// Gehirn & Psyche data: brain regions, networks, transmitter pathways, disorders, drugs, research cards and the depression/psilocybin story. Written by content agents; edit here directly.
window.PSY = {"regions":{"dlpfc":{"name":"Dorsolateraler präfrontaler Kortex (dlPFC)","view":"lat","l":1,"fn":"Arbeitsgedächtnis, Planung, Regelwechsel und kognitive Kontrolle; Kernknoten des zentralen exekutiven Netzwerks, reguliert limbische Areale top-down über ACC und vlPFC.","psych":"Depression: links oft hypoaktiv, Zielort der rTMS; Wirksamkeit hängt mit der Anti-Korrelation des Zielpunkts zum sgACC zusammen. Schizophrenie: ineffiziente Aktivierung bei Arbeitsgedächtnisaufgaben, kognitive Symptome.","fact":"Je stärker ein rTMS-Zielpunkt im dlPFC funktionell anti-korreliert mit dem sgACC ist, desto besser war die antidepressive Wirkung (Fox et al., Biol Psychiatry 2012).","q":"Welche Region wird bei Depression mit rTMS stimuliert und ist der zentrale Ort des Arbeitsgedächtnisses?","mcq":[{"q":"Warum wählt man für rTMS bei Depression einen lateral-präfrontalen Zielort, obwohl die Pathologie eher im sgACC vermutet wird?","a":"Über funktionelle Anti-Korrelation lässt sich der tiefe sgACC indirekt modulieren","w":["Der sgACC liegt direkt unter dem lateralen PFC und damit in Spulenreichweite","Der laterale PFC projiziert monosynaptisch dopaminerg zum sgACC","Die Stimulation steigert primär die Serotoninfreisetzung der Raphe-Kerne"],"why":"Fox et al. 2012: Der klinische Effekt korrelierte mit der Anti-Korrelation des Stimulationsorts zum sgACC."},{"q":"Welche Beziehung zwischen präfrontaler D1-Stimulation und Arbeitsgedächtnis beschreibt das Arnsten/Goldman-Rakic-Modell?","a":"Umgekehrtes U: zu wenig und zu viel D1-Stimulation verschlechtern die Leistung","w":["Linear: je mehr D1-Stimulation, desto besser die Leistung","U-förmig: mittlere D1-Stimulation ist am ungünstigsten","Keine Beziehung: Arbeitsgedächtnis hängt nur von D2-Rezeptoren ab"],"why":"Optimale D1-Stimulation stabilisiert persistente Aktivität; Über- und Unterstimulation (z. B. Stress) stören sie."}]},"vlpfc":{"name":"Ventrolateraler präfrontaler Kortex (vlPFC)","view":"lat","l":2,"fn":"Inhibitorische Kontrolle (v. a. rechter Gyrus frontalis inferior, Stop-Signal), Reappraisal und Emotionsregulation, links semantische Auswahl und Abruf.","psych":"ADHS: Hypoaktivierung des rechten IFG bei Inhibitionsaufgaben. Reappraisal-Defizite mit schwacher vlPFC-Amygdala-Kopplung bei Angst, Depression und Borderline. Bipolare Störung: verminderte Aktivierung bei emotionalen Aufgaben.","fact":"Läsionen des rechten Gyrus frontalis inferior verlängern die Stop-Signal-Reaktionszeit (Aron et al., Nat Neurosci 2003).","q":"Welcher präfrontale Abschnitt stoppt rechtshemisphärisch bereits begonnene Handlungen und dämpft beim Reappraisal die Amygdala?","mcq":[{"q":"Ein Rechtshänder mit Infarkt im rechten Gyrus frontalis inferior zeigt am spezifischsten welches Defizit?","a":"Verlängerte Stop-Signal-Reaktionszeit","w":["Nicht-flüssige Aphasie mit Agrammatismus","Prosopagnosie bei erhaltenem Objekterkennen","Isolierte Akalkulie mit Fingeragnosie"],"why":"Der rechte IFG ist für Antwortinhibition zentral; Aphasie und Gerstmann-Zeichen erwartet man links."}]},"ofc":{"name":"Orbitofrontaler Kortex (OFC)","view":"lat","l":2,"fn":"Repräsentiert den aktuellen Wert von Reizen und Ergebnissen, ermöglicht flexibles Umlernen (Reversal Learning); sekundäre Geschmacks- und Riechrinde verknüpft Sensorik mit Belohnungswert.","psych":"Zwangsstörung: Hyperaktivität im OFC-Striatum-Thalamus-Kreis, die sich nach erfolgreicher Therapie normalisiert. Sucht: gestörte Wertaktualisierung. Läsion: Enthemmung, impulsive Entscheidungen. Essstörungen: veränderte Belohnungsbewertung von Nahrung.","fact":"Sensorisch-spezifische Sättigung: OFC-Neurone reagieren nach Sättigung mit einem Nahrungsmittel schwächer auf dieses, nicht aber auf andere (Rolls).","q":"Welche Rindenregion kodiert sensorisch-spezifische Sättigung und wird für das Umlernen nach Kontingenzumkehr gebraucht?","mcq":[{"q":"Welche Leistung ist nach OFC-Läsion typischerweise gestört, während das erste Erlernen einer Reiz-Belohnungs-Zuordnung gelingt?","a":"Umlernen nach Umkehr der Belohnungskontingenz","w":["Erwerb einer neuen Reiz-Belohnungs-Zuordnung","Räumliches Arbeitsgedächtnis über Sekunden","Prozedurales Lernen motorischer Sequenzen"],"why":"Der OFC aktualisiert Erwartungswerte; ohne ihn bleibt die alte Wahl nach Kontingenzumkehr bestehen."},{"q":"Welcher Befund zeigt sich typischerweise im OFC von Personen mit Zwangsstörung nach erfolgreicher Behandlung?","a":"Rückgang der zuvor erhöhten Aktivität bzw. des Stoffwechsels","w":["Weitere Zunahme der Aktivität als Kompensation","Volumenzunahme ohne funktionelle Änderung","Abnahme nur unter Medikation, nicht unter Verhaltenstherapie"],"why":"PET-Studien zeigten eine Normalisierung im OFC-Caudatus-Kreis sowohl unter SSRI als auch unter Verhaltenstherapie."}]},"m1":{"name":"Primär-motorischer Kortex (Gyrus praecentralis)","view":"lat","l":1,"fn":"Willkürmotorik: Ursprung großer Teile des Tractus corticospinalis (Betz-Zellen in Schicht V), somatotop gegliedert – Bein medial im Lobulus paracentralis, Hand und Gesicht lateral.","psych":"Schlaganfall: A.-cerebri-media-Infarkt mit brachiofazial betonter, A.-cerebri-anterior-Infarkt mit beinbetonter Parese. Bei rTMS gegen Depression dient die motorische Schwelle über M1 als individuelle Referenz der Reizintensität. ALS: obere Motoneurone.","fact":"Die motorische Ruheschwelle (sichtbare Daumenzuckung bei M1-Stimulation) ist die individuelle Bezugsgröße für die Reizintensität der rTMS.","q":"Welche Rindenregion enthält die Betz-Riesenpyramidenzellen und ist somatotop als motorischer Homunkulus gegliedert?","mcq":[{"q":"Ein linksseitiger Infarkt der A. cerebri anterior führt typischerweise zu…","a":"Rechtsseitiger, beinbetonter Parese","w":["Rechtsseitiger, brachiofazial betonter Parese mit Aphasie","Linksseitiger, beinbetonter Parese","Rechtsseitiger homonymer Hemianopsie ohne Parese"],"why":"Die Beinrepräsentation von M1 liegt medial im Lobulus paracentralis und wird von der A. cerebri anterior versorgt."}]},"s1":{"name":"Primär-somatosensorischer Kortex (Gyrus postcentralis)","view":"lat","l":1,"fn":"Primäre Verarbeitung von Berührung, Vibration, Propriozeption und Schmerzlokalisation (BA 3, 1, 2), somatotop gegliedert; Afferenzen aus VPL (Körper) und VPM (Gesicht) des Thalamus.","psych":"Phantomschmerz: kortikale Reorganisation nach Amputation. Fokal-sensible Anfälle mit Jackson-Ausbreitung. Bei chronischem Schmerz und somatischer Belastungsstörung spielen eher Insel und ACC (affektive Komponente) eine Rolle.","fact":"Nach Armamputation korrelierte das Ausmaß der Reorganisation im somatosensorischen Kortex mit der Stärke des Phantomschmerzes (Flor et al., Nature 1995).","q":"Welche Rindenregion erhält ihre Hauptafferenzen aus VPL/VPM und reorganisiert sich nach Amputation?","mcq":[{"q":"Aus welchen Thalamuskernen erhält der primär-somatosensorische Kortex seine Hauptafferenzen?","a":"VPL (Körper) und VPM (Gesicht)","w":["VA und VL (Körper bzw. Gesicht)","Corpus geniculatum mediale und laterale","Nucleus anterior und mediodorsalis"],"why":"VPL/VPM sind die spezifischen somatosensorischen Relaiskerne; VA/VL sind motorisch, CGM/CGL auditiv/visuell."}]},"broca":{"name":"Broca-Areal","view":"lat","l":2,"fn":"Sprachproduktion, Syntax und artikulatorische Planung; Pars opercularis und triangularis des linken Gyrus frontalis inferior (BA 44/45), über den Fasciculus arcuatus mit dem Wernicke-Areal verbunden.","psych":"Broca-Aphasie: nicht-flüssig, Agrammatismus, gestörtes Nachsprechen, Verständnis relativ erhalten, Störungsbewusstsein – häufig begleitet von Depression nach Schlaganfall. Nicht-flüssige Variante der primär progressiven Aphasie (FTLD-Spektrum).","fact":"MRT-Nachuntersuchungen der Gehirne von Brocas Patienten zeigten Läsionen, die deutlich tiefer reichten als das heute nach Broca benannte Areal (Dronkers et al., Brain 2007).","q":"Läsion welches Areals verursacht eine nicht-flüssige Aphasie mit Agrammatismus bei relativ erhaltenem Verständnis?","mcq":[{"q":"Welches Merkmal unterscheidet eine transkortikal-motorische Aphasie von einer Broca-Aphasie?","a":"Erhaltenes Nachsprechen","w":["Erhaltenes Sprachverständnis","Nicht-flüssige Spontansprache","Gestörte Benennleistung"],"why":"Bei transkortikalen Aphasien ist der perisylvische Kreis intakt, daher gelingt Nachsprechen; Verständnis ist bei beiden relativ erhalten."}]},"wernicke":{"name":"Wernicke-Areal","view":"lat","l":2,"fn":"Sprachverständnis: Zuordnung von Lautfolgen zu Bedeutung; posteriorer Gyrus temporalis superior links (BA 22), über den Fasciculus arcuatus mit dem Broca-Areal verbunden.","psych":"Wernicke-Aphasie: flüssig, Paraphasien, Neologismen, gestörtes Verständnis, oft fehlende Einsicht – Verwechslungsgefahr mit formaler Denkstörung. Akustisch-verbale Halluzinationen gehen mit Aktivität im linken superioren Temporalkortex einher.","fact":"Eine Läsion des Fasciculus arcuatus erzeugt die Leitungsaphasie: flüssige Sprache, gutes Verständnis, aber deutlich gestörtes Nachsprechen.","q":"Welches Areal ist bei Läsion für flüssige Aphasie mit Neologismen und gestörtem Verständnis verantwortlich?","mcq":[{"q":"Ein 70-Jähriger spricht plötzlich flüssig, aber inhaltsleer mit Neologismen und wirkt unbekümmert. Was ist differenzialdiagnostisch vorrangig?","a":"Linkstemporaler Infarkt mit Wernicke-Aphasie statt neuer Psychose","w":["Rechtsfrontaler Infarkt mit Antriebsstörung und Mutismus","Spätschizophrenie, da Aphasien das Verständnis nie betreffen","Leitungsaphasie durch Läsion des Fasciculus arcuatus"],"why":"Akuter Beginn, Neologismen und gestörtes Verständnis im Alter sprechen für einen Schlaganfall; Leitungsaphasie hätte gutes Verständnis."}]},"a1":{"name":"Primäre Hörrinde (Heschl-Querwindungen)","view":"lat","l":2,"fn":"Primäre Hörverarbeitung, tonotop gegliedert; Afferenzen aus dem Corpus geniculatum mediale; jede Seite erhält Input beider Ohren.","psych":"Schizophrenie: verminderte Mismatch Negativity (MMN) als robuster, NMDA-abhängiger Biomarker; akustische Halluzinationen gehen mit Aktivierung des auditorischen Kortex einher. Tinnitus: zentrale Hyperaktivität nach Hörverlust.","fact":"Ketamin vermindert bei Gesunden die Mismatch Negativity und ahmt damit einen Schizophrenie-Befund nach (Umbricht et al., Arch Gen Psychiatry 2000).","q":"Welche tonotop gegliederte Rindenregion erhält ihre Afferenzen aus dem Corpus geniculatum mediale?","mcq":[{"q":"Warum führt eine einseitige Läsion der primären Hörrinde meist nicht zu einseitiger Taubheit?","a":"Die Hörbahn projiziert ab dem Hirnstamm bilateral","w":["Die Hörbahn kreuzt vollständig in der Medulla","Das Corpus geniculatum laterale übernimmt","Der Temporalpol übernimmt die Tonotopie"],"why":"Ab dem Nucleus cochlearis verlaufen Fasern beidseits (obere Olive, Lemniscus lateralis), daher erhält jede Hörrinde Input beider Ohren."},{"q":"Die Mismatch Negativity ist bei Schizophrenie vermindert. Welche Rezeptorblockade ahmt das bei Gesunden am besten nach?","a":"NMDA-Rezeptor-Blockade","w":["5-HT2A-Rezeptor-Aktivierung","D2-Rezeptor-Blockade","GABA-B-Rezeptor-Blockade"],"why":"Ketamin reduziert die MMN, Psilocybin dagegen kaum – ein Argument für die Glutamathypothese."}]},"ppc":{"name":"Posteriorer parietaler Kortex (inkl. Gyrus angularis)","view":"lat","l":2,"fn":"Räumliche Aufmerksamkeit, multisensorische Integration und Handlungsplanung (Greifen, Sakkaden); der Gyrus angularis dient Lesen, Rechnen und semantischer Integration und ist ein DMN-Knoten.","psych":"Rechts: Neglect. Links (Gyrus angularis): Gerstmann-Syndrom. Alzheimer: früher temporoparietaler Hypometabolismus. Intraparietaler Sulcus gehört zum exekutiven Netz, Gyrus angularis zum DMN – beide bei Schizophrenie und Depression verändert.","fact":"Im FDG-PET zeigt die Alzheimer-Krankheit typischerweise früh einen temporoparietalen und posterior-cingulären Hypometabolismus.","q":"Läsion welcher Region verursacht rechts einen Neglect und links ein Gerstmann-Syndrom?","mcq":[{"q":"Welches Symptom gehört NICHT zum Gerstmann-Syndrom?","a":"Alexie ohne Agraphie","w":["Akalkulie","Fingeragnosie","Rechts-links-Desorientierung"],"why":"Die Gerstmann-Tetrade umfasst Agraphie, Akalkulie, Fingeragnosie und Rechts-links-Störung; reine Alexie entsteht okzipital mit Splenium-Beteiligung."}]},"v1":{"name":"Primäre Sehrinde (V1)","view":"lat","l":1,"fn":"Primäre Sehrinde am Sulcus calcarinus (BA 17): retinotop gegliedert, Afferenzen aus dem Corpus geniculatum laterale; verarbeitet Orientierung, Kontrast und okuläre Dominanz.","psych":"Charles-Bonnet-Syndrom: komplexe visuelle Halluzinationen bei Sehverlust ohne Psychose. Lewy-Körper-Demenz: okzipitaler Hypometabolismus und visuelle Halluzinationen. Unter LSD korrelierten visuelle Effekte mit veränderter V1-Konnektivität.","fact":"Die Lewy-Körper-Demenz zeigt im FDG-PET okzipitalen Hypometabolismus einschließlich der primären Sehrinde, die bei Alzheimer typischerweise ausgespart bleibt.","q":"Welche retinotop gegliederte Rindenregion am Sulcus calcarinus erhält Input aus dem Corpus geniculatum laterale?","mcq":[{"q":"Ein Infarkt der rechten A. cerebri posterior verursacht typischerweise…","a":"Homonyme Hemianopsie nach links mit Makulaaussparung","w":["Bitemporale Hemianopsie","Homonyme Hemianopsie nach rechts mit Makulaaussparung","Monokulare Erblindung rechts"],"why":"Die rechte Sehrinde verarbeitet das linke Gesichtsfeld; der Okzipitalpol erhält oft Kollateralen aus der A. cerebri media."},{"q":"Welche Konstellation spricht bei komplexen visuellen Halluzinationen eines älteren Menschen am ehesten für ein Charles-Bonnet-Syndrom?","a":"Schwerer Visusverlust, erhaltene Einsicht, keine weiteren psychotischen Symptome","w":["Fluktuierende Kognition, Parkinsonismus, REM-Schlaf-Verhaltensstörung","Akuter Beginn, Aufmerksamkeitsstörung, Bewusstseinstrübung","Wahn, kommentierende Stimmen und fehlende Krankheitseinsicht"],"why":"Die Distraktoren beschreiben Lewy-Körper-Demenz, Delir und Psychose; Charles-Bonnet ist eine Deafferenzierungsfolge."}]},"temppol":{"name":"Temporalpol","view":"lat","l":3,"fn":"Semantisches Wissen über Personen und Objekte, soziale und emotionale Konzepte; Konvergenzzone, über den Fasciculus uncinatus mit OFC und Amygdala verbunden.","psych":"Semantische Variante der primär progressiven Aphasie: anteriore temporale Atrophie, meist links. Rechtsbetont: Prosopagnosie für bekannte Personen und Verhaltensänderungen. Bilaterale anteriore Temporalläsion: Klüver-Bucy-Syndrom.","fact":"Die semantische Variante der PPA ist überwiegend mit TDP-43-Pathologie (Typ C) assoziiert, nicht mit Tau oder Amyloid.","q":"Atrophie welcher Region kennzeichnet die semantische Variante der primär progressiven Aphasie?","mcq":[{"q":"Welches Profil passt zur semantischen Variante der primär progressiven Aphasie?","a":"Flüssige Sprache, gestörtes Benennen und Wortverständnis, Nachsprechen erhalten","w":["Agrammatismus und Sprechapraxie bei erhaltenem Einzelwortverständnis","Wortfindungsstörung und gestörtes Nachsprechen langer Sätze","Flüssige Sprache, gestörtes Nachsprechen, gutes Wortverständnis"],"why":"Die Distraktoren beschreiben die nicht-flüssige und die logopenische Variante sowie eine Leitungsaphasie."}]},"insula":{"name":"Inselrinde (Insula)","view":"lat","l":1,"fn":"Interozeption (Herzschlag, Hunger, Ekel, Schmerzaffekt), primäre Geschmacksrinde, Integration von Körpersignalen mit Emotion; die anteriore Insel ist Kernknoten des Salienznetzwerks.","psych":"Angst: Hyperaktivität bei Antizipation. Sucht: Raucher mit Insel-Läsion verloren oft das Rauchverlangen. Anorexia nervosa: veränderte interozeptive und Geschmacksverarbeitung. Depression: Insel-Metabolismus als möglicher Prädiktor der Therapiewahl.","fact":"Raucher mit Läsion der Insel hörten deutlich häufiger mühelos und ohne Verlangen auf zu rauchen als Raucher mit anderen Läsionen (Naqvi et al., Science 2007).","q":"Welche Rindenregion ist erst nach Abspreizen der Opercula sichtbar und verarbeitet Interozeption und Geschmack?","mcq":[{"q":"Vor Therapie zeigt das PET bei Depression einen Hypometabolismus der anterioren Insel. Was berichteten McGrath et al. (2013)?","a":"Eher Remission unter KVT, eher schlechtes Ansprechen auf Escitalopram","w":["Eher Remission unter Escitalopram, eher schlechtes Ansprechen auf KVT","Gleich gutes Ansprechen auf KVT und Escitalopram","Kein Zusammenhang mit dem Ansprechen auf beide Therapien"],"why":"Insel-Hypometabolismus sagte Remission unter KVT voraus, Hypermetabolismus Remission unter Escitalopram."},{"q":"Wo liegt die primäre Geschmacksrinde?","a":"Anteriore Insel und frontales Operculum","w":["Orbitofrontaler Kortex","Gesichtsareal des Gyrus postcentralis","Nucleus tractus solitarii"],"why":"Der OFC ist sekundäre Geschmacksrinde, der NTS die erste zentrale Relaisstation im Hirnstamm."}]},"cerebellum":{"name":"Kleinhirn (Cerebellum)","view":"lat","l":1,"fn":"Koordination, Feinabstimmung und motorisches Lernen über Fehlersignale (Kletterfasern aus der unteren Olive); über Kleinhirn-Thalamus-Kortex-Schleifen auch kognitive und affektive Funktionen.","psych":"Zerebelläres kognitiv-affektives Syndrom (Schmahmann) bei Läsionen des Hinterlappens. Chronischer Alkoholkonsum: Atrophie des anterioren Vermis. Lithium-Intoxikation: Ataxie, Dysarthrie, grober Tremor. Autismus: Befunde zu Purkinjezellen.","fact":"Purkinjezellen sind die einzigen Ausgangsneurone der Kleinhirnrinde und hemmen die Kleinhirnkerne GABAerg.","q":"Welche Struktur verursacht bei Läsion ihres Hinterlappens das kognitiv-affektive Syndrom nach Schmahmann?","mcq":[{"q":"Chronischer Alkoholkonsum betrifft im Kleinhirn bevorzugt…","a":"Den anterioren superioren Vermis mit Stand- und Gangataxie","w":["Die Hemisphären mit Intentionstremor der Arme","Den Flocculonodulus mit Nystagmus und Schwindel","Die Nuclei dentati mit Myoklonien"],"why":"Die alkoholische Kleinhirndegeneration betrifft typischerweise den anterior-superioren Vermis; die Arme bleiben relativ verschont."},{"q":"Woher stammen die Kletterfasern des Kleinhirns?","a":"Aus der unteren Olive","w":["Aus den Brückenkernen","Aus dem Nucleus ruber","Aus dem Nucleus dentatus"],"why":"Brückenkerne liefern Moosfasern, der Nucleus dentatus ist ein Ausgangskern; Kletterfasern übertragen Fehlersignale."}]},"brainstem":{"name":"Hirnstamm (Mittelhirn, Pons, Medulla)","view":"med","l":1,"fn":"Vitale Steuerung (Atmung, Kreislauf), Hirnnervenkerne, Formatio reticularis (aufsteigendes Wecksystem) und Ursprung der monoaminergen Systeme: Raphe, Locus coeruleus, VTA und Substantia nigra.","psych":"Ursprung der Monoamin-Bahnen, an denen die meisten Psychopharmaka ansetzen. Area postrema (ohne Blut-Hirn-Schranke): Übelkeit unter SSRI, Opioiden und GLP-1-RA. Ventraler Ponsinfarkt: Locked-in-Syndrom, nicht mit Koma zu verwechseln.","fact":"Die Area postrema am Boden des 4. Ventrikels liegt außerhalb der Blut-Hirn-Schranke und vermittelt Übelkeit u. a. über 5-HT3- und D2-Rezeptoren.","q":"Welcher Hirnabschnitt beherbergt die Formatio reticularis und die Ursprungskerne von Serotonin und Noradrenalin?","mcq":[{"q":"Warum verursachen SSRI zu Behandlungsbeginn häufig Übelkeit?","a":"Akuter Serotoninanstieg aktiviert 5-HT3-Rezeptoren in Area postrema und Darm","w":["Blockade von 5-HT2A-Rezeptoren in der Medulla oblongata","Agonismus an D2-Rezeptoren im Nucleus tractus solitarii","Blockade von H1-Rezeptoren in den Vestibulariskernen"],"why":"5-HT3-Antagonisten wie Ondansetron wirken genau an dieser Stelle; die Übelkeit lässt meist durch Adaptation nach."},{"q":"Nach Basilaris-Verschluss ist ein Patient wach, kann aber nur vertikale Augenbewegungen und Lidschluss ausführen. Läsionsort?","a":"Ventrale Pons beidseits","w":["Mittelhirnhaube mit Formatio reticularis","Paramedianer Thalamus beidseits","Dorsolaterale Medulla (Wallenberg)"],"why":"Locked-in: Kortikospinale/-bulbäre Bahnen sind unterbrochen, Formatio reticularis und vertikale Blickzentren im Mittelhirn bleiben intakt."}]},"vmpfc":{"name":"Ventromedialer präfrontaler Kortex (vmPFC)","view":"med","l":2,"fn":"Wertbasierte Entscheidungen, Integration von Emotion in Urteile, selbstbezogenes Denken und Abruf der Furchtextinktion durch Hemmung der Amygdala; anteriorer Knoten des DMN.","psych":"Depression: erhöhte Aktivität bei Rumination und Selbstbezug. PTBS: verminderte Aktivität, gestörter Extinktionsabruf. Psilocybin akut: verminderte Aktivität und mPFC-PCC-Kopplung. Läsion: Defizite in somatischen Markern.","fact":"Patienten mit vmPFC-Läsion entwickelten im Iowa Gambling Task keine antizipatorischen Hautleitwertreaktionen vor riskanten Wahlen (Bechara et al., Science 1997).","q":"Welche Region ist für den Abruf der Furchtextinktion nötig und zeigt bei Läsion typische Defizite im Iowa Gambling Task?","mcq":[{"q":"Der gestörte Extinktionsabruf bei PTBS wird vor allem welcher Konstellation zugeschrieben?","a":"Zu schwache vmPFC-Hemmung einer hyperreaktiven Amygdala","w":["Zu starke vmPFC-Hemmung einer hypoaktiven Amygdala","Hyperaktiver dlPFC mit überschießendem Reappraisal","Verstärkter hippocampaler Kontextinput an den vmPFC"],"why":"Bildgebung zeigt bei PTBS eine verminderte vmPFC- und eine erhöhte Amygdala-Aktivität; Hippocampus-Kontextverarbeitung ist eher geschwächt."},{"q":"Welcher akute Befund wurde in der Bildgebungsstudie von Carhart-Harris et al. (PNAS 2012) unter Psilocybin berichtet?","a":"Verminderter Blutfluss und verminderte Kopplung in mPFC und PCC","w":["Erhöhter Blutfluss und verstärkte Kopplung in mPFC und PCC","Selektive Aktivierung des Nucleus accumbens ohne Kortexeffekt","Unveränderte Kortexaktivität bei erhöhter Amygdala-Aktivität"],"why":"Die Studie fand Abnahmen in Hub-Regionen wie mPFC und PCC – entgegen der Erwartung einer globalen Aktivierung."}]},"sgacc":{"name":"Subgenualer anteriorer cingulärer Kortex (sgACC, BA 25)","view":"med","l":3,"fn":"Viszeromotorische und autonome Regulation, Stimmung und Antrieb; eng verbunden mit Hypothalamus, Amygdala, Nucleus accumbens und Hirnstamm.","psych":"Depression: Hyperaktivität in akuter Episode, Rückgang nach Ansprechen; Volumenminderung bei familiärer affektiver Störung. Erster Zielort der Tiefen Hirnstimulation bei therapieresistenter Depression. Indirekter Zielort der rTMS über den dlPFC.","fact":"Die erste offene Studie zur Tiefen Hirnstimulation bei therapieresistenter Depression zielte auf die weiße Substanz des subgenualen Cingulums (Mayberg et al., Neuron 2005).","q":"Welche Region war das Ziel der ersten THS-Studie bei therapieresistenter Depression und ist in akuter Depression hyperaktiv?","mcq":[{"q":"Welche Erklärung für das Scheitern der randomisierten BROADEN-Studie (subgenuale THS) wird am häufigsten diskutiert?","a":"Uneinheitliche Elektrodenlage relativ zu den entscheidenden Faserbündeln","w":["Fehlende Hyperaktivität des sgACC bei therapieresistenter Depression","Hohe Infektionsrate, die zum Abbruch der Studie zwang","Nachgewiesene Stimmungsverschlechterung unter aktiver Stimulation"],"why":"Traktografie-Daten (Riva-Posse 2014) verbanden Ansprechen mit der Erfassung konvergierender Bahnen; daraus entstand die traktografiegestützte Planung."},{"q":"Welcher Befund zum sgACC ist in Bildgebungsstudien depressiver Patienten am konsistentesten?","a":"Erhöhte Aktivität in akuter Depression, Abnahme nach Ansprechen","w":["Erniedrigte Aktivität in akuter Depression, Anstieg nach Ansprechen","Unveränderte Aktivität bei Volumenzunahme unter Therapie","Erhöhte Aktivität nur in Manie, nicht in Depression"],"why":"Die Normalisierung einer Hyperaktivität ist ein wiederkehrender Befund unter verschiedenen Therapien."}]},"dacc":{"name":"Dorsaler anteriorer cingulärer Kortex (dACC)","view":"med","l":2,"fn":"Konfliktüberwachung, Fehlerdetektion, Abwägung von Aufwand und Nutzen, affektive Komponente von Schmerz; gemeinsam mit der anterioren Insel Kern des Salienznetzwerks.","psych":"Zwangsstörung: vergrößerte Error-Related Negativity und Hyperaktivität; anteriore Cingulotomie als Läsionsverfahren bei therapierefraktärer Zwangsstörung. Schizophrenie: verminderte ERN. Transdiagnostischer Graue-Substanz-Verlust gemeinsam mit der Insel.","fact":"Die Error-Related Negativity, ein frontozentrales EEG-Potenzial unmittelbar nach Fehlern, entsteht vermutlich im dACC und ist bei Zwangsstörung vergrößert.","q":"Welche Region erzeugt die Error-Related Negativity und bildet mit der anterioren Insel den Kern des Salienznetzwerks?","mcq":[{"q":"Welches Läsionsverfahren bei therapierefraktärer Zwangsstörung zielt auf den cingulären Kortex?","a":"Anteriore Cingulotomie","w":["Anteriore Kapsulotomie","Subkaudale Traktotomie","Bilaterale Amygdalotomie"],"why":"Die Kapsulotomie zielt auf den vorderen Kapselschenkel, die subkaudale Traktotomie auf Fasern unter dem Caudatus."},{"q":"Welches EEG-Maß ist bei Zwangsstörung im Vergleich zu Gesunden typischerweise vergrößert?","a":"Error-Related Negativity (ERN)","w":["Mismatch Negativity (MMN)","P300 auf Zielreize","Dichte der Schlafspindeln"],"why":"Die vergrößerte ERN gilt als Marker überaktiver Fehlerüberwachung, auch bei unbelasteten Angehörigen."}]},"pcc":{"name":"Posteriorer cingulärer Kortex (PCC)","view":"med","l":2,"fn":"Zentraler Hub des Default-Mode-Netzwerks: autobiografisches Gedächtnis, Selbstbezug, Gedankenwandern; sehr hohe Ruhe-Stoffwechselrate, eng verbunden mit Hippocampus und Präcuneus.","psych":"Alzheimer: früher Hypometabolismus und Amyloidablagerung. Depression: erhöhte DMN-Konnektivität mit Rumination. Psilocybin akut: verminderte Aktivität und DMN-Integrität. Lewy-Körper-Demenz: relativ erhaltener Metabolismus.","fact":"Das cingulate island sign – relativ erhaltener PCC-Metabolismus im FDG-PET bei okzipitalem Hypometabolismus – spricht für Lewy-Körper-Demenz statt Alzheimer.","q":"Welcher mediale Kortexabschnitt ist der metabolisch aktivste DMN-Hub und zeigt bei Alzheimer früh Hypometabolismus?","mcq":[{"q":"Das cingulate island sign im FDG-PET spricht am ehesten für…","a":"Lewy-Körper-Demenz","w":["Alzheimer-Krankheit","Behaviorale frontotemporale Demenz","Creutzfeldt-Jakob-Krankheit"],"why":"Bei Alzheimer ist der PCC früh hypometabol; bei Lewy-Körper-Demenz bleibt er relativ ausgespart, während okzipital der Stoffwechsel sinkt."}]},"precuneus":{"name":"Präcuneus","view":"med","l":3,"fn":"Visuell-räumliche Vorstellung, episodischer Abruf, Selbstbewusstsein und Perspektivübernahme; posteriorer medialer DMN-Knoten im Parietallappen.","psych":"Alzheimer: einer der frühesten Amyloid-Ablagerungsorte; Atrophie bei posteriorer kortikaler Atrophie und früh beginnender Alzheimer-Krankheit. Wird in Tiefschlaf und Narkose deaktiviert – Thema der Bewusstseinsforschung.","fact":"Die früheste Amyloid-Akkumulation findet sich in DMN-Regionen wie Präcuneus, mPFC und PCC (Palmqvist et al., Nat Commun 2017).","q":"Welche medial-parietale Region gehört zu den frühesten Amyloid-Ablagerungsorten bei Alzheimer?","mcq":[{"q":"Bei welcher Alzheimer-Variante stehen früh visuell-räumliche Defizite mit betonter parietookzipitaler Atrophie im Vordergrund?","a":"Posteriore kortikale Atrophie","w":["Logopenische Variante der PPA","Frontale (dysexekutive) Variante","Limbisch-prädominante Variante"],"why":"Die posteriore kortikale Atrophie betrifft Präcuneus und parietookzipitalen Kortex; das Gedächtnis bleibt anfangs relativ erhalten."}]},"cc":{"name":"Balken (Corpus callosum)","view":"med","l":1,"fn":"Größte Kommissur: verbindet homologe Kortexareale beider Hemisphären (Rostrum, Genu, Truncus, Splenium) und ermöglicht den interhemisphärischen Informationstransfer.","psych":"Callosotomie bei therapierefraktärer Epilepsie mit Sturzanfällen: Diskonnexionssyndrom. Marchiafava-Bignami-Krankheit bei Alkohol und Mangelernährung. Splenium-Läsion: Alexie ohne Agraphie. Multiple Sklerose: Läsionen senkrecht zum Balken.","fact":"Die Marchiafava-Bignami-Krankheit, eine Demyelinisierung und Nekrose des Balkens, tritt v. a. bei chronischem Alkoholkonsum mit Mangel an B-Vitaminen auf.","q":"Welche Struktur wird bei der Marchiafava-Bignami-Krankheit demyelinisiert?","mcq":[{"q":"Alexie ohne Agraphie entsteht klassisch durch eine Läsion von…","a":"Linker Sehrinde plus Splenium des Balkens","w":["Linkem Gyrus angularis allein","Genu des Balkens plus rechtem Frontallappen","Linkem Fasciculus arcuatus"],"why":"Visuelle Information aus der rechten Sehrinde erreicht die linken Sprachareale nicht mehr; eine Angularis-Läsion verursacht Alexie mit Agraphie."}]},"thalamus":{"name":"Thalamus","view":"med","l":1,"fn":"Relais und Filter für fast alle sensorischen Signale zum Kortex (außer Riechen); Kerne für Motorik (VA/VL), Limbik (anterior, mediodorsal), Aufmerksamkeit (Pulvinar); Nucleus reticularis taktet Schlafspindeln.","psych":"Schizophrenie: gestörte thalamokortikale Konnektivität, verminderte Schlafspindeln. Korsakow: mediodorsaler und anteriorer Thalamus. Psychedelika: CSTC-Modell eines geschwächten thalamischen Filters (Vollenweider). Fatale familiäre Insomnie.","fact":"Die fatale familiäre Insomnie ist eine erbliche Prionerkrankung (PRNP D178N mit Methionin an Codon 129), die v. a. anteriore und mediodorsale Thalamuskerne zerstört.","q":"Welche Struktur filtert sensorische Signale vor dem Kortex und wird bei der fatalen familiären Insomnie zerstört?","mcq":[{"q":"Welcher Thalamuskern gehört zum klassischen Papez-Kreis?","a":"Nucleus anterior","w":["Nucleus mediodorsalis","Pulvinar","Nucleus ventralis anterior"],"why":"Der Tractus mammillothalamicus endet im Nucleus anterior, der zum Gyrus cinguli projiziert."},{"q":"Ein bilateraler paramedianer Thalamusinfarkt (A. Percheron) führt typischerweise zu…","a":"Vigilanzminderung, vertikaler Blickparese und Gedächtnisstörung","w":["Halbseitigem Ballismus mit ausfahrenden Hyperkinesen","Kontralateraler Hemihypästhesie mit zentralem Schmerz","Isolierter homonymer Quadrantenanopsie"],"why":"Ballismus entsteht im Nucleus subthalamicus, Dejerine-Roussy-Schmerz im lateralen Thalamus (VPL)."}]},"hypothal":{"name":"Hypothalamus","view":"med","l":1,"fn":"Homöostase: Energiebilanz (Nucleus arcuatus mit POMC- und AgRP-Neuronen), Temperatur, Osmolalität, zirkadianer Taktgeber (SCN), Stressachse (PVN mit CRH), Schlaf-Wach-Steuerung (Orexin, Histamin).","psych":"Depression: CRH-Hyperaktivität und gestörte Rückkopplung. Narkolepsie Typ 1: Verlust lateraler Orexin-Neurone. Anorexia nervosa: hypothalamische Amenorrhoe. GLP-1-RA wirken u. a. über Nucleus arcuatus und Hirnstamm auf die Sättigung.","fact":"Der Nucleus suprachiasmaticus erhält Licht-Information über den retinohypothalamischen Trakt von melanopsinhaltigen retinalen Ganglienzellen.","q":"Welche Region enthält den Nucleus suprachiasmaticus, den Nucleus arcuatus und den Nucleus paraventricularis?","mcq":[{"q":"Welche Neuronenpopulationen im Nucleus arcuatus wirken gegensätzlich auf die Nahrungsaufnahme?","a":"POMC/CART-Neurone (anorexigen) vs. AgRP/NPY-Neurone (orexigen)","w":["Orexin-Neurone (anorexigen) vs. MCH-Neurone (orexigen)","CRH-Neurone (orexigen) vs. TRH-Neurone (anorexigen)","AgRP/NPY-Neurone (anorexigen) vs. POMC/CART-Neurone (orexigen)"],"why":"Leptin aktiviert POMC- und hemmt AgRP-Neurone; Orexin und MCH liegen im lateralen Hypothalamus und fördern beide das Essen."},{"q":"Was zeigt ein pathologischer kombinierter Dexamethason/CRH-Test bei Depression?","a":"Gestörte Glukokortikoid-Rückkopplung mit überschießender Cortisolantwort","w":["Primäre Nebennierenrindeninsuffizienz","Erhöhte Sensitivität der Glukokortikoidrezeptoren","Erniedrigte CRH-Aktivität des Hypothalamus"],"why":"Trotz Dexamethason-Vorbehandlung steigen ACTH und Cortisol auf CRH stark an – Ausdruck verminderter GR-Rückkopplung."}]},"hypophyse_p":{"name":"Hypophyse","view":"med","l":1,"fn":"Hormondrüse: Vorderlappen (ACTH, TSH, LH/FSH, GH, Prolaktin) wird über das Pfortadersystem hypothalamisch gesteuert; der Hinterlappen setzt ADH und Oxytocin aus hypothalamischen Axonen frei.","psych":"Hyperprolaktinämie unter D2-Antagonisten: Galaktorrhoe, Amenorrhoe, sexuelle Dysfunktion, Osteoporose. ACTH-produzierendes Adenom (Morbus Cushing): Depression, Psychose. Lithium verursacht Polyurie über die Niere, nicht über die Hypophyse.","fact":"Die Hypophyse liegt außerhalb der Blut-Hirn-Schranke; Antipsychotika mit schlechter Hirngängigkeit wie Risperidon und Amisulprid erhöhen Prolaktin daher besonders stark.","q":"Welche Drüse liegt außerhalb der Blut-Hirn-Schranke und reagiert auf D2-Blockade mit vermehrter Prolaktinfreisetzung?","mcq":[{"q":"Welches Antipsychotikum senkt eine bestehende Hyperprolaktinämie eher, statt sie zu verstärken?","a":"Aripiprazol (D2-Partialagonist)","w":["Amisulprid (selektiver D2/D3-Antagonist)","Paliperidon (aktiver Risperidon-Metabolit)","Haloperidol (hochpotentes Butyrophenon)"],"why":"Als Partialagonist aktiviert Aripiprazol laktotrophe D2-Rezeptoren ausreichend, um Prolaktin zu senken."},{"q":"Die Polyurie unter Lithium beruht hauptsächlich auf…","a":"Verminderter ADH-Wirkung am Sammelrohr der Niere","w":["Verminderter ADH-Freisetzung aus der Neurohypophyse","Erhöhter Oxytocin-Freisetzung aus der Neurohypophyse","Primärer Polydipsie durch Reizung des Durstzentrums"],"why":"Lithium gelangt über ENaC in Sammelrohrzellen und stört die Aquaporin-2-Expression: nephrogener Diabetes insipidus."}]},"habenula":{"name":"Habenula","view":"med","l":4,"fn":"Epithalamischer Kern: die laterale Habenula kodiert Enttäuschung (negativen Belohnungsvorhersagefehler) und hemmt über den RMTg dopaminerge VTA- und serotonerge Raphe-Neurone; die mediale Habenula moduliert Aversion und Nikotinentzug.","psych":"Depression: im Tiermodell Burst-Feuern der lateralen Habenula, das Ketamin über NMDA-Blockade unterdrückt. Experimenteller THS-Zielort bei therapieresistenter Depression. Mediale Habenula: α5-nAChR und Begrenzung der Nikotinaufnahme.","fact":"Neurone der lateralen Habenula feuern, wenn eine erwartete Belohnung ausbleibt – spiegelbildlich zu Dopaminneuronen (Matsumoto & Hikosaka, Nature 2007).","q":"Welcher epithalamische Kern feuert bei ausbleibender Belohnung und hemmt indirekt die Dopaminneurone der VTA?","mcq":[{"q":"Über welche Zwischenstation hemmt die laterale Habenula dopaminerge VTA-Neurone hauptsächlich?","a":"GABAerger rostromedialer tegmentaler Nucleus (RMTg)","w":["Glutamaterge Projektion des Nucleus accumbens","Cholinerger Nucleus pedunculopontinus","Serotonerger Nucleus raphe dorsalis"],"why":"Glutamaterge Habenula-Neurone aktivieren den GABAergen RMTg, der VTA-Dopaminneurone hemmt."},{"q":"Welcher Mechanismus erklärte bei Yang et al. (Nature 2018) die schnelle antidepressive Ketaminwirkung in der lateralen Habenula?","a":"Blockade NMDA-abhängiger Burst-Entladungen","w":["Aktivierung von 5-HT2A-Rezeptoren auf Habenula-Neuronen","Hemmung der Serotoninwiederaufnahme an Habenula-Terminalen","Direkter Agonismus an μ-Opioid-Rezeptoren der Habenula"],"why":"Im Nagermodell feuerten Habenula-Neurone vermehrt in Bursts; Ketamin blockierte die dafür nötigen NMDA-Ströme."}]},"hippocampus":{"name":"Hippocampus","view":"med","l":1,"fn":"Episodisches und räumliches Gedächtnis (Ortszellen), Kontextverarbeitung und Konsolidierung; adulte Neurogenese im Gyrus dentatus; Rückkopplung der HPA-Achse über Glukokortikoid- und Mineralokortikoidrezeptoren.","psych":"Depression: Volumenminderung v. a. bei rezidivierendem Verlauf. Alzheimer: frühe Atrophie. Schizophrenie: Hypermetabolismus in CA1 in frühen Stadien. Temporallappenepilepsie: Ammonshornsklerose. HSV-Enzephalitis: mediotemporal.","fact":"In der ENIGMA-Analyse war das Hippocampusvolumen v. a. bei rezidivierender Depression und frühem Erkrankungsbeginn vermindert, nicht bei Ersterkrankung (Schmaal et al., Mol Psychiatry 2016).","q":"Welche Struktur enthält Ortszellen, zeigt adulte Neurogenese und bremst die HPA-Achse über Glukokortikoidrezeptoren?","mcq":[{"q":"Welche Patientengruppe zeigte in der ENIGMA-Depressionsanalyse (2016) ein vermindertes Hippocampusvolumen?","a":"Rezidivierende Depression mit frühem Erkrankungsbeginn","w":["Ersterkrankte unabhängig vom Erkrankungsalter","Ausschließlich unbehandelte Ersterkrankte","Ausschließlich Personen mit Erkrankungsbeginn im höheren Alter"],"why":"Der Effekt wurde vor allem von rezidivierenden Verläufen und frühem Beginn getragen; Ersterkrankte unterschieden sich nicht signifikant."},{"q":"Welches Hippocampus-Subfeld zeigte in frühen Psychosestadien zuerst Hypermetabolismus (Schobel et al., Neuron 2013)?","a":"CA1","w":["CA3","Gyrus dentatus","Subiculum"],"why":"Der Hypermetabolismus begann in CA1, breitete sich zum Subiculum aus und war im Tiermodell glutamatgetrieben."}]},"entorhinal":{"name":"Entorhinaler Kortex","view":"med","l":3,"fn":"Haupteingang und -ausgang des Hippocampus (Tractus perforans zum Gyrus dentatus); enthält Gitterzellen für räumliche Navigation; Schnittstelle zwischen Neokortex und Hippocampus.","psych":"Alzheimer: Tau-Neurofibrillen beginnen transentorhinal (Braak I–II), lange vor klinischen Symptomen; frühe Atrophie im MRT. Schizophrenie: Hinweise auf veränderte Zytoarchitektur, der Befund ist umstritten.","fact":"Gitterzellen im entorhinalen Kortex wurden 2005 beschrieben (Hafting et al., Nature); 2014 erhielten May-Britt und Edvard Moser mit John O’Keefe den Nobelpreis.","q":"Welche Region enthält Gitterzellen und ist nach Braak der früheste kortikale Ort der Tau-Neurofibrillen?","mcq":[{"q":"In welchen Braak-Stadien ist die neurofibrilläre Tau-Pathologie noch weitgehend auf die (trans)entorhinale Region beschränkt?","a":"I–II","w":["III–IV","V–VI","I–IV"],"why":"In III–IV ist das limbische System betroffen, in V–VI der Neokortex."},{"q":"Welche Bahn verbindet den entorhinalen Kortex mit dem Gyrus dentatus?","a":"Tractus perforans","w":["Fornix","Moosfasern","Schaffer-Kollateralen"],"why":"Moosfasern ziehen vom Gyrus dentatus zu CA3, Schaffer-Kollateralen von CA3 zu CA1; der Fornix ist ein Ausgang."}]},"amygdala":{"name":"Amygdala (Mandelkern)","view":"med","l":1,"fn":"Bewertung von Bedrohung und emotionaler Salienz, Furchtkonditionierung (basolateral: Assoziation; zentral: Ausgang zu Hypothalamus und Hirnstamm), Verstärkung emotionaler Gedächtnisinhalte.","psych":"Angststörungen, PTBS: Hyperreaktivität. Depression: verstärkte Reaktion auf negative Gesichter, unter SSRI früh abgeschwächt. Nach Psilocybin-Therapie wurde veränderte Amygdala-Reaktivität berichtet. Urbach-Wiethe: bilaterale Verkalkung.","fact":"Patientin S. M. mit bilateraler Amygdala-Läsion zeigte kaum Furcht vor äußeren Bedrohungen, erlebte aber bei CO2-Inhalation Panik (Feinstein et al., Nat Neurosci 2013).","q":"Welche Struktur ist für Furchtkonditionierung nötig und beim Urbach-Wiethe-Syndrom bilateral verkalkt?","mcq":[{"q":"Was erlebten Personen mit bilateraler Amygdala-Läsion bei CO2-Inhalation?","a":"Panikattacken – interozeptive Furcht ist ohne Amygdala möglich","w":["Keine Angst – die Amygdala ist für jede Form von Furcht nötig","Nur autonome Reaktionen ohne subjektives Angsterleben","Ausschließlich Ekel, da die Insel die Furcht ersetzt"],"why":"Der Befund zeigt, dass Furcht vor inneren Bedrohungen über Hirnstamm und Insel auch ohne Amygdala entstehen kann."},{"q":"Welcher Amygdala-Anteil ist der wichtigste Ausgang zu Hypothalamus und periaquäduktalem Grau?","a":"Nucleus centralis","w":["Nucleus basolateralis","Nucleus corticalis","Interkalierte Zellmassen"],"why":"Der basolaterale Komplex bildet Assoziationen, interkalierte Zellen hemmen bei Extinktion den Nucleus centralis."}]},"nacc":{"name":"Nucleus accumbens (ventrales Striatum)","view":"med","l":2,"fn":"Ventrales Striatum: Schnittstelle zwischen Motivation und Handlung; erhält mesolimbisches Dopamin und glutamaterge Inputs aus PFC, Amygdala und Hippocampus; gegliedert in Kern (core) und Schale (shell).","psych":"Sucht: missbrauchte Substanzen erhöhen bevorzugt das Dopamin im NAcc. Depression: Anhedonie mit verminderter Aktivierung bei Belohnungsantizipation. THS-Zielort bei Zwangsstörung und experimentell bei Depression.","fact":"Von Menschen missbrauchte Substanzen erhöhen bevorzugt die extrazelluläre Dopaminkonzentration im mesolimbischen System (Di Chiara & Imperato, PNAS 1988).","q":"Welche Struktur des ventralen Striatums gliedert sich in Kern und Schale und erhält mesolimbisches Dopamin?","mcq":[{"q":"Welche Aussage zu Dopamin im NAcc entspricht der Incentive-Salience-Theorie (Berridge & Robinson)?","a":"Dopamin vermittelt Wollen (Anreiz), nicht primär Mögen (Genuss)","w":["Dopamin vermittelt Mögen, Opioide dagegen das Wollen","Dopamin kodiert im NAcc ausschließlich Bestrafung","Dopamin ist für den Genuss süßer Nahrung unverzichtbar"],"why":"Dopamin-depletierte Ratten zeigen weiter hedonische Reaktionen auf Süßes, suchen es aber nicht mehr aktiv."},{"q":"Anhedonie bei Depression zeigt sich im fMRT am konsistentesten als…","a":"Verminderte ventral-striatale Aktivierung bei Belohnungsantizipation","w":["Erhöhte ventral-striatale Aktivierung bei Bestrafung","Verminderte V1-Aktivierung bei Belohnungsreizen","Erhöhte Amygdala-Aktivierung bei positiven Reizen"],"why":"Eine abgeschwächte Antwort des ventralen Striatums auf Belohnungserwartung ist ein wiederholter Befund."}]},"septum":{"name":"Septumkerne","view":"med","l":4,"fn":"Septumkerne des limbischen Systems: das mediale Septum (mit diagonalem Band) taktet über den Fornix die hippocampale Theta-Rhythmik; das laterale Septum verbindet Hippocampus mit Hypothalamus und VTA.","psych":"Laterales Septum: Regulation von Angst, Aggression und Sozialverhalten. Klassische Selbststimulationsexperimente begründeten die Belohnungsforschung. Septale Läsionen verursachen im Tiermodell Hyperreaktivität (Septum-Wut).","fact":"Olds und Milner beobachteten 1954, dass Ratten die elektrische Selbststimulation der Septumregion wiederholt suchten – Ausgangspunkt der Belohnungsforschung.","q":"Welche Kerngruppe gibt über den Fornix den Takt der hippocampalen Theta-Rhythmik vor?","mcq":[{"q":"Was bewirkt eine Läsion des medialen Septums im Tiermodell am direktesten?","a":"Verlust der hippocampalen Theta-Oszillation","w":["Vollständiger Verlust der hippocampalen Ortszellen","Aufhebung des zirkadianen Ruhe-Aktivitäts-Rhythmus","Vollständige Anosmie"],"why":"Ohne Septum-Input bricht Theta zusammen, Ortszellen feuern aber weiter ortsgebunden."}]},"nbm":{"name":"Basales Vorderhirn (Nucleus basalis Meynert)","view":"med","l":3,"fn":"Größte cholinerge Zellgruppe des Vorderhirns (Ch4): projiziert in Neokortex und Amygdala, moduliert Aufmerksamkeit, Signal-Rausch-Verhältnis und kortikale Plastizität.","psych":"Alzheimer: frühe Degeneration als Basis der cholinergen Hypothese und der Cholinesterasehemmer. Lewy-Körper- und Parkinson-Demenz: noch ausgeprägterer cholinerger Verlust. Hohe anticholinerge Last: Delir und kognitive Verschlechterung.","fact":"Whitehouse et al. (Science 1982) beschrieben den Neuronenverlust im Nucleus basalis Meynert bei Alzheimer – zentraler Befund der cholinergen Hypothese.","q":"Welche Kerngruppe liefert den Hauptanteil der cholinergen Innervation des Neokortex?","mcq":[{"q":"Bei welcher Demenz ist das cholinerge Defizit typischerweise am stärksten und das Ansprechen auf Cholinesterasehemmer oft am deutlichsten?","a":"Lewy-Körper-Demenz","w":["Alzheimer-Krankheit","Frontotemporale Demenz","Vaskuläre Demenz"],"why":"Der kortikale cholinerge Verlust ist bei Lewy-Körper-Demenz ausgeprägter; bei FTD sind Cholinesterasehemmer nicht wirksam."},{"q":"Die cholinerge Innervation des Hippocampus stammt überwiegend aus…","a":"Medialem Septum und diagonalem Band (Ch1/Ch2)","w":["Nucleus basalis Meynert (Ch4)","Nucleus pedunculopontinus (Ch5)","Nucleus laterodorsalis tegmenti (Ch6)"],"why":"Ch4 versorgt Neokortex und Amygdala, Ch5/Ch6 v. a. Thalamus und Hirnstamm."}]},"vta":{"name":"Ventrales tegmentales Areal (VTA)","view":"med","l":2,"fn":"Ursprung der mesolimbischen und mesokortikalen Dopaminbahn; Dopaminneurone kodieren Belohnungsvorhersagefehler; enthält zusätzlich GABA- und Glutamatneurone.","psych":"Sucht: Opioide enthemmen Dopaminneurone über μ-Rezeptoren auf GABA-Neuronen, Nikotin wirkt über α4β2-nAChR. Schizophrenie: mesolimbische Überaktivität (Positivsymptome), mesokortikale Unterfunktion. Depression: veränderte Feuermuster im Tiermodell.","fact":"Dopaminneurone feuern bei unerwarteter Belohnung, verlagern die Antwort nach Lernen auf den ankündigenden Reiz und pausieren bei ausbleibender Belohnung (Schultz et al., Science 1997).","q":"Von welcher Mittelhirnregion gehen die mesolimbische und die mesokortikale Dopaminbahn aus?","mcq":[{"q":"Wie erhöhen Opioide die Dopaminfreisetzung aus der VTA?","a":"μ-Agonismus hemmt GABA-Neurone und enthemmt so die Dopaminneurone","w":["μ-Agonismus depolarisiert die Dopaminneurone direkt","κ-Agonismus steigert die Dopaminfreisetzung im NAcc","Hemmung des Dopamintransporters im NAcc"],"why":"μ-Rezeptoren sitzen v. a. auf GABAergen Neuronen; κ-Agonisten senken die Dopaminfreisetzung eher und wirken aversiv."},{"q":"Ein Affe erwartet nach einem Lichtreiz Saft, der Saft bleibt aus. Wie verhalten sich VTA-Dopaminneurone zum erwarteten Zeitpunkt?","a":"Kurze Pause unter die Basalrate","w":["Phasischer Burst wie bei erhaltener Belohnung","Keine Änderung, da kein Reiz auftritt","Anhaltende tonische Erhöhung der Feuerrate"],"why":"Die Pause ist ein negativer Belohnungsvorhersagefehler – Kernbefund von Schultz."}]},"sn":{"name":"Substantia nigra","view":"med","l":2,"fn":"Pars compacta: neuromelaninhaltige Dopaminneurone der nigrostriatalen Bahn. Pars reticulata: GABAerger Ausgangskern der Basalganglien (analog zum GPi) zu Thalamus und Colliculus superior.","psych":"Parkinson: Verlust der Pars-compacta-Neurone. Antipsychotika: extrapyramidale Symptome durch nigrostriatale D2-Blockade. Neuromelanin-MRT als nicht-invasives Maß dopaminerger Funktion, bei Psychose mit Symptomschwere assoziiert.","fact":"Bei Parkinson ist zum Zeitpunkt der motorischen Diagnose bereits ein Großteil der nigralen Dopaminneurone bzw. ihrer Terminalen verloren – Hinweis auf eine lange Prodromalphase.","q":"Welche Mittelhirnstruktur enthält die neuromelaninhaltigen Dopaminneurone der nigrostriatalen Bahn?","mcq":[{"q":"Welche Struktur ist funktionell ein Ausgangskern der Basalganglien analog zum GPi?","a":"Substantia nigra pars reticulata","w":["Substantia nigra pars compacta","Nucleus subthalamicus","Globus pallidus externus"],"why":"SNr und GPi hemmen tonisch Thalamus bzw. Colliculus superior; die SNc liefert Dopamin."},{"q":"Warum gilt Clozapin bei Psychose im Rahmen von Parkinson als vertretbar, Risperidon dagegen nicht?","a":"Geringe, rasch dissoziierende D2-Bindung bei starker 5-HT2A-Blockade","w":["Clozapin wirkt am D2-Rezeptor als voller Agonist","Clozapin wirkt ausschließlich über H1-Blockade","Risperidon besitzt keine Affinität zu 5-HT2A-Rezeptoren"],"why":"Risperidon blockiert D2 stark und verschlechtert die Motorik; Clozapin kaum."}]},"raphe":{"name":"Raphe-Kerne","view":"med","l":2,"fn":"Mittellinienkerne des Hirnstamms, Ursprung nahezu aller serotonergen Projektionen: rostrale Gruppe (dorsaler und medianer Raphekern) zum Vorderhirn, kaudale Gruppe zu Rückenmark und Hirnstamm.","psych":"SSRI aktivieren akut somatodendritische 5-HT1A-Autorezeptoren, die das Feuern bremsen; erst nach deren Desensitisierung steigt die Transmission – ein Erklärungsmodell der Wirklatenz. Klassisch hemmt LSD akut das Feuern der dorsalen Raphe.","fact":"Der dorsale Raphekern projiziert v. a. in Kortex und Striatum; die kaudalen Raphe-Kerne ziehen ins Rückenmark und modulieren dort die Schmerzweiterleitung.","q":"Welche Hirnstammkerne in der Mittellinie sind Ursprung der serotonergen Projektionen?","mcq":[{"q":"Welcher Mechanismus wird klassisch für die verzögerte Wirkung der SSRI angeführt?","a":"Allmähliche Desensitisierung somatodendritischer 5-HT1A-Autorezeptoren","w":["Langsame Anreicherung des SSRI im Fettgewebe","Allmähliche Hochregulation des Serotonintransporters","Verzögerte Aktivierung kortikaler 5-HT3-Rezeptoren"],"why":"Akut hemmen 5-HT1A-Autorezeptoren das Raphe-Feuern; nach Desensitisierung wird mehr Serotonin freigesetzt."},{"q":"Warum wurde Pindolol als Augmentation zu SSRI untersucht?","a":"Antagonismus an 5-HT1A-Autorezeptoren soll die Feuerbremse lösen","w":["Hemmung der MAO-A in den Raphe-Kernen","Agonismus an 5-HT2A-Rezeptoren im Kortex","Blockade von β-Rezeptoren gegen SSRI-Unruhe"],"why":"Ziel war ein schnellerer Wirkeintritt; die Ergebnisse der Studien waren uneinheitlich."}]},"lc":{"name":"Locus coeruleus","view":"med","l":2,"fn":"Pontiner Kern mit den meisten noradrenergen Neuronen des ZNS; projiziert in Kortex, Thalamus, Hippocampus, Amygdala, Kleinhirn und Rückenmark; steuert Wachheit, Aufmerksamkeit und Stressreaktion.","psych":"Panik, PTBS: Hyperaktivität; Alpträume (Prazosin). Opioidentzug: LC-Hyperaktivität, Behandlung mit α2-Agonisten. ADHS: Atomoxetin, Guanfacin. Früher Ort der Tau-Pathologie bei Alzheimer, Degeneration auch bei Parkinson.","fact":"Tau-Pathologie findet sich im Locus coeruleus oft schon vor der entorhinalen Beteiligung, teils bereits im jungen Erwachsenenalter (Braak et al., J Neuropathol Exp Neurol 2011).","q":"Welcher pontine Kern stellt den Großteil der noradrenergen Neurone des Gehirns?","mcq":[{"q":"Warum lindern α2-Agonisten wie Clonidin die vegetativen Symptome des Opioidentzugs?","a":"Sie hemmen die rebound-hyperaktiven Neurone des Locus coeruleus","w":["Sie wirken als partielle μ-Opioid-Agonisten","Sie blockieren postsynaptische β1-Rezeptoren","Sie steigern die Noradrenalinfreisetzung im Kortex"],"why":"Opioide hemmen den LC; im Entzug feuert er überschießend, α2-Autorezeptor-Aktivierung dämpft dies."}]},"pineal":{"name":"Zirbeldrüse (Epiphyse)","view":"med","l":3,"fn":"Epithalamische Drüse, bildet nachts Melatonin aus Serotonin; Steuerung: SCN → PVN → Rückenmark → Ganglion cervicale superius → sympathische Fasern zur Epiphyse; Licht unterdrückt die Sekretion.","psych":"Agomelatin (MT1/MT2-Agonist und 5-HT2C-Antagonist) bei Depression; Melatonin bei Schlaf-Wach-Rhythmusstörungen; Evidenz zur Delirprävention uneinheitlich. Pinealistumoren: Parinaud-Syndrom mit vertikaler Blickparese.","fact":"Geschwindigkeitsbestimmend für die Melatoninsynthese ist die Arylalkylamin-N-Acetyltransferase (AANAT), die nachts sympathisch aktiviert wird.","q":"Welche Drüse wird über das Ganglion cervicale superius sympathisch innerviert und schüttet nachts Melatonin aus?","mcq":[{"q":"Welcher Signalweg verbindet Licht mit der Melatoninsuppression?","a":"Retina → SCN → PVN → Rückenmark → Ganglion cervicale superius → Epiphyse","w":["Retina → Corpus geniculatum laterale → V1 → Epiphyse","Retina → Colliculus superior → direkt zur Epiphyse","Retina → SCN → Hypophysenvorderlappen → Epiphyse"],"why":"Die Epiphyse wird über einen multisynaptischen sympathischen Weg gesteuert, nicht über die Sehrinde oder hormonell."},{"q":"Welche Kombination beschreibt das Wirkprofil von Agomelatin korrekt?","a":"MT1/MT2-Agonist und 5-HT2C-Antagonist","w":["MT1/MT2-Antagonist und 5-HT2C-Agonist","Dualer Orexin-Rezeptorantagonist","MT1/MT2-Agonist und SERT-Hemmer"],"why":"Die 5-HT2C-Blockade enthemmt frontale Dopamin- und Noradrenalinfreisetzung."}]},"mammillar":{"name":"Corpora mammillaria","view":"med","l":3,"fn":"Hypothalamische Kerne des Papez-Kreises: erhalten über den Fornix Input aus dem Hippocampus und projizieren über den Tractus mammillothalamicus zum Nucleus anterior thalami; wichtig für episodisches Gedächtnis.","psych":"Wernicke-Enzephalopathie und Korsakow-Syndrom bei Thiaminmangel (Alkohol, Mangelernährung, Hyperemesis, nach bariatrischer Operation, Anorexia nervosa): Atrophie und Einblutungen, anterograde Amnesie, Konfabulation.","fact":"Die klassische Wernicke-Trias (Augenbewegungsstörung, Ataxie, Verwirrtheit) liegt nur bei einer Minderheit vollständig vor; bei Verdacht wird Thiamin vor Glukose gegeben.","q":"Welche hypothalamischen Kerne atrophieren beim Korsakow-Syndrom und sind über den Fornix mit dem Hippocampus verbunden?","mcq":[{"q":"Warum soll bei Verdacht auf Wernicke-Enzephalopathie Thiamin vor Glukose gegeben werden?","a":"Glukoseverwertung verbraucht Thiamin als Cofaktor der Pyruvatdehydrogenase","w":["Glukose blockiert die intestinale Thiaminresorption","Thiamin ist der Cofaktor der Hexokinase","Glukose steigert direkt die renale Thiaminausscheidung"],"why":"Thiaminpyrophosphat ist Cofaktor von PDH, α-Ketoglutarat-Dehydrogenase und Transketolase; Glukose verschärft den Mangel."}]},"caudate":{"name":"Nucleus caudatus","view":"cor","l":2,"fn":"Dorsales, assoziatives Striatum: zielgerichtetes Lernen und Handlungsauswahl; Input aus dlPFC und OFC, Teil der assoziativen CSTC-Schleifen; der Kopf bildet die laterale Wand des Seitenventrikel-Vorderhorns.","psych":"Chorea Huntington: früheste Atrophie des Caudatuskopfs mit ballonierten Vorderhörnern. Zwangsstörung: erhöhter Caudatus-Stoffwechsel, der unter SSRI und Verhaltenstherapie sinkt. Schizophrenie: erhöhte Dopaminsynthese im assoziativen Striatum.","fact":"Bei Huntington gehen zuerst striatale Projektionsneurone der indirekten Bahn (D2, Enkephalin) unter – das erklärt die frühe Chorea.","q":"Welche Struktur atrophiert bei Chorea Huntington am frühesten und formt die laterale Wand der Vorderhörner?","mcq":[{"q":"Warum führt der frühe Verlust striataler Neurone bei Huntington zunächst zu Hyperkinesen?","a":"Zuerst gehen Neurone der indirekten Bahn (D2/Enkephalin) unter","w":["Zuerst gehen Neurone der direkten Bahn (D1/Substanz P) unter","Die nigrale Dopaminfreisetzung sinkt früh stark ab","Der Nucleus subthalamicus wird früh hyperaktiv"],"why":"Fällt die indirekte Bahn aus, wird der Thalamus enthemmt; spätere Rigidität spiegelt den Verlust auch der direkten Bahn."},{"q":"Was zeigten PET-Studien bei Zwangsstörung nach erfolgreicher Verhaltenstherapie oder SSRI-Behandlung?","a":"Abnahme des Caudatus-Glukosestoffwechsels unter beiden Therapieformen","w":["Abnahme nur unter SSRI, nicht unter Verhaltenstherapie","Zunahme des Caudatus-Glukosestoffwechsels unter beiden","Keine striatale Änderung, nur eine im Kleinhirn"],"why":"Baxter et al. 1992 zeigten konvergente Effekte von Psychotherapie und Pharmakotherapie im selben Kreis."}]},"putamen":{"name":"Putamen","view":"cor","l":2,"fn":"Dorsales, sensomotorisches Striatum: Gewohnheitsbildung und automatisierte Bewegungen; Input aus M1 und S1; bildet mit dem Caudatus das Striatum mit direkter (D1) und indirekter (D2) Bahn.","psych":"Parkinson: dopaminerger Verlust zuerst im posterioren Putamen. Sucht: Verlagerung der Kontrolle vom ventralen zum dorsalen Striatum bei Gewohnheitsbildung. Häufiger Ort hypertensiver Blutungen. Morbus Wilson: Putamenveränderungen.","fact":"Im DaT-SPECT zeigt Parkinson typischerweise zuerst einen Verlust im posterioren Putamen, später auch im Caudatus („Komma“ wird zum „Punkt“).","q":"Welcher Teil des dorsalen Striatums verliert bei Parkinson zuerst seine dopaminergen Terminalen?","mcq":[{"q":"Ein Patient unter Antipsychotikum hat einen Parkinsonismus, das DaT-SPECT ist normal. Was ist am wahrscheinlichsten?","a":"Medikamentös induzierter Parkinsonismus durch postsynaptische D2-Blockade","w":["Idiopathisches Parkinson-Syndrom im Frühstadium","Lewy-Körper-Demenz mit beginnendem Parkinsonismus","Multisystematrophie vom Parkinson-Typ"],"why":"Das DaT-SPECT misst präsynaptische Terminalen; bei neurodegenerativen Parkinson-Syndromen ist es pathologisch."}]},"gp":{"name":"Globus pallidus","view":"cor","l":3,"fn":"Globus pallidus externus: Station der indirekten Bahn. Globus pallidus internus: GABAerger Hauptausgang der Basalganglien, hemmt tonisch den motorischen Thalamus (VA/VL).","psych":"Tiefe Hirnstimulation des GPi bei Dystonie und Parkinson. Bilaterale Pallidumnekrosen bei Kohlenmonoxidvergiftung. T1-hyperintense Pallida durch Manganablagerung. Pantothenatkinase-assoziierte Neurodegeneration mit typischem MRT-Zeichen.","fact":"T1-hyperintense Pallida finden sich bei Manganablagerung, z. B. bei Leberzirrhose oder langer parenteraler Ernährung.","q":"Welcher Basalganglienkern ist der GABAerge Hauptausgang zum Thalamus und THS-Zielort bei Dystonie?","mcq":[{"q":"Welche Ursache führt typischerweise zu bilateralen Nekrosen des Globus pallidus?","a":"Kohlenmonoxidvergiftung","w":["Wernicke-Enzephalopathie","Hypertensive Massenblutung","Herpes-simplex-Enzephalitis"],"why":"Das Pallidum ist besonders empfindlich gegenüber CO-Hypoxie; die Distraktoren betreffen Mammillarkörper, Putamen bzw. Temporallappen."},{"q":"Was bewirkt der Dopaminmangel bei Parkinson im klassischen Basalganglienmodell am GPi?","a":"Erhöhte GPi-Aktivität mit stärkerer Hemmung des motorischen Thalamus","w":["Verminderte GPi-Aktivität mit Enthemmung des Thalamus","Keine Änderung, da der GPi nicht dopaminerg beeinflusst wird","Erhöhte GPe-Aktivität mit Enthemmung des Thalamus"],"why":"Schwächere direkte und stärkere indirekte Bahn steigern die GPi-Hemmung des Thalamus – Akinese."}]},"claustrum":{"name":"Claustrum","view":"cor","l":4,"fn":"Dünne Platte grauer Substanz zwischen Capsula externa und Capsula extrema, reziprok mit fast allen Kortexarealen verbunden; Hypothesen: Synchronisierung kortikaler Aktivität, Aufmerksamkeit, Bewusstsein.","psych":"Hohe Dichte an 5-HT2A- und κ-Opioid-Rezeptoren macht es zum Kandidaten für Wirkorte von Psychedelika und Salvinorin A; Psilocybin veränderte in einer fMRT-Studie seine Konnektivität mit Netzwerken. Claustrum-Zeichen im MRT bei NORSE.","fact":"Crick und Koch (Phil Trans R Soc B, 2005) schlugen das Claustrum als Struktur vor, die kortikale Inhalte zu einem bewussten Erleben bindet – bislang nicht belegt.","q":"Welche dünne Kernplatte zwischen Capsula externa und extrema ist mit nahezu allen Kortexarealen reziprok verbunden?","mcq":[{"q":"Zwischen welchen Strukturen liegt das Claustrum?","a":"Capsula externa und Capsula extrema","w":["Capsula interna und Capsula externa","Putamen und Globus pallidus","Capsula extrema und Inselrinde"],"why":"Von medial nach lateral: Putamen, Capsula externa, Claustrum, Capsula extrema, Inselrinde."},{"q":"Welche Rezeptoren sind im Claustrum besonders dicht und begründen Hypothesen zu Psychedelika und Salvinorin A?","a":"5-HT2A- und κ-Opioid-Rezeptoren","w":["D1- und D2-Rezeptoren","μ-Opioid- und CB1-Rezeptoren","Nikotinische α7- und H3-Rezeptoren"],"why":"Salvinorin A ist ein selektiver κ-Agonist; klassische Psychedelika wirken über 5-HT2A."}]},"capsula":{"name":"Capsula interna","view":"cor","l":3,"fn":"Projektionsfasern zwischen Kortex und Subkortex: Crus anterius (frontothalamisch, frontopontin), Genu (kortikobulbär), Crus posterius (kortikospinal, somatosensibel; retrolentikulär Seh- und Hörstrahlung).","psych":"Lakunärer Infarkt im Crus posterius: rein motorische Hemiparese. Ventraler vorderer Kapselschenkel: Ziel der Kapsulotomie und der THS an ventraler Kapsel/ventralem Striatum bei therapierefraktärer Zwangsstörung, experimentell bei Depression.","fact":"Die THS an ventraler Kapsel und ventralem Striatum erhielt 2009 in den USA eine Humanitarian Device Exemption für therapierefraktäre Zwangsstörung.","q":"Welche Fasermasse führt im hinteren Schenkel die Pyramidenbahn und ist im vorderen Schenkel Ziel der Kapsulotomie?","mcq":[{"q":"Ein kleiner lakunärer Infarkt im Crus posterius capsulae internae verursacht typischerweise…","a":"Rein motorische kontralaterale Hemiparese ohne kortikale Zeichen","w":["Kontralaterale Hemiparese mit globaler Aphasie","Ipsilaterale Ataxie mit kontralateraler Hypästhesie","Bilaterale Parese mit Bewusstseinsstörung"],"why":"Die dicht gebündelten kortikospinalen Fasern werden getroffen; kortikale Funktionen wie Sprache bleiben erhalten."}]},"ventrikel":{"name":"Seitenventrikel","view":"cor","l":2,"fn":"Liquorräume der Hemisphären mit Plexus choroideus (Liquorbildung); Abfluss über das Foramen interventriculare in den 3. Ventrikel; der Caudatus bildet die laterale Wand des Vorderhorns.","psych":"Schizophrenie: Erweiterung der Seitenventrikel, schon bei Ersterkrankten nachweisbar. Normaldruckhydrozephalus als behandelbare Demenzursache. Huntington: ballonierte Vorderhörner durch Caudatusatrophie.","fact":"Johnstone et al. (Lancet 1976) zeigten mit CT erstmals erweiterte Seitenventrikel bei chronischer Schizophrenie.","q":"Welche Liquorräume sind bei Schizophrenie erweitert und beim Normaldruckhydrozephalus unverhältnismäßig weit?","mcq":[{"q":"Welche Trias spricht bei erweiterten Ventrikeln für einen Normaldruckhydrozephalus?","a":"Gangstörung, kognitive Störung, Harninkontinenz","w":["Kopfschmerz, Stauungspapille, Erbrechen","Ataxie, Ophthalmoplegie, Verwirrtheit","Rigor, Ruhetremor, Akinese"],"why":"Die Distraktoren beschreiben erhöhten Hirndruck, Wernicke-Enzephalopathie bzw. Parkinson."},{"q":"Welche MRT-Konstellation stützt einen Normaldruckhydrozephalus am stärksten?","a":"DESH: weite Sylvische Fissuren, enge hochparietale Sulci","w":["Sulci proportional zu den Ventrikeln global erweitert","Isolierte Hippocampusatrophie ohne Ventrikelerweiterung","Ovoide periventrikuläre Läsionen senkrecht zum Balken"],"why":"DESH (disproportionately enlarged subarachnoid-space hydrocephalus) unterscheidet NPH von Atrophie; die übrigen passen zu Atrophie, Alzheimer bzw. MS."}]},"bnst":{"name":"Nucleus interstitialis striae terminalis (BNST)","view":"cor","l":4,"fn":"Teil der erweiterten Amygdala: vermittelt anhaltende Angst bei unvorhersehbarer, diffuser Bedrohung; projiziert zu Hypothalamus (PVN) und Hirnstamm, CRH-reich.","psych":"Generalisierte Angststörung, PTBS: Hypervigilanz und Erwartungsangst. Sucht: stressinduzierte Rückfälle über CRH. Geschlechtsdimorphe Struktur. Experimenteller THS-Zielort bei therapierefraktärer Zwangsstörung.","fact":"Davis et al. (Neuropsychopharmacology 2010) trennten phasische Furcht vor klarer Bedrohung (zentrale Amygdala) von anhaltender Angst bei unvorhersehbarer Bedrohung (BNST).","q":"Welche Struktur der erweiterten Amygdala vermittelt anhaltende Angst bei unvorhersehbarer Bedrohung?","mcq":[{"q":"Welche Aufgabenteilung zwischen zentraler Amygdala (CeA) und BNST beschreibt das Modell von Davis am besten?","a":"CeA: phasische Furcht bei klarer Bedrohung; BNST: anhaltende Angst bei diffuser","w":["CeA: anhaltende Angst bei diffuser Bedrohung; BNST: phasische Furcht bei klarer","CeA: Abruf der Extinktion nach Lernen; BNST: Erwerb neuer Furchtassoziationen","CeA: Furcht vor sozialen Reizen; BNST: Furcht vor physischen Schmerzreizen"],"why":"Die Unterscheidung Furcht vs. Angst bildet sich auf CeA vs. BNST ab und spiegelt sich in Paradigmen mit vorhersagbarer vs. unvorhersagbarer Bedrohung."}]},"pyramidal":{"name":"Pyramidenzelle der Schicht V","view":"syn","l":3,"fn":"Glutamaterges Projektionsneuron der Kortexschicht V: integriert Inputs an apikalem und basalen Dendriten und projiziert subkortikal (Striatum, Thalamus, Hirnstamm, Rückenmark); hohe 5-HT2A-Dichte am apikalen Dendriten.","psych":"Zentraler zellulärer Angriffsort klassischer Psychedelika: 5-HT2A-Aktivierung erhöht Erregbarkeit und Glutamatfreisetzung. Chronischer Stress und Depression: Dendritenatrophie im PFC; Ketamin und Psychedelika fördern im Tiermodell Spine-Bildung.","fact":"Bei Mäusen erhöhte eine einzelne Psilocybin-Gabe Dichte und Größe dendritischer Spines in Schicht-V-Pyramidenzellen des medialen Frontalkortex anhaltend (Shao et al., Neuron 2021).","q":"Welcher Zelltyp der tiefen Kortexschichten trägt am apikalen Dendriten die höchste 5-HT2A-Dichte und projiziert subkortikal?","mcq":[{"q":"Welcher Effekt am Schicht-V-Pyramidenneuron gilt als zellulärer Kern der akuten Psychedelikawirkung?","a":"5-HT2A-vermittelte Zunahme exzitatorischer Aktivität am apikalen Dendriten","w":["5-HT1A-vermittelte Hyperpolarisation des Zellkörpers mit Feuerreduktion","Blockade präsynaptischer D2-Autorezeptoren mit kortikalem Dopaminanstieg","Hemmung des Serotonintransporters an serotonergen Terminalen im Kortex"],"why":"5-HT2A-Agonisten steigern spontane EPSCs in Schicht-V-Zellen; 5-HT2A-Antagonisten heben die subjektiven Effekte beim Menschen auf."}]},"apical":{"name":"Apikaler Dendrit mit Dornen (Spines)","view":"syn","l":4,"fn":"Langer apikaler Dendrit bis in Schicht I mit Dornen (Spines) als Orte exzitatorischer Synapsen; Spine-Bildung und -Abbau sind ein Substrat synaptischer Plastizität; integriert Feedback-Input aus höheren Arealen.","psych":"Chronischer Stress und Depression: Atrophie apikaler Dendriten und Spine-Verlust in PFC und Hippocampus. Ketamin und Psychedelika fördern im Tiermodell rasch neue Spines (Psychoplastogene) – ein Kandidatenmechanismus anhaltender Wirkung.","fact":"Ketamin-induzierte Spine-Neubildung war im Mausmodell nicht für den schnellen Wirkbeginn, wohl aber für den Erhalt der Wirkung nötig (Moda-Sava et al., Science 2019).","q":"Welche Zellstruktur verliert unter chronischem Stress Dornen und bildet unter Ketamin rasch neue Spines?","mcq":[{"q":"Was zeigten Moda-Sava et al. (Science 2019) zur Ketaminwirkung bei Mäusen?","a":"Neue Spines waren für den Erhalt, nicht für den Beginn der Wirkung nötig","w":["Neue Spines waren für den Beginn, nicht für den Erhalt der Wirkung nötig","Ketamin wirkte ganz ohne messbare Änderung der Spinedichte","Ketamin senkte die Spinedichte und wirkte dadurch antidepressiv"],"why":"Die gezielte Löschung neu gebildeter Spines hob die anhaltende, nicht aber die akute Verhaltenswirkung auf."},{"q":"Wie bezeichneten Ly et al. (Cell Rep 2018) Substanzen, die rasch strukturelle neuronale Plastizität fördern?","a":"Psychoplastogene","w":["Neurotrophine","Nootropika","Entaktogene"],"why":"Der Begriff umfasst Psychedelika und Ketamin; Neurotrophine sind körpereigene Proteine wie BDNF."}]},"r5ht2a":{"name":"5-HT2A-Rezeptor","view":"syn","l":3,"fn":"Gq-gekoppelter Serotoninrezeptor (PLC → IP3/DAG → Ca2+), besonders dicht auf apikalen Dendriten von Schicht-V-Pyramidenzellen; auch auf GABA-Interneuronen und Thrombozyten.","psych":"Ziel klassischer Psychedelika (Psilocin, LSD, DMT): Agonismus ist für die subjektiven Effekte nötig. Antagonismus bzw. inverser Agonismus bei atypischen Antipsychotika, Pimavanserin und Mirtazapin.","fact":"Die Intensität subjektiver Psilocybin-Effekte korrelierte mit der 5-HT2A-Belegung im PET und der Psilocin-Plasmakonzentration (Madsen et al., Neuropsychopharmacology 2019).","q":"Welcher Gq-gekoppelte Rezeptor muss aktiviert werden, damit Psilocin seine subjektiven Effekte entfaltet?","mcq":[{"q":"Lisurid ist 5-HT2A-Agonist, aber beim Menschen nicht psychedelisch. Welche Erklärung wird diskutiert?","a":"Funktionelle Selektivität: andere Signalwege bzw. geringere Gq-Effizienz","w":["Lisurid erreicht wegen fehlender Hirngängigkeit den Kortex nicht","Lisurid bindet nur an 5-HT2C- und nicht an 5-HT2A-Rezeptoren","Lisurid wirkt im Kortex überwiegend als Hemmer des SERT"],"why":"Lisurid wirkt zentral (Parkinson-Therapie); Unterschiede in der Signalwegaktivierung gegenüber LSD erklären die fehlende psychedelische Wirkung."},{"q":"Welcher Befund belegte beim Menschen erstmals die 5-HT2A-Abhängigkeit der Psilocybin-Wirkung?","a":"Vorbehandlung mit Ketanserin verhinderte die Effekte weitgehend","w":["Vorbehandlung mit Haloperidol verhinderte die Effekte weitgehend","Vorbehandlung mit Pindolol verhinderte die Effekte weitgehend","Vorbehandlung mit Naloxon verhinderte die Effekte weitgehend"],"why":"Vollenweider et al. 1998: Ketanserin und Risperidon blockierten die Wirkung, der D2-Antagonist Haloperidol nicht."}]},"r5ht1a":{"name":"5-HT1A-Rezeptor","view":"syn","l":4,"fn":"Gi/o-gekoppelter Rezeptor (cAMP sinkt, GIRK-Kanäle öffnen, Hyperpolarisation): somatodendritischer Autorezeptor auf Raphe-Neuronen und postsynaptischer Heterorezeptor in Hippocampus, Septum und Kortex.","psych":"Buspiron (Partialagonist) bei generalisierter Angststörung; Vilazodon und Vortioxetin mit 5-HT1A-Komponente; Autorezeptor-Desensitisierung als Modell der SSRI-Latenz. Einige Psychedelika (besonders 5-MeO-DMT) haben hohe 5-HT1A-Affinität.","fact":"Aktivierte 5-HT1A-Autorezeptoren hemmen das Feuern der Raphe-Neurone – eine negative Rückkopplung, die die SSRI-Wirkung zu Beginn abschwächt.","q":"Welcher Gi-gekoppelte Rezeptor wirkt auf Raphe-Neuronen als somatodendritischer Autorezeptor?","mcq":[{"q":"Welche Kombination beschreibt das Wirkprofil von Vilazodon?","a":"SERT-Hemmung plus partieller 5-HT1A-Agonismus","w":["SERT-Hemmung plus 5-HT3-Antagonismus","NET-Hemmung plus 5-HT2A-Antagonismus","SERT-Hemmung plus 5-HT2C-Antagonismus"],"why":"Vortioxetin kombiniert u. a. SERT-Hemmung, 5-HT1A-Agonismus und 5-HT3-Antagonismus; Vilazodon nur die ersten beiden."},{"q":"Wo wirkt der 5-HT1A-Rezeptor als Heterorezeptor statt als Autorezeptor?","a":"Auf Pyramidenzellen in Hippocampus und Kortex","w":["Auf Serotoninneuronen des dorsalen Raphekerns","Auf Serotoninneuronen des medianen Raphekerns","Auf serotonergen Axonterminalen als 5-HT-Freisetzungsbremse"],"why":"Somatodendritische Autorezeptoren sitzen in den Raphe-Kernen; an Terminalen bremsen eher 5-HT1B/1D-Autorezeptoren."}]},"sert":{"name":"Serotonintransporter (SERT)","view":"syn","l":3,"fn":"Natriumabhängiger Transporter (SLC6A4) in der präsynaptischen Membran serotonerger Endigungen; holt Serotonin aus dem synaptischen Spalt zurück und beendet so das Signal.","psych":"Angriffspunkt von SSRI, SNRI und Trizyklika; MDMA kehrt den Transport um. Der 5-HTTLPR-Polymorphismus galt als Gen-Umwelt-Modell der Depression, wurde in sehr großen Stichproben aber nicht bestätigt.","fact":"Weder 5-HTTLPR noch andere historische Kandidatengene zeigten in sehr großen Stichproben Haupt- oder Interaktionseffekte auf Depression (Border et al., Am J Psychiatry 2019).","q":"Welches präsynaptische Membranprotein beendet das Serotoninsignal und ist Angriffspunkt von Escitalopram?","mcq":[{"q":"Warum erhöhen SSRI das Blutungsrisiko, besonders zusammen mit NSAR?","a":"Thrombozyten nehmen Serotonin über SERT auf und verarmen unter SSRI daran","w":["SSRI hemmen direkt die Cyclooxygenase-1 der Thrombozyten","SSRI senken die hepatische Synthese von Gerinnungsfaktoren","Serotonin wirkt über 5-HT3 am Endothel gerinnungshemmend"],"why":"Thrombozyten synthetisieren kein Serotonin; ohne SERT-Aufnahme fehlt es für die Aggregationsverstärkung."},{"q":"Was zeigten Border et al. (Am J Psychiatry 2019) zum 5-HTTLPR-Polymorphismus?","a":"Weder Haupteffekt noch Interaktion mit Stress auf Depression","w":["Robuste Interaktion mit Kindheitstrauma auf Depression","Haupteffekt auf Depression nur bei Frauen","Effekt nur auf das Ansprechen auf SSRI"],"why":"Die großen Stichproben lieferten keine Unterstützung für die historischen Kandidatengen-Hypothesen."}]},"terminal5ht":{"name":"Serotonerge Nervenendigung (aus den Raphe-Kernen)","view":"syn","l":3,"fn":"Axonendigung serotonerger Raphe-Neurone: Synthese (Tryptophanhydroxylase 2 → 5-HTP → AADC → 5-HT), vesikuläre Speicherung über VMAT2, Freisetzung, Rückaufnahme über SERT, Abbau durch MAO-A; 5-HT1B/1D-Autorezeptoren.","psych":"Akute Tryptophan-Depletion löst bei remittierten, mit SSRI behandelten Patienten oft vorübergehend depressive Symptome aus, bei Gesunden kaum. MAO-Hemmer; Serotonin-Syndrom bei Kombination serotonerger Wirkstoffe; Reserpin blockiert VMAT.","fact":"Geschwindigkeitsbestimmend ist die Tryptophanhydroxylase; im Gehirn ist TPH2 zuständig, in enterochromaffinen Zellen des Darms TPH1.","q":"Welche präsynaptische Struktur synthetisiert Serotonin über TPH2 und reguliert die Freisetzung über 5-HT1B-Autorezeptoren?","mcq":[{"q":"Warum hängt die zentrale Serotoninsynthese vom Verhältnis Tryptophan zu anderen großen neutralen Aminosäuren ab?","a":"Sie konkurrieren um denselben Transporter (LAT1) an der Blut-Hirn-Schranke","w":["Sie hemmen kompetitiv die Tryptophanhydroxylase","Sie beschleunigen den Serotoninabbau durch MAO-A","Sie blockieren die vesikuläre Speicherung über VMAT2"],"why":"Kohlenhydratreiche Mahlzeiten senken über Insulin die Konkurrenten im Plasma und erhöhen so den Tryptophaneinstrom."},{"q":"Bei wem löst akute Tryptophan-Depletion am ehesten depressive Symptome aus?","a":"Remittierte Patienten unter SSRI-Therapie","w":["Gesunde ohne familiäre Belastung","Remittierte Patienten unter Desipramin","Akut manische Patienten"],"why":"Bei Remission unter noradrenergen Antidepressiva wie Desipramin löste die Depletion kaum Rückfallsymptome aus."}]},"nmda":{"name":"NMDA- und AMPA-Rezeptoren (Glutamat)","view":"syn","l":4,"fn":"Ionotrope Glutamatrezeptoren: AMPA vermittelt die schnelle Depolarisation; NMDA braucht Glutamat, Glycin/D-Serin und Depolarisation zur Lösung des Mg2+-Blocks – Koinzidenzdetektor für LTP mit Ca2+-Einstrom.","psych":"Glutamathypothese der Schizophrenie: NMDA-Antagonisten erzeugen positive, negative und kognitive Symptome. Anti-NMDA-Rezeptor-Enzephalitis. Ketamin und Esketamin wirken rasch antidepressiv, im Tiermodell AMPA-abhängig.","fact":"Die Anti-NMDA-Rezeptor-Enzephalitis (Antikörper gegen GluN1) beginnt oft psychiatrisch und ist bei jungen Frauen mit Ovarialteratomen assoziiert (Dalmau et al., Lancet Neurol 2008).","q":"Welche ionotropen Glutamatrezeptoren brauchen für den Ionenfluss gleichzeitig Depolarisation zur Lösung des Mg2+-Blocks?","mcq":[{"q":"Welche Beobachtung im Tiermodell spricht dafür, dass die antidepressive Ketaminwirkung AMPA-abhängig ist?","a":"Der AMPA-Antagonist NBQX hebt die Wirkung auf","w":["Der AMPA-Antagonist NBQX verstärkt die Wirkung","Ketamin wirkt unverändert trotz AMPA-Blockade","AMPA-Agonisten blockieren die Ketaminwirkung"],"why":"Die Disinhibitions- und die Ruhe-NMDA-Hypothese münden beide in eine verstärkte AMPA-Signalisierung."},{"q":"Eine 24-Jährige hat eine akute Psychose, orofaziale Dyskinesien und autonome Instabilität. Welche Diagnostik ist vordringlich?","a":"Liquor auf GluN1-Antikörper und Suche nach Ovarialteratom","w":["DaT-SPECT und Bestimmung des Ceruloplasmins","Dexamethason-Hemmtest und Cortisol-Tagesprofil","Polysomnographie und Orexin im Liquor"],"why":"Psychose plus Bewegungsstörung und Dysautonomie ist typisch für die Anti-NMDAR-Enzephalitis; frühe Immuntherapie verbessert die Prognose."}]},"interneuron":{"name":"GABAerges Interneuron","view":"syn","l":4,"fn":"Lokale hemmende Neurone mit Subtypen: Parvalbumin (perisomatisch, schnell feuernd, Gamma-Oszillationen), Somatostatin (dendritisch), VIP (hemmen andere Interneurone). Steuern Timing und Verstärkung der Pyramidenzellen.","psych":"Schizophrenie: verminderte GAD67- und Parvalbumin-Expression im dlPFC, gestörte Gamma-Oszillationen. Disinhibitionshypothese: Ketamin blockiert bevorzugt NMDA-Rezeptoren auf Interneuronen. Depression: Hinweise auf reduzierte Somatostatin-Marker.","fact":"Parvalbumin-Korbzellen erzeugen durch perisomatische Hemmung Gamma-Oszillationen; bei Schizophrenie ist ihre GAD67-Expression im dlPFC vermindert (Lewis et al., Nat Rev Neurosci 2005).","q":"Welcher Zelltyp erzeugt Gamma-Oszillationen und zeigt bei Schizophrenie im dlPFC verminderte GAD67-Expression?","mcq":[{"q":"Was besagt die Disinhibitionshypothese der Ketaminwirkung?","a":"NMDA-Blockade an Interneuronen enthemmt Pyramidenzellen – Glutamatschub","w":["NMDA-Blockade an Pyramidenzellen hemmt Interneurone dauerhaft","Ketamin aktiviert direkt GABA-A-Rezeptoren auf Pyramidenzellen","Ketamin senkt die Glutamatfreisetzung der Pyramidenzellen"],"why":"Tonisch aktive Interneurone sind besonders NMDA-abhängig; ihre Hemmung erhöht die Pyramidenzellaktivität."},{"q":"Welche Interneuron-Klasse hemmt bevorzugt andere Interneurone und wirkt dadurch disinhibierend?","a":"VIP-Interneurone","w":["Parvalbumin-Korbzellen","Chandelier-Zellen","Martinotti-Zellen (Somatostatin)"],"why":"VIP-Zellen hemmen Somatostatin-Zellen und enthemmen so die apikalen Dendriten der Pyramidenzellen."}]},"trkb":{"name":"BDNF und TrkB-Rezeptor","view":"syn","l":4,"fn":"BDNF bindet an die Rezeptortyrosinkinase TrkB und aktiviert MAPK/ERK, PI3K/Akt und PLCγ; fördert Synaptogenese, LTP, Spine-Wachstum und Neurogenese; aktivitätsabhängige Freisetzung.","psych":"Neurotrophe Hypothese der Depression. Antidepressiva binden laut Casarotto et al. direkt an TrkB, LSD und Psilocin laut Moliner et al. mit höherer Affinität; unabhängige Bestätigung steht aus. Val66Met-Polymorphismus.","fact":"NMDA-Blockade in Ruhe steigerte im Tiermodell über Hemmung der eEF2-Kinase rasch die BDNF-Translation – ein Mechanismus der Ketaminwirkung (Autry et al., Nature 2011).","q":"Welches Neurotrophin-Rezeptorsystem wird laut Casarotto et al. (Cell 2021) direkt von Antidepressiva gebunden?","mcq":[{"q":"Was berichteten Moliner et al. (Nat Neurosci 2023) zu LSD und Psilocin?","a":"Direkte TrkB-Bindung, die Plastizität 5-HT2A-unabhängig fördern kann","w":["Direkte Bindung an BDNF selbst, nicht an dessen Rezeptor","Blockade von TrkB mit verminderter neuronaler Plastizität","Plastizität allein über 5-HT2A, ohne TrkB-Beteiligung"],"why":"Plastizitätseffekte blieben unter 5-HT2A-Blockade bestehen, die Head-Twitch-Reaktion hing dagegen von 5-HT2A ab."},{"q":"Welche Folge hat das Met-Allel des BDNF-Val66Met-Polymorphismus primär?","a":"Verminderte aktivitätsabhängige BDNF-Sekretion","w":["Vermehrte konstitutive BDNF-Sekretion","Verlust der TrkB-Kinaseaktivität","Erhöhte BDNF-Bindung an p75NTR"],"why":"Egan et al. 2003: Das Met-Allel stört das intrazelluläre Sorting von pro-BDNF in regulierte Sekretionsvesikel."}]},"microglia":{"name":"Mikroglia","view":"syn","l":4,"fn":"Residente Immunzellen des ZNS (myeloischer Ursprung aus dem Dottersack): überwachen das Gewebe, phagozytieren, beschneiden Synapsen über Komplement (C1q/C3 → CR3) und bilden Zytokine.","psych":"Schizophrenie: Hypothese übermäßigen synaptischen Prunings, gestützt durch C4-Varianten. Depression: Entzündungshypothese (IL-6, CRP); Interferon-α kann Depression auslösen. TSPO-PET als unspezifischer Marker der Mikroglia-Aktivierung.","fact":"Varianten, die die Expression von C4A erhöhen, sind mit Schizophrenie assoziiert; C4 vermittelte im Tiermodell synaptisches Pruning (Sekar et al., Nature 2016).","q":"Welche Zellen beschneiden Synapsen nach Komplementmarkierung und werden mit TSPO-PET dargestellt?","mcq":[{"q":"Warum gilt TSPO-PET als eingeschränkter Marker der Mikroglia-Aktivierung?","a":"TSPO ist nicht aktivierungsspezifisch und kommt auch in Astrozyten und Endothel vor","w":["TSPO wird ausschließlich in Neuronen und nicht in Glia exprimiert","TSPO-Tracer passieren die Blut-Hirn-Schranke grundsätzlich nicht","TSPO bindet nur an ruhende, nicht an aktivierte Mikroglia"],"why":"Hinzu kommt ein Polymorphismus (rs6971), der die Bindung neuerer Tracer beeinflusst und eine Genotypisierung nötig macht."},{"q":"Welche klinische Beobachtung stützt die Entzündungshypothese der Depression besonders?","a":"Interferon-α-Therapie löst bei einem Teil der Behandelten Depressionen aus","w":["Glukokortikoide wirken bei Depression regelhaft antidepressiv","Immunsuppressiva lösen regelhaft manische Episoden aus","Akute Infektionen senken das Depressionsrisiko messbar"],"why":"Zytokin-induzierte Depression ist ein Modell, das Entzündung kausal mit depressiven Symptomen verknüpft."}]}},"networks":[{"id":"dmn","name":"Default-Mode-Netzwerk","level":2,"regions":["vmpfc","pcc","precuneus","ppc","hippocampus"],"fn":"Aktiv in Ruhe und bei selbstbezogenem Denken, autobiografischer Erinnerung, Zukunftssimulation und Theory of Mind; bei externen Aufgaben deaktiviert und antikorreliert mit aufgabenpositiven Netzwerken.","psych":"Depression: erhöhte DMN-Konnektivität mit Rumination. Psilocybin akut: verminderte DMN-Integrität; nach Psilocybin-Therapie verminderte Netzwerk-Modularität. Alzheimer: frühe Amyloidablagerung in DMN-Knoten. Schizophrenie: verminderte Suppression bei Aufgaben.","src":["Raichle et al., PNAS 2001","Carhart-Harris et al., PNAS 2012","Daws et al., Nat Med 2022"],"mcq":[{"q":"Welchen Befund nach Psilocybin-Therapie bei Depression berichteten Daws et al. (Nat Med 2022)?","a":"Abnahme der Netzwerk-Modularität im Sinne stärkerer globaler Integration","w":["Zunahme der Netzwerk-Modularität im Sinne stärkerer Segregation","Selektive Zunahme der Integrität des Default-Mode-Netzwerks","Keine Konnektivitätsänderung, nur eine Zunahme des Amygdalavolumens"],"why":"Die verminderte Modularität korrelierte mit der Besserung und fand sich unter Escitalopram nicht."},{"q":"Welche Region gehört NICHT zum Kern des Default-Mode-Netzwerks?","a":"Anteriore Insel","w":["Präcuneus","Gyrus angularis","Ventromedialer PFC"],"why":"Die anteriore Insel ist Kernknoten des Salienznetzwerks, das zwischen DMN und exekutivem Netz umschaltet."}]},{"id":"salienz","name":"Salienznetzwerk","level":2,"regions":["insula","dacc","amygdala","vta","thalamus"],"fn":"Erkennt verhaltensrelevante innere und äußere Reize und schaltet zwischen Default-Mode-Netzwerk und zentralem exekutivem Netzwerk um; Kern sind anteriore Insel und dACC, ergänzt durch Amygdala, Thalamus und Mittelhirn.","psych":"Triple-Network-Modell: aberrante Salienzzuweisung bei Psychose, Hyperreaktivität bei Angst, Bindung an innere Inhalte bei Depression, Drogenreize bei Sucht. Transdiagnostischer Graue-Substanz-Verlust in dACC und anteriorer Insel.","src":["Seeley et al., J Neurosci 2007","Sridharan et al., PNAS 2008","Menon, Trends Cogn Sci 2011","Goodkind et al., JAMA Psychiatry 2015"],"mcq":[{"q":"Welche Struktur wurde als kausaler Schalter zwischen Default-Mode- und zentralem exekutivem Netzwerk beschrieben?","a":"Rechte fronto-insuläre Rinde (anteriore Insel)","w":["Linker dorsolateraler präfrontaler Kortex","Posteriorer cingulärer Kortex","Rechter Hippocampus"],"why":"Sridharan et al. 2008 zeigten, dass Aktivität der rechten anterioren Insel dem Umschalten zeitlich vorausgeht."},{"q":"Was fanden Goodkind et al. (JAMA Psychiatry 2015) in einer transdiagnostischen Metaanalyse?","a":"Gemeinsamen Graue-Substanz-Verlust in dACC und anteriorer Insel","w":["Hippocampusverlust nur bei Schizophrenie, sonst keine Befunde","Volumenzunahme des PCC über alle Diagnosen hinweg","Störungsspezifische Atrophien ohne gemeinsame Regionen"],"why":"Über Schizophrenie, bipolare Störung, Depression, Sucht, Zwang und Angst hinweg zeigte sich ein gemeinsames Substrat im Salienznetzwerk."}]},{"id":"cen","name":"Zentrales exekutives Netzwerk","level":2,"regions":["dlpfc","ppc","vlpfc"],"fn":"Frontoparietales Kontrollnetzwerk: hält Ziele und Regeln im Arbeitsgedächtnis, steuert Aufmerksamkeit top-down und ermöglicht Problemlösen; bei Aufgaben aktiv, antikorreliert mit dem DMN.","psych":"Schizophrenie und Depression: veränderte Aktivierung und Konnektivität mit kognitiven Defiziten. ADHS: verminderte frontoparietale Aktivierung. rTMS-Zielort dlPFC bei Depression. Psychedelika: akut verminderte Abgrenzung von DMN und exekutivem Netz.","src":["Menon, Trends Cogn Sci 2011"],"mcq":[{"q":"Welches Modell beschreibt psychische Störungen als gestörte Interaktion von DMN, Salienz- und exekutivem Netzwerk?","a":"Triple-Network-Modell (Menon)","w":["Zwei-Prozess-Modell der Schlafregulation (Borbély)","Dual-Process-Modell des Denkens (Kahneman)","Gate-Control-Modell des Schmerzes (Melzack & Wall)"],"why":"Menon 2011 führte Psychopathologie auf eine gestörte Salienz-gesteuerte Umschaltung zwischen DMN und exekutivem Netz zurück."},{"q":"Welcher Befund beschreibt den dlPFC bei Schizophrenie während Arbeitsgedächtnisaufgaben am besten?","a":"Ineffiziente Aktivierung, deren Richtung von der Aufgabenlast abhängt","w":["Generell stärkere Aktivierung ohne jedes Leistungsdefizit","Fehlende parietale, aber normale präfrontale Aktivierung","Rein subkortikale Defizite bei intaktem Präfrontalkortex"],"why":"Je nach Last zeigen Patienten Hyper- oder Hypoaktivierung bei schlechterer Leistung – Modell der Ineffizienz."}]},{"id":"belohnung","name":"Belohnungssystem","level":2,"regions":["vta","nacc","vmpfc","ofc","amygdala","hippocampus"],"fn":"VTA-Dopamin meldet Belohnungsvorhersagefehler an NAcc und PFC; OFC und vmPFC repräsentieren den Wert, Amygdala und Hippocampus liefern emotionale und kontextuelle Assoziationen; steuert Motivation und Verstärkungslernen.","psych":"Sucht (Anreiz-Sensitivierung, Verlagerung zum dorsalen Striatum), Anhedonie bei Depression, Negativsymptomatik, Binge-Eating. GLP-1-RA dämpfen im Tiermodell den Konsum von Alkohol und anderen Substanzen; erste randomisierte Studien beim Menschen liegen vor.","src":["Schultz et al., Science 1997","Everitt & Robbins, Nat Neurosci 2005"],"mcq":[{"q":"Welche Verlagerung beschreibt das Modell von Everitt & Robbins beim Übergang zu zwanghaftem Drogenkonsum?","a":"Von ventralem zu dorsalem Striatum über striatonigrostriatale Spiralen","w":["Von dorsalem zu ventralem Striatum über kortikale Rückprojektionen","Vom Kleinhirn zum Hippocampus über den Tractus perforans","Vom OFC zum primär-motorischen Kortex über den Balken"],"why":"Zielgerichtetes Verhalten (ventral) wird zur Gewohnheit (dorsolateral), vermittelt über aufsteigende dopaminerge Spiralen (Haber)."},{"q":"Welcher PET-Befund ist bei Abhängigkeitserkrankungen am konsistentesten beschrieben?","a":"Verminderte striatale D2/D3-Rezeptorverfügbarkeit","w":["Erhöhte striatale D2/D3-Rezeptorverfügbarkeit","Erhöhte präsynaptische Dopaminsynthese im Striatum","Unveränderte D2-Verfügbarkeit bei erhöhter SERT-Dichte"],"why":"Erhöhte präsynaptische Dopaminsynthese ist ein Schizophrenie-Befund; bei Sucht sind D2-Verfügbarkeit und Dopaminfreisetzung eher vermindert."}]},{"id":"furcht","name":"Furchtkreis","level":3,"regions":["amygdala","vmpfc","hippocampus","dacc","insula","bnst","hypothal","thalamus"],"fn":"Thalamus und Kortex → laterale Amygdala (Assoziation) → zentrale Amygdala → Hypothalamus und Hirnstamm (Furchtreaktion); der vmPFC hemmt bei Extinktion, der Hippocampus liefert Kontext, der dACC fördert den Furchtausdruck, der BNST anhaltende Angst.","psych":"Angststörungen und PTBS: Übergeneralisierung, gestörter Extinktionsabruf. Expositionstherapie nutzt Extinktion als neues Hemmungslernen, nicht als Löschung; D-Cycloserin-Augmentation brachte uneinheitliche Ergebnisse. Rekonsolidierung: experimentell.","src":["Milad & Quirk, Annu Rev Psychol 2012"],"mcq":[{"q":"Warum kehrt Furcht nach erfolgreicher Exposition in einem neuen Kontext oft zurück (Renewal)?","a":"Extinktion ist kontextabhängiges Hemmungslernen, die Furchtspur bleibt erhalten","w":["Extinktion löscht die Furchtspur, Renewal ist ein kompletter Neuerwerb","Der Hippocampus speichert die Furcht dauerhaft, die Amygdala nicht mehr","Exposition wirkt nur über Cortisol und verliert sich nach dessen Abbau"],"why":"Der Hippocampus kodiert den Extinktionskontext; außerhalb davon setzt sich die ursprüngliche Assoziation wieder durch."},{"q":"Welche Funktion wird dem dACC beim Menschen (prälimbischer Kortex bei Nagern) im Furchtkreis zugeschrieben?","a":"Förderung des Furchtausdrucks","w":["Abruf der Extinktion","Kodierung des räumlichen Kontexts","Primäre Schmerzdiskrimination"],"why":"Nach Milad & Quirk fördert der dACC/prälimbische Kortex den Furchtausdruck, der vmPFC/infralimbische Kortex den Extinktionsabruf."}]},{"id":"cstc","name":"Kortiko-striato-thalamo-kortikale Schleife (CSTC)","level":3,"regions":["ofc","dacc","dlpfc","m1","caudate","putamen","nacc","gp","sn","thalamus"],"fn":"Parallele Schleifen (motorisch, okulomotorisch, dorsolateral-präfrontal, lateral-orbitofrontal, anterior-cingulär) vom Kortex über Striatum, GPi/SNr und Thalamus zurück; die direkte Bahn fördert, die indirekte hemmt Handlungen.","psych":"Zwangsstörung: OFC/ACC-Caudatus-Hyperaktivität. Tourette: motorische Schleife. Parkinson und Huntington: motorische Schleife. Schizophrenie: erhöhte Dopaminsynthese im assoziativen Striatum. Psychedelika: Modell eines geschwächten thalamischen Filters.","src":["Alexander et al., Annu Rev Neurosci 1986","Howes et al., Arch Gen Psychiatry 2009","Vollenweider & Geyer, Brain Res Bull 2001"],"mcq":[{"q":"Wo ist die präsynaptische Dopaminsynthesekapazität bei Schizophrenie und Prodrom im PET am deutlichsten erhöht?","a":"Assoziatives (dorsales) Striatum","w":["Limbisches (ventrales) Striatum","Dorsolateraler präfrontaler Kortex","Sensomotorisches Striatum (posteriores Putamen)"],"why":"Howes et al. 2009 fanden die Erhöhung v. a. im assoziativen Striatum, das mit dem dlPFC verbunden ist – nicht im klassisch vermuteten ventralen."},{"q":"Was bewirkt die direkte Bahn der Basalganglien netto auf den Thalamus?","a":"Enthemmung über Hemmung von GPi/SNr","w":["Hemmung über Aktivierung von GPi/SNr","Erregung über eine monosynaptische striatale Glutamatprojektion","Keine, da sie nur auf den Hirnstamm projiziert"],"why":"Striatale D1-MSN hemmen GPi/SNr, die ihrerseits den Thalamus tonisch hemmen – Netto-Enthemmung."}]},{"id":"hpa","name":"HPA-Achse (Hypothalamus-Hypophysen-Nebennierenrinden-Achse)","level":3,"regions":["hypothal","hypophyse_p","hippocampus","amygdala","vmpfc"],"fn":"PVN-CRH (mit AVP) → ACTH aus der Hypophyse → Cortisol aus der Nebennierenrinde (außerhalb des Gehirns); Rückkopplung über GR/MR in Hypothalamus, Hypophyse und Hippocampus; die Amygdala aktiviert, Hippocampus und mPFC hemmen.","psych":"Depression, v. a. melancholisch oder psychotisch: Hypercortisolismus, gestörte Dexamethason-Suppression. Morbus Cushing: Depression, Psychose. Glukokortikoidtherapie: Manie oder Psychose möglich. FKBP5-Varianten modulieren die Wirkung von Kindheitstrauma.","src":["Binder et al., JAMA 2008","Klengel et al., Nat Neurosci 2013"],"mcq":[{"q":"Welcher Rezeptor vermittelt bei basalen Cortisolspiegeln überwiegend die Glukokortikoidwirkung im Hippocampus?","a":"Mineralokortikoidrezeptor (hohe Affinität)","w":["Glukokortikoidrezeptor (hohe Affinität)","Mineralokortikoidrezeptor (niedrige Affinität)","CRH-Rezeptor Typ 2"],"why":"Der MR ist schon basal weitgehend besetzt; der niedrigaffine GR wird erst bei Stress- und Tagesgipfelspiegeln relevant."},{"q":"Welche Funktion hat FKBP5 im Glukokortikoid-System?","a":"Co-Chaperon, das die GR-Sensitivität senkt (ultrakurze Rückkopplung)","w":["Enzym der Cortisolsynthese in der Nebennierenrinde","Transporter für Cortisol über die Blut-Hirn-Schranke","Rezeptor für ACTH in der Nebennierenrinde"],"why":"Cortisol induziert FKBP5, das die GR-Affinität senkt; risikoassoziierte Varianten verlängern Stressantworten."}]},{"id":"papez","name":"Papez-Kreis","level":3,"regions":["hippocampus","mammillar","thalamus","dacc","pcc","entorhinal"],"fn":"Hippocampus → Fornix → Corpora mammillaria → Tractus mammillothalamicus → Nucleus anterior thalami → Gyrus cinguli → Cingulum → entorhinaler Kortex → Hippocampus. 1937 als Emotionskreis vorgeschlagen, heute v. a. für episodisches Gedächtnis.","psych":"Korsakow-Syndrom (Corpora mammillaria, Thalamus), Fornixläsionen (z. B. Kolloidzyste, Operation) mit anterograder Amnesie, limbische Enzephalitis, HSV-Enzephalitis. Fornix-THS bei Alzheimer experimentell.","src":["Papez, Arch Neurol Psychiatry 1937"],"mcq":[{"q":"Welche Struktur gehört NICHT zum klassischen Papez-Kreis?","a":"Amygdala","w":["Corpora mammillaria","Nucleus anterior thalami","Gyrus cinguli"],"why":"Die Amygdala wurde erst später (Yakovlev, MacLean) in das erweiterte limbische System aufgenommen."},{"q":"Welche Gedächtnisstörung kann eine Kolloidzyste am Foramen interventriculare verursachen?","a":"Anterograde Amnesie durch Schädigung des Fornix","w":["Semantische Amnesie durch Schädigung des Temporalpols","Prosopagnosie durch Schädigung des Gyrus fusiformis","Prozedurale Lerndefizite durch Schädigung des Kleinhirns"],"why":"Die Fornixsäulen liegen direkt am Foramen; Kompression oder operative Schädigung unterbricht den Papez-Kreis."}]}],"transmitters":[{"id":"ht_raphe","name":"Serotonerges System","nt":"Serotonin (5-HT)","level":2,"from":"raphe","to":["dlpfc","vmpfc","sgacc","ofc","hippocampus","amygdala","caudate","putamen","nacc","hypothal","thalamus","cerebellum"],"fn":"Raphe-Neurone innervieren nahezu das gesamte ZNS; Serotonin moduliert Stimmung, Impulskontrolle, Schlaf, Appetit, Schmerz und Plastizität über sieben Rezeptorfamilien (5-HT3 ionotrop, die übrigen G-Protein-gekoppelt).","psych":"SSRI/SNRI und Vortioxetin (SERT), Buspiron (5-HT1A), atypische Antipsychotika (5-HT2A-Antagonismus), Ondansetron (5-HT3), Triptane (5-HT1B/1D), Psychedelika (5-HT2A-Agonismus). Serotonin-Syndrom. 5-HT2B-Agonismus als kardiales Antitarget.","mcq":[{"q":"Welcher Befund spricht GEGEN eine einfache Serotoninmangel-Hypothese der Depression?","a":"Tryptophan-Depletion senkt bei Gesunden ohne Risikofaktoren die Stimmung kaum","w":["Tryptophan-Depletion senkt bei remittierten SSRI-Patienten oft die Stimmung","Hemmung der 5-HT-Synthese hebt bei SSRI-Respondern die Wirkung auf","Hemmstoffe der MAO-A wirken bei Depression antidepressiv"],"why":"Ein reiner Mangel müsste auch Gesunde depressiv machen; die Distraktoren sind Befunde, die die Hypothese eher stützen."},{"q":"Agonismus an welchem Rezeptor verursachte unter Fenfluramin und Pergolid Herzklappenfibrosen?","a":"5-HT2B","w":["5-HT2A","5-HT2C","5-HT1A"],"why":"5-HT2B auf Klappeninterstitialzellen fördert Proliferation; das ist auch für wiederholte Gaben serotonerger Agonisten relevant."}]},{"id":"da_meso","name":"Mesolimbische Dopaminbahn","nt":"Dopamin","level":2,"from":"vta","to":["nacc","amygdala","hippocampus","septum"],"fn":"VTA → Nucleus accumbens, Amygdala, Hippocampus und Septum: phasisches Dopamin kodiert Belohnungsvorhersagefehler und Anreizsalienz und steuert Motivation und Verstärkungslernen.","psych":"Positivsymptome der Schizophrenie als aberrante Salienz, antipsychotische Wirkung über D2-Blockade. Sucht: missbrauchte Substanzen erhöhen Dopamin im NAcc. Anhedonie bei Depression. Stimulanzien, Opioide, Nikotin und Alkohol setzen hier an.","src":["Kapur, Am J Psychiatry 2003","Di Chiara & Imperato, PNAS 1988"],"mcq":[{"q":"Welches Konzept beschreibt Psychose als Folge dysregulierter Dopaminfreisetzung, die neutralen Reizen Bedeutung verleiht?","a":"Aberrante Salienz","w":["Hypofrontalität","Defizit im sensorischen Gating","Dyskonnektivitäts-Hypothese"],"why":"Kapur 2003: Dopamin vermittelt Salienz; dysreguliert erhalten belanglose Reize Bedeutung, Wahn ist der Erklärungsversuch."},{"q":"Warum bessern sich psychotische Symptome nach Kapur oft erst allmählich, obwohl die D2-Blockade sofort eintritt?","a":"Aberrante Salienzen müssen erst verblassen; neue werden nur nicht mehr gebildet","w":["D2-Rezeptoren müssen sich erst über Wochen hochregulieren","Antipsychotika reichern sich erst nach Wochen im Gehirn an","Die Wirkung beruht primär auf langsamer 5-HT1A-Desensitisierung"],"why":"Die Blockade dämpft die Salienzbildung; bestehende Überzeugungen lösen sich über Extinktion langsam auf."}]},{"id":"da_mesocort","name":"Mesokortikale Dopaminbahn","nt":"Dopamin","level":2,"from":"vta","to":["dlpfc","vmpfc","dacc","ofc"],"fn":"VTA → präfrontaler und cingulärer Kortex: Dopamin stabilisiert v. a. über D1 Arbeitsgedächtnis und kognitive Kontrolle; im PFC wird es wegen geringer DAT-Dichte großenteils über NET aufgenommen und durch COMT abgebaut.","psych":"Schizophrenie: präfrontale Hypofunktion mit Negativsymptomen und kognitiven Defiziten. COMT-Val158Met beeinflusst das präfrontale Dopamin. ADHS: Stimulanzien und Atomoxetin erhöhen präfrontales Dopamin.","src":["Davis et al., Am J Psychiatry 1991","Howes & Kapur, Schizophr Bull 2009"],"mcq":[{"q":"Warum erhöht der NET-Hemmer Atomoxetin Dopamin im präfrontalen Kortex, im Striatum aber kaum?","a":"Im PFC wird Dopamin mangels DAT überwiegend über NET aufgenommen","w":["Atomoxetin hemmt im PFC zusätzlich die MAO-B","Im Striatum fehlen D1-Rezeptoren weitgehend","Atomoxetin wirkt als kortikal selektiver D1-Agonist"],"why":"Im Striatum dominiert der DAT, den Atomoxetin nicht hemmt; daher fehlt dort ein Dopaminanstieg und das Missbrauchspotenzial ist gering."},{"q":"Welches COMT-Allel bedingt höhere Enzymaktivität und damit weniger präfrontales Dopamin?","a":"Val158","w":["Met158","Val66","Met66"],"why":"Val/Met an Position 66 betrifft BDNF; bei COMT ist das Val158-Enzym thermostabiler und aktiver."}]},{"id":"da_nigro","name":"Nigrostriatale Dopaminbahn","nt":"Dopamin","level":2,"from":"sn","to":["caudate","putamen"],"fn":"Substantia nigra pars compacta → dorsales Striatum: Dopamin fördert über D1 die direkte und hemmt über D2 die indirekte Bahn – netto Bewegungsinitiierung und Gewohnheitslernen.","psych":"Parkinson durch Degeneration. Unter D2-Antagonisten extrapyramidale Symptome: akute Dystonie, Akathisie, Parkinsonoid, Spätdyskinesien. Dopaminerge Parkinson-Therapie kann Impulskontrollstörungen auslösen (eher ventrales Striatum).","mcq":[{"q":"Welche Substanzklasse ist in den USA zur Behandlung von Spätdyskinesien zugelassen?","a":"VMAT2-Hemmer (z. B. Valbenazin)","w":["Anticholinergika (z. B. Biperiden)","Dopaminagonisten (z. B. Pramipexol)","COMT-Hemmer (z. B. Entacapon)"],"why":"VMAT2-Hemmer vermindern die Dopaminfreisetzung; Anticholinergika können Spätdyskinesien verschlechtern."},{"q":"Welche extrapyramidale Störung tritt nach Beginn eines hochpotenten Antipsychotikums typischerweise am frühesten auf?","a":"Akute Dystonie","w":["Spätdyskinesie","Parkinsonoid","Malignes neuroleptisches Syndrom"],"why":"Akute Dystonien treten meist innerhalb von Stunden bis Tagen auf, Parkinsonoid nach Wochen, Spätdyskinesien nach Monaten."}]},{"id":"da_tubero","name":"Tuberoinfundibuläre Dopaminbahn","nt":"Dopamin","level":2,"from":"hypothal","to":["hypophyse_p"],"fn":"Nucleus arcuatus → Eminentia mediana → Pfortaderkreislauf → Hypophysenvorderlappen: Dopamin hemmt über D2-Rezeptoren laktotropher Zellen tonisch die Prolaktinfreisetzung.","psych":"D2-Antagonisten verursachen Hyperprolaktinämie (Galaktorrhoe, Amenorrhoe, sexuelle Dysfunktion, Osteoporose). Dopaminagonisten wie Cabergolin beim Prolaktinom. Aripiprazol als Zusatz senkt antipsychotikabedingt erhöhtes Prolaktin.","mcq":[{"q":"Unter Antipsychotikum ist Prolaktin erhöht, zusätzlich bestehen Kopfschmerz und ein Gesichtsfelddefekt. Was ist vorrangig?","a":"Hypophysenadenom per MRT ausschließen","w":["Normaldruckhydrozephalus per Lumbalpunktion ausschließen","Wernicke-Enzephalopathie mit Thiamin behandeln","Auf Haloperidol umstellen und Prolaktin kontrollieren"],"why":"Gesichtsfelddefekt und Kopfschmerz weisen auf ein raumforderndes Makroadenom mit Chiasmakompression hin."},{"q":"Wie unterscheidet sich Quetiapin von Risperidon in Bezug auf Prolaktin?","a":"Quetiapin erhöht Prolaktin meist kaum (schnelle D2-Dissoziation)","w":["Quetiapin erhöht Prolaktin stärker (langsame D2-Dissoziation)","Beide erhöhen Prolaktin in vergleichbarem Ausmaß","Quetiapin senkt Prolaktin als voller D2-Agonist"],"why":"Schwache, rasch dissoziierende D2-Bindung und gute Hirngängigkeit halten die hypophysäre Blockade gering."}]},{"id":"na_lc","name":"Noradrenerges System","nt":"Noradrenalin","level":2,"from":"lc","to":["dlpfc","vmpfc","thalamus","hippocampus","amygdala","hypothal","cerebellum"],"fn":"Locus coeruleus → nahezu gesamtes ZNS: Noradrenalin steigert Wachheit, Aufmerksamkeit und Signal-Rausch-Verhältnis (α2A im PFC) und vermittelt die Stressreaktion; tonischer vs. phasischer Modus nach dem Adaptive-Gain-Modell.","psych":"Depression (SNRI, Bupropion, Mirtazapin über α2-Blockade), ADHS (Atomoxetin, Guanfacin), PTBS-Alpträume (Prazosin, α1), Opioidentzug (Clonidin, Lofexidin), Panikstörung.","src":["Aston-Jones & Cohen, Annu Rev Neurosci 2005"],"mcq":[{"q":"Wie steigert Mirtazapin die Freisetzung von Noradrenalin und Serotonin?","a":"Blockade präsynaptischer α2-Auto- und Heterorezeptoren","w":["Hemmung der Wiederaufnahme über NET und SERT","Hemmung des Abbaus durch die MAO-A","Agonismus an präsynaptischen α2-Rezeptoren"],"why":"α2-Rezeptoren bremsen die Freisetzung; zusätzlich blockiert Mirtazapin 5-HT2-, 5-HT3- und H1-Rezeptoren."},{"q":"Welcher LC-Modus ist nach dem Adaptive-Gain-Modell mit fokussierter Aufgabenbearbeitung verbunden?","a":"Mäßige tonische Aktivität mit ausgeprägten phasischen Antworten","w":["Hohe tonische Aktivität mit schwachen phasischen Antworten","Sehr niedrige tonische Aktivität ohne phasische Antworten","Gleichmäßig hohe tonische und phasische Aktivität"],"why":"Hoher tonischer Modus fördert Ablenkbarkeit und Exploration, sehr niedriger entspricht Schläfrigkeit."}]},{"id":"ach","name":"Cholinerges System","nt":"Acetylcholin","level":2,"from":"nbm","to":["dlpfc","vmpfc","ppc","v1","amygdala","hippocampus"],"fn":"Basales Vorderhirn (Nucleus basalis Meynert → Neokortex, Amygdala; mediales Septum → Hippocampus) und Hirnstamm (PPT/LDT → Thalamus, VTA; Wachheit, REM-Schlaf): Aufmerksamkeit, Gedächtnisenkodierung, Plastizität.","psych":"Alzheimer und Lewy-Körper-Demenz: Cholinesterasehemmer. Anticholinerges Delir durch Anticholinergika, Trizyklika, Clozapin. Xanomelin-Trospium (M1/M4-Agonist mit peripherem Antagonisten) wurde 2024 in den USA als Antipsychotikum ohne D2-Blockade zugelassen.","src":["Whitehouse et al., Science 1982"],"mcq":[{"q":"Warum wird Xanomelin mit Trospium kombiniert?","a":"Trospium blockiert periphere Muskarinrezeptoren und ist kaum hirngängig","w":["Trospium verstärkt die zentrale M4-Wirkung von Xanomelin","Trospium hemmt den hepatischen Abbau von Xanomelin","Trospium blockiert zusätzlich zentrale D2-Rezeptoren"],"why":"Als quartäres Amin bleibt Trospium peripher und mildert cholinerge Nebenwirkungen, ohne die zentrale Wirkung zu blockieren."},{"q":"Welcher Wirkstoff hat die höchste anticholinerge Last und ist bei Älteren mit Delirrisiko besonders zu meiden?","a":"Amitriptylin","w":["Paroxetin","Mirtazapin","Sertralin"],"why":"Paroxetin ist unter den SSRI am stärksten anticholinerg, bleibt aber deutlich unter tertiären Trizyklika wie Amitriptylin."}]},{"id":"glu","name":"Glutamaterges System","nt":"Glutamat","level":2,"from":"pyramidal","to":["dlpfc","ppc","caudate","putamen","nacc","thalamus"],"fn":"Wichtigster erregender Transmitter: kortikokortikale und kortikostriatale Projektionen der Pyramidenzellen; ionotrope (AMPA, NMDA, Kainat) und metabotrope Rezeptoren; Glutamat-Glutamin-Zyklus mit Astrozyten.","psych":"NMDA-Hypofunktions-Hypothese der Schizophrenie. Esketamin-Nasenspray bei therapieresistenter Depression; Dextromethorphan-Bupropion bei Depression. Memantin bei Alzheimer, Riluzol bei ALS. Anti-NMDAR-Enzephalitis. Exzitotoxizität bei Schlaganfall.","mcq":[{"q":"Welche pharmakokinetische Rolle spielt Bupropion in der Kombination mit Dextromethorphan?","a":"CYP2D6-Hemmung erhöht die Dextromethorphan-Spiegel","w":["NMDA-Antagonismus verstärkt die Dextromethorphanwirkung","MAO-Hemmung verlangsamt den Dextromethorphanabbau","σ1-Antagonismus hebt dessen Nebenwirkungen auf"],"why":"Dextromethorphan wird sonst über CYP2D6 rasch abgebaut; Bupropion wirkt zusätzlich als NDRI."},{"q":"Wodurch wird synaptisches Glutamat überwiegend entfernt?","a":"Astrozytäre Transporter (EAAT1/2) und Umwandlung zu Glutamin","w":["Enzymatischer Abbau im Spalt durch eine Glutamatoxidase","Direkte Aufnahme in Vesikel über VMAT2","Diffusion ins Blut über die Blut-Hirn-Schranke"],"why":"Astrozyten wandeln Glutamat über die Glutaminsynthetase in Glutamin um, das an Neurone zurückgeht."}]},{"id":"gaba_str","name":"Striatale GABA-Ausgangsbahnen","nt":"GABA","level":2,"from":"putamen","to":["gp","sn"],"fn":"Mittelgroße bedornte Projektionsneurone (MSN) stellen die große Mehrheit der Striatumneurone: D1-MSN (direkt) → GPi/SNr, D2-MSN (indirekt) → GPe; GPi und SNr hemmen ihrerseits GABAerg den Thalamus.","psych":"Huntington (früher Verlust der D2-MSN), Parkinson (Ungleichgewicht direkt/indirekt), Sucht (D1- und D2-MSN im Nucleus accumbens), extrapyramidale Symptome unter Antipsychotika. Kotransmitter: Substanz P und Dynorphin (direkt), Enkephalin (indirekt).","mcq":[{"q":"Welche Kotransmitter-Kombination kennzeichnet MSN der direkten Bahn?","a":"GABA mit Substanz P und Dynorphin (D1)","w":["GABA mit Enkephalin (D2)","Glutamat mit Substanz P (D1)","GABA mit Neuropeptid Y und Somatostatin"],"why":"NPY und Somatostatin finden sich in striatalen Interneuronen, Enkephalin in MSN der indirekten Bahn."},{"q":"Wohin projizieren D2-MSN der indirekten Bahn primär?","a":"Globus pallidus externus","w":["Globus pallidus internus","Substantia nigra pars compacta","Nucleus ventralis lateralis thalami"],"why":"Vom GPe führt die indirekte Bahn über den Nucleus subthalamicus zu GPi/SNr."}]},{"id":"gaba_int","name":"Kortikale GABA-Interneurone","nt":"GABA","level":2,"from":"interneuron","to":["pyramidal","apical"],"fn":"Lokale Hemmung über GABA-A (Chloridkanal, schnell; Bindestelle für Benzodiazepine, Barbiturate, Neurosteroide) und GABA-B (Gi/o, langsam): PV-Zellen am Soma, SST-Zellen an apikalen Dendriten, VIP-Zellen an anderen Interneuronen.","psych":"Benzodiazepine bei Angst, Alkoholentzug und Katatonie; Neurosteroide (Brexanolon, Zuranolon) bei postpartaler Depression; Parvalbumin-Defizit bei Schizophrenie; Epilepsie; Disinhibition als Ketamin-Mechanismus; Baclofen (GABA-B).","src":["Lewis et al., Nat Rev Neurosci 2005"],"mcq":[{"q":"Wo binden Benzodiazepine am GABA-A-Rezeptor?","a":"An der Grenzfläche zwischen α- und γ2-Untereinheit","w":["An der Grenzfläche zwischen α- und β-Untereinheit","An der δ-Untereinheit extrasynaptischer Rezeptoren","In der Ionenkanalpore an der Picrotoxin-Stelle"],"why":"Die α/β-Grenzfläche bindet GABA selbst; δ-haltige Rezeptoren haben keine Benzodiazepinstelle."},{"q":"Warum wirken Neurosteroide wie Zuranolon auch an extrasynaptischen GABA-A-Rezeptoren, Benzodiazepine aber kaum?","a":"Extrasynaptische δ-haltige Rezeptoren haben keine γ2-Benzodiazepinstelle","w":["Extrasynaptische Rezeptoren besitzen keine GABA-Bindestelle","Neurosteroide binden an GABA-B- statt an GABA-A-Rezeptoren","Benzodiazepine erreichen extrasynaptische Membranen nicht"],"why":"Neurosteroide binden an Transmembranstellen auch δ-haltiger Rezeptoren und verstärken so die tonische Hemmung."}]},{"id":"orexin","name":"Orexin-/Hypocretin-System","nt":"Orexin A/B (Hypocretin 1/2)","level":2,"from":"hypothal","to":["lc","raphe","vta","nbm","thalamus","brainstem"],"fn":"Neurone des lateralen Hypothalamus stabilisieren Wachheit, indem sie LC, Raphe, tuberomammillären Kern, basales Vorderhirn und VTA aktivieren; verknüpfen Energiestatus (Hunger aktiviert, Leptin hemmt) mit Arousal.","psych":"Narkolepsie Typ 1: Verlust der Orexin-Neurone, Liquor-Hypocretin erniedrigt, Kataplexie. Duale Orexin-Rezeptorantagonisten (Suvorexant, Lemborexant, Daridorexant) bei Insomnie; Orexin-2-Agonisten in klinischer Prüfung. Sucht: Orexin fördert Drogensuche.","mcq":[{"q":"Welche Konstellation spricht am stärksten für Narkolepsie Typ 1?","a":"Kataplexie oder erniedrigtes Hypocretin-1 im Liquor","w":["Hypnagoge Halluzinationen als einziges Zusatzsymptom","Tagesschläfrigkeit mit normalem Liquor-Hypocretin","Schlafparalysen bei fehlendem HLA-DQB1*06:02"],"why":"Typ 1 wird über Kataplexie oder Hypocretinmangel definiert; Halluzinationen und Schlafparalysen sind unspezifisch."},{"q":"Wie unterscheidet sich der Wirkmechanismus dualer Orexin-Rezeptorantagonisten von dem der Benzodiazepine?","a":"Sie dämpfen Wachsignale, statt die GABAerge Hemmung global zu verstärken","w":["Sie verstärken wie Benzodiazepine die GABA-A-Hemmung","Sie wirken als Agonisten an Melatoninrezeptoren","Sie blockieren H1-Rezeptoren im tuberomammillären Kern"],"why":"Die gezielte Blockade des Wachsystems erklärt das günstigere Profil bezüglich Atemdepression und Abhängigkeit."}]},{"id":"histamin","name":"Histaminerges System","nt":"Histamin","level":2,"from":"hypothal","to":["dlpfc","vmpfc","thalamus","nbm","hippocampus","amygdala"],"fn":"Tuberomammillärer Kern im posterioren Hypothalamus → gesamter Kortex: fördert Wachheit und Aufmerksamkeit, aktiv im Wachen, still im Schlaf; H1 (postsynaptisch, Gq), H2, H3 (präsynaptischer Autorezeptor).","psych":"H1-Blockade erklärt Sedierung und Gewichtszunahme vieler Psychopharmaka (Quetiapin, Mirtazapin, Olanzapin, Doxepin). Pitolisant (inverser H3-Agonist) bei Narkolepsie. Im Schlaf hemmen GABAerge VLPO-Neurone den tuberomammillären Kern.","mcq":[{"q":"Wie wirkt Pitolisant wachheitsfördernd?","a":"Inverser Agonismus an H3-Autorezeptoren steigert die Histaminfreisetzung","w":["Agonismus an postsynaptischen H1-Rezeptoren im Kortex","Hemmung des Histaminabbaus durch die Histamin-N-Methyltransferase","Agonismus an Orexin-2-Rezeptoren des Hypothalamus"],"why":"H3-Autorezeptoren bremsen die Histaminfreisetzung; ihre Hemmung enthemmt das Wachsystem."},{"q":"Die Affinität zu welchem Rezeptor sagt die antipsychotikainduzierte Gewichtszunahme am besten voraus?","a":"H1-Rezeptor (gemeinsam mit 5-HT2C)","w":["D3-Rezeptor (gemeinsam mit 5-HT1A)","α2-Rezeptor (gemeinsam mit M2)","H3-Rezeptor (gemeinsam mit 5-HT3)"],"why":"Olanzapin und Clozapin mit hoher H1-Affinität verursachen die stärkste Gewichtszunahme."}]}],"disorders":[{"id":"mdd","name":"Depression (MDD)","dis":"depression","level":3,"regions":[{"r":"sgacc","how":"hyper","note":"Erhöhte Aktivität in akuter und therapieresistenter Depression; sinkt bei Ansprechen auf viele Therapien (Mayberg)"},{"r":"amygdala","how":"hyper","note":"Verstärkte Reaktion auf negative Reize (negativer Verarbeitungsbias); normalisiert sich früh unter SSRI"},{"r":"hippocampus","how":"atrophy","note":"Volumenminderung v. a. bei rezidivierendem Verlauf und Beginn vor 21 J. (ENIGMA, Schmaal 2016)"},{"r":"dlpfc","how":"hypo","note":"Linksbetonte Hypoaktivität → schwächere kognitive Kontrolle über Emotionen; Zielregion der rTMS"},{"r":"nacc","how":"hypo","note":"Abgeschwächte Antwort bei Belohnungserwartung → Anhedonie, Antriebsmangel"},{"r":"habenula","how":"hyper","note":"Laterale Habenula: Burst-Feuern hemmt VTA und Raphe (Tiermodelle); wird von Ketamin blockiert"},{"r":"pcc","how":"dysconnect","note":"Erhöhte DMN-Konnektivität (PCC–mPFC) korreliert mit Rumination"}],"nt":["Serotonin","Noradrenalin","Dopamin","Glutamat/GABA","CRH/Cortisol (HPA-Achse)"],"models":["Monoaminhypothese: erklärt den Wirkort der Antidepressiva, nicht aber Wirklatenz und Krankheitsursache","Neuroplastizität: Stress senkt BDNF und Spine-Dichte; wirksame Therapien kehren dies um","Inflammation: Subgruppe mit erhöhtem CRP/IL-6, mehr Anhedonie und schlechterem SSRI-Ansprechen","HPA-Achse: erhöhtes CRH/Cortisol, fehlende Dexamethason-Suppression bei einem Teil (v. a. melancholisch)","Kognitiv-neuropsychologisch (Harmer): negativer Bias in Wahrnehmung und Gedächtnis als früher Angriffspunkt"],"nut":"Mediterrane Kost als Zusatztherapie wirksam (SMILES-RCT, klein, unverblindet); EPA-reiche Omega-3 adjuvant mit moderater Evidenz; Vitamin D verhinderte Depression nicht (VITAL-DEP).","mcq":[{"q":"Bei welcher Gruppe löst akute Tryptophan-Depletion am zuverlässigsten einen depressiven Rückfall aus?","a":"Remittierte Patienten unter SSRI-Therapie","w":["Gesunde ohne familiäre Vorbelastung","Remittierte Patienten unter Desipramin","Akut depressive, unbehandelte Patienten"],"why":"Serotonin ist für die SSRI-Wirkung nötig (Delgado 1990), ein Mangel erklärt Depression aber nicht: Gesunde und noradrenerg Behandelte reagieren kaum."},{"q":"Welche Veränderung im sgACC (BA 25) gilt nach Mayberg als gemeinsamer Marker des Ansprechens auf verschiedene Depressionstherapien?","a":"Abnahme der zuvor erhöhten Aktivität","w":["Zunahme der zuvor erniedrigten Aktivität","Volumenzunahme durch adulte Neurogenese","Zunahme der Kopplung an die Amygdala"],"why":"Fluoxetin-, Placebo- und DBS-Response gingen mit einer Abnahme der sgACC-Aktivität einher – daher das DBS-Ziel (Mayberg 2005)."},{"q":"Welche Struktur zeigte in der ENIGMA-MDD-Metaanalyse (Schmaal 2016) die robusteste Volumenminderung – und bei wem?","a":"Hippocampus, v. a. bei rezidivierendem Verlauf und frühem Beginn","w":["Amygdala, v. a. bei Erstepisode und spätem Beginn","Nucleus accumbens, v. a. beim melancholischen Subtyp","Putamen, v. a. bei medikamentös Unbehandelten"],"why":"Kleinere Hippocampi fanden sich bei rezidivierender MDD und Beginn ≤ 21 J., nicht bei Erstepisoden – Hinweis auf kumulative Krankheitslast."}],"src":"Mayberg, Neuron 2005; Schmaal, Mol Psychiatry 2016; Delgado, Arch Gen Psychiatry 1990; Jacka, BMC Med 2017; Okereke, JAMA 2020; Yang, Nature 2018"},{"id":"trd","name":"Therapieresistente Depression (TRD)","dis":"depression","level":3,"regions":[{"r":"sgacc","how":"hyper","note":"Persistierende Hyperaktivität; Ziel der DBS und über Antikorrelation zum dlPFC auch der rTMS"},{"r":"dlpfc","how":"hypo","note":"Linkslateral hypoaktiv; Stimulationsort für rTMS/iTBS"},{"r":"habenula","how":"hyper","note":"Laterale Habenula als präklinischer Kandidat für Anhedonie und Ketamin-Wirkung"},{"r":"nacc","how":"hypo","note":"Ausgeprägte Anhedonie sagt schlechteres Ansprechen auf Standard-Antidepressiva voraus"},{"r":"pcc","how":"dysconnect","note":"Rigide DMN-Konnektivität; Psilocybin desintegriert das DMN akut"},{"r":"microglia","how":"hyper","note":"TSPO-PET: erhöhte Mikroglia-Aktivierung in Episoden (Setiawan 2015); Subgruppe mit CRP ↑"}],"nt":["Glutamat (NMDA/AMPA)","GABA","Serotonin (5-HT2A)","Dopamin"],"models":["Definition (EMA): kein Ansprechen auf ≥ 2 adäquat dosierte, ausreichend lange Antidepressiva-Versuche in der Episode","Pseudoresistenz zuerst ausschließen: Adhärenz, Spiegel, Diagnose (bipolar?), Komorbidität, Schilddrüse","STAR*D: Remissionsraten sinken mit jeder weiteren Behandlungsstufe, Rückfälle nehmen zu (Rush 2006)","Plastizitäts-Ansatz: Ketamin, Psilocybin, EKT und rTMS sollen rigide Netzwerke (sgACC/DMN) rasch umbauen","Inflammatorischer Subtyp: Infliximab half nur bei erhöhtem Ausgangs-CRP (Raison 2013)"],"nut":"Pseudoresistenz-Check: TSH, B12/Folat, Vitamin D, Alkohol; Adipositas und CRP-Erhöhung mit schlechterem Ansprechen assoziiert; L-Methylfolat adjuvant nur begrenzt belegt.","mcq":[{"q":"Mit welchem aktiven Komparator verglich ESCAPE-TRD (Reif, NEJM 2023) Esketamin-Nasenspray?","a":"Quetiapin retard als Augmentation eines SSRI/SNRI","w":["Aripiprazol als Augmentation eines SSRI/SNRI","Lithium als Augmentation eines SSRI/SNRI","Elektrokonvulsionstherapie nach SSRI-Absetzen"],"why":"Esketamin erreichte in Woche 8 häufiger Remission (primärer Endpunkt) und wurde seltener abgebrochen als Quetiapin XR."},{"q":"Welche Aussage trifft auf die Phase-2b-Studie zu Psilocybin (COMP360) bei TRD (Goodwin, NEJM 2022) zu?","a":"Der MADRS-Vorteil der hohen Dosis in Woche 3 hielt bis Woche 12 nicht signifikant an","w":["Kontrolle war ein aktives Placebo (Niacin) statt einer Minimaldosis","Antidepressiva wurden während der Studie unverändert fortgeführt","Suizidales Verhalten trat ausschließlich im Kontrollarm auf"],"why":"Verglichen wurden drei Psilocybin-Dosen (Minimaldosis als Kontrolle) nach Absetzen der Antidepressiva; suizidales Verhalten trat in allen Armen auf."},{"q":"Bei welchen TRD-Patienten war Infliximab (Raison, JAMA Psychiatry 2013) Placebo überlegen?","a":"Bei hohem Ausgangs-hs-CRP (über 5 mg/l)","w":["Bei allen Patienten unabhängig vom CRP","Bei niedrigem CRP und erhöhtem Cortisol","Bei normalem CRP und hohem BMI"],"why":"Insgesamt kein Effekt; bei niedrigem CRP schnitt Placebo sogar besser ab – Argument für biomarkerbasierte Stratifizierung."}],"src":"Reif, NEJM 2023; Goodwin, NEJM 2022; Raison, JAMA Psychiatry 2013; Rush, Am J Psychiatry 2006; Setiawan, JAMA Psychiatry 2015"},{"id":"bipolar","name":"Bipolare Störung","dis":"bipolare_stoerung","level":3,"regions":[{"r":"amygdala","how":"hyper","note":"Überreaktivität auf emotionale Reize – in Manie, Depression und auch euthym"},{"r":"vlpfc","how":"hypo","note":"Vermindert v. a. in der Manie → defizitäre Emotions- und Impulsregulation"},{"r":"nacc","how":"hyper","note":"Erhöhte ventral-striatale Antwort bei Belohnungserwartung (Belohnungs-Hypersensitivität)"},{"r":"sgacc","how":"atrophy","note":"Reduziertes Volumen der subgenualen grauen Substanz bei familiärer Störung (Drevets 1997)"},{"r":"cc","how":"dysconnect","note":"Reduzierte fraktionale Anisotropie in Balken und frontolimbischen Bahnen (DTI)"}],"nt":["Dopamin","Glutamat","Noradrenalin","Serotonin"],"models":["Belohnungs-Hypersensitivität: übersteigerte Reaktion auf Ziel- und Erfolgsreize triggert Hypomanie","Zirkadiane Dysregulation: Schlafentzug und Rhythmusbrüche lösen Manien aus (Rationale der IPSRT)","Dopaminerge Dysbalance: Hyperdopaminergie in Manie; Stimulanzien/L-Dopa können Switches auslösen","Kindling (Post): frühe Episoden brauchen Stressoren, spätere treten zunehmend spontan auf","Hohe Heritabilität; genetische Überlappung mit Schizophrenie und MDD"],"nut":"Erhöhtes Risiko für Adipositas und metabolisches Syndrom (Krankheit und Medikation); feste Schlaf- und Mahlzeitenrhythmen stabilisieren; unter Lithium Natrium- und Trinkmenge konstant halten.","mcq":[{"q":"Welcher fMRT-Befund unterscheidet bipolare von unipolarer Depression am ehesten (Phillips & Swartz 2014)?","a":"Erhöhte ventral-striatale Aktivität bei Belohnungserwartung","w":["Verminderte Amygdala-Reaktion auf negative Gesichter","Erhöhte dlPFC-Aktivität bei hoher Arbeitsgedächtnislast","Verminderte Insula-Aktivität bei interozeptiven Aufgaben"],"why":"Bipolar Erkrankte zeigen auch euthym eine erhöhte ventral-striatale und vlPFC/OFC-Belohnungsantwort, unipolar Depressive eher eine verminderte."},{"q":"Was ist bei akuter bipolarer Depression laut Leitlinien zu vermeiden?","a":"Antidepressiva-Monotherapie ohne Phasenprophylaktikum","w":["Quetiapin-Monotherapie","Lamotrigin zur Prophylaxe depressiver Episoden","Fortführung einer bestehenden Lithiumprophylaxe"],"why":"Monotherapie birgt Switch- und Rapid-Cycling-Risiko ohne belegten Nutzen; Antidepressiva allenfalls kombiniert mit Lithium, Valproat oder Atypikum."}],"src":"Phillips & Swartz, Am J Psychiatry 2014; Drevets, Nature 1997"},{"id":"schizophrenie","name":"Schizophrenie","dis":"schizophrenie","level":3,"regions":[{"r":"caudate","how":"hyper","note":"Erhöhte präsynaptische DA-Synthese v. a. im assoziativen Striatum, schon im Prodrom (Howes 2009)"},{"r":"dlpfc","how":"hypo","note":"Hypofrontalität bei Arbeitsgedächtnisaufgaben → kognitive und negative Symptome"},{"r":"hippocampus","how":"hyper","note":"CA1-Hypermetabolismus (Schobel 2013) treibt über das Subiculum die VTA-Dopaminneurone an"},{"r":"interneuron","how":"hypo","note":"Parvalbumin-Interneurone mit vermindertem GAD67 → gestörte Gamma-Oszillationen"},{"r":"apical","how":"loss","note":"Verminderte Spine-Dichte an Pyramidenzellen der Schicht III im dlPFC (Glantz & Lewis 2000)"},{"r":"a1","how":"hyper","note":"Aktivierung von Hörrinde und Gyrus temporalis superior während akustischer Halluzinationen"},{"r":"ventrikel","how":"atrophy","note":"Erweiterte Seitenventrikel (Johnstone 1976) als Zeichen periventrikulären Gewebeverlusts"}],"nt":["Dopamin (präsynaptisch ↑, striatal)","Glutamat (NMDA-Hypofunktion)","GABA (Interneurone)","Acetylcholin (muskarinerg)","Serotonin (5-HT2A)"],"models":["Dopaminhypothese III: erhöhte präsynaptische DA-Synthese als gemeinsame Endstrecke der Psychose (Howes & Kapur 2009)","Aberrante Salienz: Dopamin verleiht neutralen Reizen Bedeutung, Wahn als Erklärungsversuch (Kapur 2003)","NMDA-Hypofunktion: Ketamin/PCP erzeugen Positiv-, Negativ- und kognitive Symptome; PV-Interneurone betroffen","Neuroentwicklung und Pruning: C4A-vermittelte Synapseneliminierung in der Adoleszenz (Sekar 2016)","Muskarinerg: Xanomelin-Trospium (M1/M4-Agonist) seit 2024 in den USA zugelassen – ohne D2-Blockade"],"nut":"Hohe Raten von Adipositas, Diabetes und Rauchen (CYP1A2-Induktion senkt Olanzapin/Clozapin); Metformin mildert AP-bedingte Gewichtszunahme; Lebenserwartung um ~15 Jahre verkürzt.","mcq":[{"q":"Wo ist die präsynaptische Dopaminsynthesekapazität (18F-DOPA-PET) bei Psychose bzw. im Prodrom am deutlichsten erhöht?","a":"Assoziatives (dorsales) Striatum","w":["Limbisches (ventrales) Striatum","Sensomotorisches Striatum (posteriores Putamen)","Präfrontaler Kortex"],"why":"Howes 2009: Erhöhung v. a. im assoziativen Striatum, schon bei Prodromal-Personen – entgegen der klassischen rein mesolimbischen Annahme."},{"q":"Welcher Befund stützt die NMDA-Hypofunktions- gegenüber einer reinen Dopaminhypothese?","a":"Ketamin erzeugt bei Gesunden auch Negativsymptome und kognitive Defizite","w":["Amphetamin verschlechtert Positivsymptome bei Patienten","Antipsychotische Potenz korreliert mit der D2-Affinität","Amphetamin setzt bei Patienten mehr striatales Dopamin frei"],"why":"Dopaminerge Agonisten imitieren v. a. Positivsymptome; NMDA-Antagonisten bilden das ganze Spektrum inkl. Negativ- und kognitiver Symptome ab."},{"q":"Welche genetische Variation verknüpft Schizophrenie (Sekar, Nature 2016) mit übermäßigem synaptischem Pruning?","a":"Strukturvarianten von C4 mit hoher C4A-Expression","w":["DISC1-Translokation mit gestörter Neuronenmigration","COMT-Val158Met mit schnellerem PFC-Dopaminabbau","NRG1-Varianten mit reduzierter ErbB4-Signalgebung"],"why":"C4A markiert Synapsen für die komplementvermittelte Phagozytose durch Mikroglia; höhere C4A-Expression geht mit höherem Risiko einher."}],"src":"Howes, Arch Gen Psychiatry 2009; Howes & Kapur, Schizophr Bull 2009; Kapur, Am J Psychiatry 2003; Sekar, Nature 2016; Schobel, Neuron 2013; Glantz & Lewis, Arch Gen Psychiatry 2000; Johnstone, Lancet 1976; Hjorthøj, Lancet Psychiatry 2017"},{"id":"gad","name":"Generalisierte Angststörung (GAD)","dis":"generalisierte_angststoerung","level":3,"regions":[{"r":"amygdala","how":"hyper","note":"Bei Jugendlichen konsistent überaktiv; bei Erwachsenen sind die Befunde heterogen"},{"r":"bnst","how":"hyper","note":"Anhaltende Angst bei unvorhersehbarer Bedrohung (Davis-Modell der erweiterten Amygdala)"},{"r":"vmpfc","how":"dysconnect","note":"Verminderte funktionelle Kopplung mit der Amygdala → schwache Top-down-Regulation"},{"r":"insula","how":"hyper","note":"Verstärkte Antizipation aversiver Ereignisse und interozeptive Wachsamkeit"}],"nt":["GABA","Serotonin","Noradrenalin","CRH"],"models":["Furcht vs. Angst: Amygdala für phasische Furcht, BNST für anhaltende Angst bei unvorhersehbarer Bedrohung (Davis 2010)","Kognitive Vermeidung (Borkovec): verbales Sorgen dämpft somatische Erregung und verhindert emotionale Verarbeitung","Intoleranz gegenüber Unsicherheit als transdiagnostischer Kernfaktor (Dugas)","Kontrastvermeidung (Newman & Llera 2011): Sorgen schützt vor plötzlichem negativem Gefühlsumschwung"],"nut":"Koffein verstärkt dosisabhängig Angst; Alkohol als Selbstmedikation führt zu Rebound-Angst und Abhängigkeit; Hyperthyreose, Hypoglykämie und Phäochromozytom als Differenzialdiagnosen ausschließen.","mcq":[{"q":"Welche Struktur vermittelt nach Davis vor allem anhaltende Angst bei unvorhersehbarer Bedrohung – im Gegensatz zu cue-gebundener Furcht?","a":"Nucleus interstitialis striae terminalis (BNST)","w":["Zentraler Amygdalakern (medialer Anteil)","Lateraler Amygdalakern","Dorsales periaquäduktales Grau"],"why":"Läsion oder Inaktivierung des BNST verhindert anhaltende, nicht aber phasische, reizgebundene Furchtreaktionen (Davis 2010)."},{"q":"Welche Funktion schreibt Borkovecs Vermeidungstheorie dem Sorgen bei GAD zu?","a":"Verbales Denken dämpft somatische Erregung und blockiert emotionale Verarbeitung","w":["Bildhaftes Vorstellen fördert die Habituation an Angstreize","Sorgen steigert die vagale Aktivität und beschleunigt Extinktion","Sorgen richtet die Aufmerksamkeit gezielt auf Körpersignale"],"why":"Die Abnahme der Erregung verstärkt das Sorgen negativ und verhindert die für Extinktion nötige Furchtaktivierung."}],"src":"Davis, Neuropsychopharmacology 2010"},{"id":"panik","name":"Panikstörung","dis":"panikstoerung","level":3,"regions":[{"r":"amygdala","how":"hyper","note":"Zentrum des Furchtnetzwerks (Gorman 2000), für CO2-ausgelöste Panik aber nicht notwendig (Feinstein 2013)"},{"r":"insula","how":"hyper","note":"Fehlbewertung interozeptiver Signale wie Herzschlag und Atemnot"},{"r":"brainstem","how":"hyper","note":"PAG, Nucleus parabrachialis und CO2/pH-Chemosensoren als Generatoren der Panikreaktion"},{"r":"lc","how":"hyper","note":"Noradrenerge Überaktivität; Yohimbin (α2-Antagonist) provoziert Attacken"}],"nt":["Noradrenalin","Serotonin","GABA","Cholecystokinin (CCK-4 panikogen)"],"models":["Kognitives Modell (Clark 1986): katastrophisierende Fehlinterpretation körperlicher Empfindungen","Falscher Erstickungsalarm (Klein 1993): überempfindlicher CO2-Monitor im Hirnstamm","Furchtnetzwerk (Gorman 2000): Amygdala-zentriert mit Projektionen zu Hirnstamm und Hypothalamus","Interozeptive Konditionierung: Körperempfindungen werden zu konditionierten Auslösern"],"nut":"Koffein wirkt bei Panikstörung stärker anxiogen als bei Gesunden; Laktatinfusion und CO2-Inhalation provozieren Attacken experimentell; Hypoglykämie und Hyperventilation als Auslöser beachten.","mcq":[{"q":"Was zeigte die CO2-Inhalation bei Personen mit bilateraler Amygdala-Läsion (Feinstein, Nat Neurosci 2013)?","a":"Sie erlebten Panikattacken, obwohl sie äußere Bedrohungen kaum fürchten","w":["Sie zeigten keinerlei Atemnot oder autonome Erregung","Sie hatten autonome Reaktionen ganz ohne Angsterleben","Sie reagierten erst auf Laktat, nicht auf CO2"],"why":"Interozeptiv ausgelöste Panik braucht die Amygdala nicht – Hinweis auf Hirnstamm-/Insula-Chemosensorik als eigenständige Route."},{"q":"Welcher Panik-Provokationsstoff wirkt über den CCK-B-Rezeptor?","a":"CCK-4","w":["Yohimbin","Flumazenil","Natriumlaktat"],"why":"Alle vier sind bei Panikstörung panikogen: CCK-4 via CCK-B, Yohimbin via α2-Blockade, Flumazenil an der BZD-Stelle, Laktat vermutlich via Chemosensorik."}],"src":"Feinstein, Nat Neurosci 2013; Gorman, Am J Psychiatry 2000; Klein, Arch Gen Psychiatry 1993"},{"id":"ptbs","name":"Posttraumatische Belastungsstörung (PTBS)","dis":"ptbs","level":3,"regions":[{"r":"amygdala","how":"hyper","note":"Überreaktivität auf Trauma- und Bedrohungsreize, Generalisierung der Furcht"},{"r":"vmpfc","how":"hypo","note":"Defizitärer Abruf des Extinktionsgedächtnisses (Milad 2009)"},{"r":"hippocampus","how":"atrophy","note":"Kleineres Volumen, teils präexistierend (Gilbertson 2002); gestörte Kontextverarbeitung"},{"r":"dacc","how":"hyper","note":"Erhöhter Ruhemetabolismus, auch beim nicht exponierten Zwilling (Shin 2009) – möglicher Risikomarker"},{"r":"insula","how":"hyper","note":"Verstärkte interozeptive und Salienz-Antwort"},{"r":"lc","how":"hyper","note":"Noradrenerge Überaktivität → Hyperarousal und Albträume (Rationale für Prazosin)"}],"nt":["Noradrenalin","CRH/Cortisol (verstärkte Rückkopplung)","Glutamat","Serotonin"],"models":["Extinktionsdefizit: Sicherheit wird gelernt, aber nicht abgerufen (vmPFC/Hippocampus)","Hippocampus-Vulnerabilität: kleineres Volumen teils präexistierend statt nur Traumafolge (Gilbertson 2002)","HPA-Achse (Yehuda): niedrig-normales Cortisol bei verstärkter Glukokortikoid-Rückkopplung","Duale Repräsentation (Brewin): sensorische Erinnerungen ohne Kontextbindung → Intrusionen","Rekonsolidierung: reaktivierte Gedächtnisspuren sind kurz labil – Angriffspunkt für Therapien"],"nut":"Häufige Komorbidität mit Alkohol- und Substanzkonsum; erhöhtes Risiko für Adipositas, Typ-2-Diabetes und metabolisches Syndrom; Alkohol als Schlafmittel verschlechtert REM-Schlaf und Albträume.","mcq":[{"q":"Was zeigte die Zwillingsstudie von Gilbertson (Nat Neurosci 2002) zum Hippocampusvolumen bei PTBS?","a":"Auch die nicht exponierten Zwillinge Betroffener hatten kleinere Hippocampi","w":["Das Volumen nahm erst nach dem Trauma proportional zur Dauer ab","Nur der kampfexponierte Zwilling zeigte eine Volumenminderung","Das Volumen war nicht mit der PTBS-Schwere assoziiert"],"why":"Ein kleiner Hippocampus erscheint als präexistierender Vulnerabilitätsfaktor – nicht (nur) als Folge cortisolbedingter Neurotoxizität."},{"q":"Welches HPA-Achsen-Muster ist für chronische PTBS typischer als für Depression?","a":"Niedrig-normales Cortisol mit verstärkter Dexamethason-Suppression","w":["Hypercortisolismus mit fehlender Dexamethason-Suppression","Erhöhtes Cortisol bei abgeschwächter Glukokortikoid-Rückkopplung","Normales Cortisol bei aufgehobenem Tagesrhythmus"],"why":"Yehuda: verstärkte Glukokortikoidrezeptor-Sensitivität und Rückkopplung – das Gegenteil des melancholischen Depressionsmusters."},{"q":"Welches Aktivierungsmuster fand Milad (2009) bei PTBS beim Abruf eines Extinktionsgedächtnisses?","a":"vmPFC und Hippocampus hypo-, dACC hyperaktiv","w":["vmPFC und Hippocampus hyper-, dACC hypoaktiv","Amygdala hypo-, Insula hyperaktiv","dlPFC hyper-, Thalamus hypoaktiv"],"why":"Schwacher vmPFC-/Hippocampus-Abruf der Sicherheitsspur und überaktiver dACC (Furchtausdruck) erklären die persistierende Furcht."}],"src":"Gilbertson, Nat Neurosci 2002; Milad, Biol Psychiatry 2009; Shin, Arch Gen Psychiatry 2009"},{"id":"zwang","name":"Zwangsstörung (OCD)","dis":"zwangsstoerung","level":3,"regions":[{"r":"ofc","how":"hyper","note":"Hyperaktiv in Ruhe und bei Symptomprovokation; normalisiert sich unter erfolgreicher Therapie"},{"r":"caudate","how":"hyper","note":"Überaktivität im CSTC-Kreis; sinkt nach SSRI und Verhaltenstherapie (Baxter 1992)"},{"r":"thalamus","how":"hyper","note":"Mangelnde thalamische Filterung im kortiko-striato-thalamo-kortikalen Kreis"},{"r":"dacc","how":"hyper","note":"Verstärkte Fehlerüberwachung (erhöhte ERN) – ‚etwas stimmt nicht‘-Signal"}],"nt":["Serotonin","Glutamat","Dopamin"],"models":["CSTC-Modell: Übergewicht des direkten über den indirekten Pfad in OFC/ACC–Striatum–Thalamus-Schleifen","Habit-Hypothese: Übergewicht gewohnheitsbasierter gegenüber zielgerichteter Kontrolle (Gillan 2011)","Gestörte Fehlerüberwachung: erhöhte ERN als Endophänotyp, auch bei Angehörigen","Glutamat: SAPAP3-Knockout-Mäuse zeigen striatal bedingtes Zwangsputzen (Welch 2007)"],"nut":"Kein spezifischer Ernährungsbezug; oft höhere SSRI-Dosen nötig (GI-NW, Gewicht); Fluvoxamin hemmt CYP1A2 stark → Koffein-, Clozapin- und Melatoninspiegel steigen deutlich.","mcq":[{"q":"Welches Trizyklikum ist bei Zwangsstörung wirksam – im Gegensatz zum noradrenergen Desipramin?","a":"Clomipramin","w":["Amitriptylin","Nortriptylin","Imipramin"],"why":"Antizwanghafte Wirkung ist an starke SERT-Hemmung gebunden; Desipramin war im direkten Vergleich unwirksam."},{"q":"Was zeigten OCD-Patienten im Outcome-Devaluations-Paradigma (Gillan 2011)?","a":"Fortgesetztes Reagieren trotz entwerteter Belohnung (Habit-Übergewicht)","w":["Beschleunigte Extinktion instrumenteller Reaktionen","Verstärkt modellbasiertes, zielgerichtetes Planen","Fehlende pawlowsche Konditionierung auf Belohnung"],"why":"Zwänge erscheinen als übermäßige Gewohnheiten: Handlungen laufen weiter, obwohl ihr Ergebnis nicht mehr erwünscht ist."},{"q":"Welches DBS-Ziel erhielt in den USA 2009 eine Humanitarian Device Exemption für therapierefraktäre Zwangsstörung?","a":"Ventrale Kapsel/ventrales Striatum (VC/VS)","w":["Nucleus subthalamicus (anteromedial)","Subgenualer cingulärer Kortex","Globus pallidus internus"],"why":"Der anteromediale STN war in einer französischen RCT wirksam (Mallet 2008), die HDE gilt aber der VC/VS-Stimulation."}],"src":"Baxter, Arch Gen Psychiatry 1992; Gillan, Am J Psychiatry 2011; Welch, Nature 2007; Mallet, NEJM 2008"},{"id":"adhs","name":"ADHS","dis":"adhs","level":3,"regions":[{"r":"dlpfc","how":"hypo","note":"Hypoaktivierung bei Inhibition und Arbeitsgedächtnis; verzögerte kortikale Reifung (Shaw 2007)"},{"r":"caudate","how":"atrophy","note":"Kleineres Volumen bei Kindern (ENIGMA, Hoogman 2017)"},{"r":"nacc","how":"hypo","note":"Verminderte ventral-striatale Aktivierung bei Belohnungserwartung; Volumen bei Kindern ↓"},{"r":"cerebellum","how":"atrophy","note":"Kleineres Volumen (v. a. posteriorer Vermis) – Timing- und Motorikdefizite"},{"r":"pcc","how":"dysconnect","note":"Unzureichende DMN-Deaktivierung bei Aufgaben → Aufmerksamkeitsschwankungen"},{"r":"amygdala","how":"atrophy","note":"Kleineres Volumen bei Kindern (ENIGMA) – passend zu emotionaler Dysregulation"}],"nt":["Dopamin","Noradrenalin"],"models":["Verzögerte kortikale Reifung: Gipfel der Kortexdicke rund 3 Jahre später, v. a. präfrontal (Shaw 2007)","Dual-Pathway (Sonuga-Barke): exekutive Dysfunktion plus Delay-Aversion im Belohnungssystem","DMN-Interferenz: unzureichende Deaktivierung des Ruhenetzwerks verursacht Aufmerksamkeitsaussetzer","Hoch heritabel und polygen; erste genomweite Risikoloci identifiziert (Demontis 2019)"],"nut":"Oligoantigene Diät: Effekte v. a. in nicht verblindeten Bewertungen (Pelsser 2011); Farbstoffe und Omega-3 nur kleine Effekte; Stimulanzien senken Appetit und Wachstum; Ferritin prüfen.","mcq":[{"q":"Was zeigte die longitudinale MRT-Studie von Shaw et al. (PNAS 2007) bei Kindern mit ADHS?","a":"Verzögerten Gipfel der Kortexdicke, am deutlichsten präfrontal","w":["Verfrühten Gipfel der Kortexdicke im Präfrontalkortex","Dauerhaft dünneren Kortex ohne Reifungsverzögerung","Reifungsverzögerung nur bei Kindern unter Stimulanzien"],"why":"Der Median des Dickengipfels lag bei ADHS rund 3 Jahre später; die Reifungssequenz selbst war erhalten – Modell der verzögerten Reifung."},{"q":"Was ergab die ENIGMA-ADHD-Megaanalyse (Hoogman 2017) zu subkortikalen Volumina?","a":"Kleinere Volumina bei Kindern, bei Erwachsenen kaum nachweisbar","w":["Kleinere Volumina v. a. bei Erwachsenen, nicht bei Kindern","Effekte nur bei stimulanzienbehandelten Personen","Volumenminderung ausschließlich im Nucleus caudatus"],"why":"Accumbens, Amygdala, Caudatum, Hippocampus und Putamen waren bei Kindern kleiner, nicht durch Medikation erklärt – passend zum Reifungsmodell."}],"src":"Shaw, PNAS 2007; Hoogman, Lancet Psychiatry 2017; Demontis, Nat Genet 2019; Pelsser, Lancet 2011"},{"id":"autismus","name":"Autismus-Spektrum-Störung","dis":"autismus","level":3,"regions":[{"r":"amygdala","how":"hyper","note":"Frühkindlich vergrößert, später Annäherung an die Norm; veränderte Reaktion auf Gesichter"},{"r":"cerebellum","how":"loss","note":"Verminderte Zahl von Purkinje-Zellen in Post-mortem-Studien"},{"r":"apical","how":"hyper","note":"Erhöhte Spine-Dichte durch defizitäres Pruning (mTOR/Autophagie, Tang 2014)"},{"r":"interneuron","how":"hypo","note":"E/I-Ungleichgewicht mit relativ verminderter GABAerger Hemmung"},{"r":"cc","how":"atrophy","note":"Kleinerer Balken → reduzierte interhemisphärische Konnektivität"},{"r":"microglia","how":"hyper","note":"Mikroglia- und Astroglia-Aktivierung in Post-mortem-Gewebe (Vargas 2005)"}],"nt":["Glutamat","GABA","Serotonin (Hyperserotonämie im Blut)","Oxytocin"],"models":["E/I-Ungleichgewicht: relative Übererregung kortikaler Netzwerke (Rubenstein & Merzenich 2003)","Frühes Hirnüberwachstum: Oberflächen-Hyperexpansion im 1. Lebensjahr (Hazlett 2017)","Pruning-Defizit: mTOR-Überaktivität hemmt Autophagie → mehr Spines (Tang 2014)","Predictive Coding: schwache Vorannahmen, Wahrnehmung wird ‚zu real‘ (Pellicano & Burr 2012)","Stark heritabel: polygen plus seltene De-novo-Varianten (z. B. SHANK3, CHD8)"],"nut":"Selektives Essverhalten häufig → Risiko für Mangel an Vitamin D, Calcium, Eisen, Ballaststoffen; GI-Beschwerden häufig; gluten-/caseinfreie Diät ohne belastbare Evidenz.","mcq":[{"q":"Was zeigten Yap et al. (Cell 2021) zu Unterschieden im Darmmikrobiom bei Autismus?","a":"Sie spiegeln v. a. die eingeschränkte Nahrungsauswahl wider","w":["Sie gehen den ersten Symptomen kausal voraus","Sie normalisieren sich nach Stuhltransplantation dauerhaft","Sie korrelieren eng mit der polygenen Risikolast"],"why":"Kaum direkte Autismus-Mikrobiom-Assoziationen; die Unterschiede ließen sich über geringere Ernährungsvielfalt erklären – eher Folge als Ursache."},{"q":"Welcher MRT-Befund ging bei Säuglingen mit familiärem Hochrisiko (Hazlett, Nature 2017) der späteren Autismusdiagnose voraus?","a":"Hyperexpansion der Kortexoberfläche zwischen 6 und 12 Monaten","w":["Ausdünnung des präfrontalen Kortex ab 6 Monaten","Verkleinerung der Amygdala im ersten Lebensjahr","Reduziertes Gesamthirnvolumen mit 24 Monaten"],"why":"Die Oberflächen-Hyperexpansion im 1. Jahr ging dem Volumen-Überwachstum im 2. Jahr voraus und sagte die Diagnose mit 24 Monaten voraus."}],"src":"Hazlett, Nature 2017; Yap, Cell 2021; Tang, Neuron 2014; Vargas, Ann Neurol 2005; Pellicano & Burr, Trends Cogn Sci 2012"},{"id":"sucht","name":"Sucht (allgemeine Neurobiologie)","dis":"","level":3,"regions":[{"r":"nacc","how":"hyper","note":"Phasische DA-Freisetzung auf Drogen und Cues → Incentive Salience"},{"r":"vta","how":"hyper","note":"Dopaminerge Antwort verlagert sich von der Droge auf vorhersagende Reize"},{"r":"putamen","how":"hyper","note":"Verlagerung vom ventralen zum dorsalen Striatum → habitueller, zwanghafter Konsum"},{"r":"ofc","how":"hypo","note":"Hypometabolismus gekoppelt an niedrige striatale D2-Verfügbarkeit (Volkow) → Kontrollverlust"},{"r":"amygdala","how":"hyper","note":"Erweiterte Amygdala: CRF und Dynorphin ↑ im Entzug → negativer Affekt (Koob)"},{"r":"insula","how":"hyper","note":"Interozeptives Craving; Insula-Läsion beendete Rauchen mühelos (Naqvi 2007)"},{"r":"dlpfc","how":"hypo","note":"Geschwächte exekutive Kontrolle über Konsumimpulse"}],"nt":["Dopamin","Glutamat","Endogene Opioide","CRF/Dynorphin","Endocannabinoide"],"models":["Incentive Sensitization: ‚Wanting‘ (Dopamin) sensitiviert, ‚Liking‘ nicht (Robinson & Berridge 1993)","Drei-Stadien-Zyklus: Rausch, Entzug/negativer Affekt, Antizipation/Craving (Koob & Volkow 2016)","Ventral → dorsal: vom zielgerichteten zum habituellen, zwanghaften Konsum (Everitt & Robbins 2005)","Allostase/Anti-Reward: Stresssysteme kompensieren chronisch und erzeugen anhaltenden negativen Affekt","Reduzierte striatale D2-Verfügbarkeit und abgeschwächte DA-Freisetzung bei vielen Substanzen (PET)"],"nut":"Hochverarbeitete, sehr schmackhafte Lebensmittel aktivieren dieselben Belohnungskreise (‚Food Addiction‘, Konstrukt umstritten); frühe PET-Studien fanden niedrige D2-Verfügbarkeit bei Adipositas.","mcq":[{"q":"Welche Läsion führte bei Rauchern zu einem abrupten, mühelosen Rauchstopp ohne Craving (Naqvi, Science 2007)?","a":"Läsion der Inselrinde","w":["Läsion des Nucleus accumbens","Läsion des dorsalen Striatums","Läsion des orbitofrontalen Kortex"],"why":"Die Insula repräsentiert interozeptive Konsumempfindungen; nach ihrer Schädigung ‚vergaß der Körper den Drang‘ zu rauchen."},{"q":"Was unterscheidet nach Robinson & Berridge ‚Wanting‘ von ‚Liking‘?","a":"Wanting ist dopaminabhängig und sensitiviert, Liking (Opioid-Hotspots) nicht","w":["Liking ist dopaminabhängig, Wanting rein opioidvermittelt","Beide sensitivieren bei wiederholtem Konsum gleichermaßen","Wanting entsteht durch Habituation im dorsalen Striatum"],"why":"Daher kann Verlangen wachsen, während der Genuss abnimmt – das Kernparadox der Sucht."},{"q":"Welcher PET-Befund findet sich konsistent bei Stimulanzien-, Alkohol- und Opioidabhängigkeit?","a":"Verminderte striatale D2/3-Rezeptorverfügbarkeit","w":["Erhöhte striatale D2/3-Rezeptorverfügbarkeit","Erhöhte präsynaptische Dopaminsynthese im Striatum","Verstärkte amphetamininduzierte Dopaminfreisetzung"],"why":"Niedrige D2-Verfügbarkeit und abgestumpfte DA-Freisetzung kontrastieren mit der Schizophrenie, bei der Synthese und Freisetzung erhöht sind."}],"src":"Naqvi, Science 2007; Robinson & Berridge, Brain Res Rev 1993; Everitt & Robbins, Nat Neurosci 2005; Koob & Volkow, Lancet Psychiatry 2016"},{"id":"alkohol","name":"Alkoholabhängigkeit","dis":"alkoholabhaengigkeit","level":3,"regions":[{"r":"nacc","how":"hyper","note":"Cue-Reaktivität im ventralen Striatum, Prädiktor für Rückfälle"},{"r":"amygdala","how":"hyper","note":"CRF-Überaktivität im Entzug → Angst und negativer Affekt"},{"r":"dlpfc","how":"hypo","note":"Exekutive Defizite und Volumenminderung der frontalen grauen Substanz"},{"r":"cerebellum","how":"atrophy","note":"Degeneration des anterior-superioren Vermis → Stand- und Gangataxie"},{"r":"hippocampus","how":"atrophy","note":"Volumenminderung, unter Abstinenz teilweise reversibel"},{"r":"mammillar","how":"atrophy","note":"Atrophie bei Thiaminmangel (Wernicke-Korsakow)"}],"nt":["GABA (GABA-A-Verstärkung)","Glutamat (NMDA-Hemmung, im Entzug Rebound)","Dopamin","Endogene Opioide","CRF"],"models":["Neuroadaptation: chronisch NMDA ↑ und GABA-A ↓ → im Entzug Übererregbarkeit (Krampfanfälle, Delir)","Kindling: wiederholte Entzüge verschlimmern nachfolgende Entzugssyndrome","Allostase (Koob): Trinken wird zunehmend negativ verstärkt (Entzugslinderung) statt positiv","Genetik: ALDH2*2 und ADH1B*2 schützen durch Acetaldehyd-Akkumulation"],"nut":"Thiamin-, Folat-, Magnesium- und Zinkmangel häufig (Wernicke-Prophylaxe!); Ethanol liefert ~7 kcal/g; Hypoglykämie durch gehemmte Glukoneogenese; Fettleber.","mcq":[{"q":"Welche Neuroadaptation erklärt am besten die Entzugskrampfanfälle nach chronischem Alkoholkonsum?","a":"NMDA-Hochregulation bei verminderter GABA-A-Funktion","w":["D2-Hochregulation im ventralen Striatum","Verstärkte Dynorphin-Freisetzung im Hippocampus","Erhöhte Kaliumleitfähigkeit kortikaler Neurone"],"why":"Ethanol hemmt NMDA und verstärkt GABA-A; die Gegenregulation demaskiert sich beim Absetzen als Übererregbarkeit."},{"q":"Welche Genvariante schützt durch Acetaldehyd-Akkumulation am stärksten vor Alkoholabhängigkeit?","a":"ALDH2*2 (inaktive Aldehyddehydrogenase 2)","w":["ADH1B*1 (langsame Alkoholdehydrogenase)","CYP2E1-Induktionsvariante","OPRM1 A118G (μ-Opioidrezeptor)"],"why":"ALDH2*2 verursacht Flush und Übelkeit; schützend ist ADH1B*2 (nicht *1); OPRM1 moduliert eher das Naltrexon-Ansprechen."}],"src":""},{"id":"anorexie","name":"Anorexia nervosa","dis":"anorexia_nervosa","level":3,"regions":[{"r":"insula","how":"hypo","note":"Verminderte Antwort auf Geschmacksreize, auch nach Genesung (Wagner 2008); gestörte Interozeption"},{"r":"caudate","how":"hyper","note":"Dorsales Striatum bei Nahrungswahl aktiver → gewohnheitsmäßige Restriktion (Foerde 2015)"},{"r":"hypothal","how":"hypo","note":"Funktionelle Suppression der HPG-Achse (GnRH ↓ → Amenorrhö), Leptin ↓"},{"r":"r5ht1a","how":"hyper","note":"Erhöhte 5-HT1A-Bindung im PET bei akuter Erkrankung (Bailer 2007)"},{"r":"r5ht2a","how":"hypo","note":"Verminderte 5-HT2A-Bindung nach Genesung (Bailer 2004) – eine Rationale für Psilocybin-Studien"},{"r":"ventrikel","how":"atrophy","note":"Erweiterte Ventrikel/Sulci und Kortexverdünnung, nach Gewichtsrestitution weitgehend reversibel"}],"nt":["Serotonin","Dopamin","Leptin (erniedrigt) und Ghrelin (erhöht)"],"models":["Serotonerges Modell (Kaye): Hungern senkt Tryptophanzufuhr und damit angstverstärkende 5-HT-Aktivität","Habit-Modell: Restriktion wird über das dorsale Striatum zur Gewohnheit (Foerde 2015)","Metabo-psychiatrische Störung: genetische Korrelation mit Stoffwechselmerkmalen (Watson 2019)","Interozeptives Defizit: veränderte Insula-Verarbeitung von Hunger- und Geschmackssignalen","Kognitive Rigidität und Detailfokus (Set-Shifting-Defizite), teils auch nach Genesung"],"nut":"Refeeding-Syndrom: Hypophosphatämie (+ K, Mg, Thiamin) bei Wiederernährung – Phosphat monitoren, Thiamin geben; Knochendichte ↓ (Ca, Vit. D, Östrogenmangel); Zinkmangel; Hypoglykämie.","mcq":[{"q":"Warum fällt beim Refeeding-Syndrom das Serum-Phosphat?","a":"Insulin treibt Phosphat für Glykolyse und ATP-Synthese in die Zellen","w":["Renale Phosphatverluste durch sekundären Hyperaldosteronismus","Phosphatbindung durch die gleichzeitige Calciumgabe","PTH-Anstieg durch hochdosiertes Vitamin D"],"why":"Kohlenhydrate stimulieren Insulin → zelluläre Aufnahme von Glukose, Phosphat, Kalium und Magnesium bei leeren Speichern; Thiaminbedarf steigt."},{"q":"Welche genetische Korrelation fand die AN-GWAS (Watson, Nat Genet 2019) neben psychiatrischen Merkmalen?","a":"Positiv mit HDL-Cholesterin, negativ mit BMI und Nüchterninsulin","w":["Positiv mit Nüchterninsulin und Typ-2-Diabetes","Negativ mit körperlicher Aktivität und HDL","Positiv mit Leptin und Fettmasse"],"why":"Das Muster (dazu positiv mit körperlicher Aktivität) spricht für eine metabolische Komponente der Ätiologie, nicht nur für Folgen der Unterernährung."},{"q":"Wie war die erste Psilocybin-Studie bei Anorexia nervosa (Peck, Nat Med 2023) angelegt?","a":"Offene Phase-1-Machbarkeitsstudie, erwachsene Frauen, eine Dosis","w":["Placebokontrollierte Phase-2-Studie mit Frauen und Männern","Randomisierter Vergleich mit Olanzapin über 12 Wochen","Offene Studie mit drei Sitzungen bei Jugendlichen"],"why":"Primär Sicherheit und Verträglichkeit bei 10 Frauen; Wirksamkeit lässt sich daraus nicht ableiten – dafür braucht es kontrollierte Studien."}],"src":"Watson, Nat Genet 2019; Foerde, Nat Neurosci 2015; Peck, Nat Med 2023; Wagner, Neuropsychopharmacology 2008; Bailer, Biol Psychiatry 2007; Bailer, Neuropsychopharmacology 2004"},{"id":"bulimie","name":"Bulimia nervosa","dis":"bulimia_nervosa","level":3,"regions":[{"r":"dlpfc","how":"hypo","note":"Verminderte frontostriatale Aktivierung bei Aufgaben zur Selbstregulation (Marsh 2009)"},{"r":"caudate","how":"hypo","note":"Teil des defizitären frontostriatalen Kontrollkreises (Marsh 2009)"},{"r":"sert","how":"hypo","note":"Verminderte SERT-Verfügbarkeit in Hypothalamus/Thalamus im SPECT (Tauscher 2001)"}],"nt":["Serotonin","Dopamin"],"models":["Restriktions-Essanfall-Zyklus: Diät und Hunger erhöhen das Essanfallrisiko, Kompensation hält ihn aufrecht","Transdiagnostisches CBT-E-Modell (Fairburn): Überbewertung von Figur und Gewicht als Kern","Escape-Theorie: Essanfälle als Flucht aus aversiver Selbstwahrnehmung (Heatherton & Baumeister 1991)","Defizitäre frontostriatale Selbstregulation (Marsh 2009)"],"nut":"Erbrechen → Hypokaliämie, Alkalose, Parotisschwellung, Zahnschmelzerosion; Laxanzien → Dehydratation; regelmäßige Mahlzeiten (3 Haupt- plus Zwischenmahlzeiten) durchbrechen den Zyklus.","mcq":[{"q":"Welche Laborkonstellation ist für häufiges selbstinduziertes Erbrechen typisch?","a":"Hypokaliämie mit hypochlorämischer metabolischer Alkalose","w":["Hypokaliämie mit hyperchlorämischer metabolischer Azidose","Hyperkaliämie mit metabolischer Azidose","Hyponatriämie mit respiratorischer Alkalose"],"why":"Säureverlust aus dem Magen → Alkalose; Laxanzienabusus führt dagegen eher zu hyperchlorämischer Azidose durch Bicarbonatverlust."},{"q":"Welches Antidepressivum ist bei Bulimia nervosa zugelassen – und welches kontraindiziert?","a":"Fluoxetin zugelassen, Bupropion kontraindiziert","w":["Bupropion zugelassen, Fluoxetin kontraindiziert","Sertralin zugelassen, Mirtazapin kontraindiziert","Mirtazapin zugelassen, Sertralin kontraindiziert"],"why":"Fluoxetin (höher dosiert) reduziert Essanfälle und Erbrechen; unter Bupropion traten bei Bulimie gehäuft Krampfanfälle auf (Horne 1988)."}],"src":"Marsh, Am J Psychiatry 2009; Tauscher, Am J Psychiatry 2001; Horne, J Clin Psychiatry 1988"},{"id":"bes","name":"Binge-Eating-Störung","dis":"binge_eating_stoerung","level":3,"regions":[{"r":"nacc","how":"hyper","note":"Erhöhte ventral-striatale Cue-Reaktivität auf Nahrungsreize"},{"r":"ofc","how":"hyper","note":"Gesteigerte medial-orbitofrontale Antwort auf Nahrungsbilder (Schienle 2009)"},{"r":"dlpfc","how":"hypo","note":"Verminderte präfrontale Aktivierung bei Inhibitionsaufgaben → Kontrollverlust"}],"nt":["Dopamin","Noradrenalin","Serotonin","Endogene Opioide"],"models":["Belohnungssensitivität und Impulsivität: verstärkte Cue-Reaktivität bei geschwächter Inhibition","Emotionsregulationsmodell: Essanfälle dämpfen negative Affekte kurzfristig","Diät geht Essanfällen bei BES seltener voraus als bei Bulimie","Überlappung mit ‚Food Addiction‘ (Yale Food Addiction Scale) – Konstrukt umstritten"],"nut":"Ohne Kompensation hohe Adipositas-Komorbidität; strenge Diäten können Essanfälle triggern – Struktur statt Restriktion; Gewichtsreduktion ist nicht primäres Ziel der KVT.","mcq":[{"q":"Welche Substanz ist als erstes Medikament von der FDA für die Binge-Eating-Störung zugelassen?","a":"Lisdexamfetamin","w":["Topiramat","Semaglutid","Naltrexon/Bupropion"],"why":"Zulassung 2015 in den USA; in Deutschland ist Lisdexamfetamin nur für ADHS zugelassen. Topiramat wirkt in Studien, ist aber nicht zugelassen."},{"q":"Was unterscheidet die Binge-Eating-Störung im DSM-5 diagnostisch von der Bulimia nervosa?","a":"Fehlen regelmäßigen kompensatorischen Verhaltens","w":["Essanfälle mindestens zweimal pro Woche über 6 Monate","Kontrollverlust ist kein Kriterium","Ausschluss bei einem BMI über 30"],"why":"Beide verlangen Essanfälle mit Kontrollverlust mindestens 1×/Woche über 3 Monate; die 2×/Woche-6-Monate-Regel stammt aus dem DSM-IV."}],"src":"Schienle, Biol Psychiatry 2009"},{"id":"borderline","name":"Borderline-Persönlichkeitsstörung","dis":"borderline_persoenlichkeitsstoerung","level":3,"regions":[{"r":"amygdala","how":"hyper","note":"Überreaktion auf negative und soziale Reize, verzögerte Rückkehr zur Baseline"},{"r":"vmpfc","how":"hypo","note":"Defizitäre Top-down-Regulation der Amygdala"},{"r":"hippocampus","how":"atrophy","note":"Verkleinert in Metaanalysen, assoziiert mit frühen Traumata"},{"r":"dacc","how":"hyper","note":"Verstärkte Reaktion auf soziale Ausgrenzung (Cyberball-Paradigma)"}],"nt":["Serotonin","Endogene Opioide","Oxytocin","Glutamat"],"models":["Biosoziale Theorie (Linehan): emotionale Vulnerabilität × invalidierendes Umfeld – Grundlage der DBT","Mentalisierungsdefizit (Fonagy): eingeschränktes Verstehen eigener und fremder Zustände unter Stress","Opioid-Hypothese: Selbstverletzung reguliert Spannung über endogene Opioide (Bandelow 2010)","Veränderte Schmerzverarbeitung mit präfrontal vermittelter Antinozizeption (Schmahl 2006)"],"nut":"Häufige Komorbidität mit Bulimie/Binge-Eating und Substanzkonsum; unter off-label eingesetzten Atypika Gewicht und Stoffwechsel kontrollieren.","mcq":[{"q":"Welche Hirnantwort auf Hitzeschmerz fand Schmahl (2006) bei BPS-Patientinnen mit Selbstverletzung?","a":"Mehr dlPFC-, weniger Amygdala-Aktivierung als Gesunde","w":["Mehr Amygdala-, weniger dlPFC-Aktivierung als Gesunde","Fehlende Aktivierung von S1 und Thalamus","Verstärkte Insula- und dACC-Aktivierung"],"why":"Antinozizeption durch präfrontale Hemmung und Deaktivierung limbischer Areale – passend zur berichteten Schmerzunempfindlichkeit."},{"q":"Welche Aussage zur Pharmakotherapie der BPS trifft zu?","a":"Kein Medikament zugelassen; Psychotherapie (z. B. DBT) ist Therapie der Wahl","w":["Lamotrigin reduzierte in einer großen RCT die Gesamtsymptomatik","SSRI sind Mittel der ersten Wahl gegen Affektinstabilität","Benzodiazepine senken Selbstverletzungen nachhaltig"],"why":"In der LABILE-RCT (Crawford 2018) war Lamotrigin Placebo nicht überlegen; Medikamente nur symptomorientiert und befristet."}],"src":"Schmahl, Arch Gen Psychiatry 2006; Crawford, Am J Psychiatry 2018"},{"id":"insomnie","name":"Insomnie","dis":"insomnie","level":3,"regions":[{"r":"hypothal","how":"hyper","note":"Wachfördernde Systeme (Orexin, Histamin) überwiegen gegenüber dem schlaffördernden VLPO"},{"r":"thalamus","how":"hyper","note":"Geringerer Abfall des Glukosemetabolismus von Wach zu NREM (Nofzinger 2004)"},{"r":"dacc","how":"hyper","note":"Persistierende Aktivität im Schlafübergang, passend zu nächtlichem Grübeln"},{"r":"insula","how":"hyper","note":"Wie Thalamus und ACC: verminderte Deaktivierung im Schlaf"},{"r":"lc","how":"hyper","note":"Noradrenerge Überaktivierung; erhöhte nächtliche Herzfrequenz und Katecholamine"}],"nt":["Orexin","GABA","Noradrenalin","Histamin","Adenosin","Melatonin"],"models":["Hyperarousal: kognitive, autonome und kortikale Übererregung bei Tag und Nacht","3P-Modell (Spielman): prädisponierende, auslösende und aufrechterhaltende Faktoren","Zwei-Prozess-Modell (Borbély): homöostatischer Schlafdruck (Adenosin) plus zirkadianer Prozess","Flip-Flop-Schalter (Saper): wechselseitige Hemmung von VLPO und Wachsystemen, Orexin stabilisiert"],"nut":"Koffein (lange HWZ, CYP1A2) ab dem Nachmittag meiden; Alkohol verkürzt die Einschlafzeit, fragmentiert aber die zweite Nachthälfte; späte große Mahlzeiten verschlechtern den Schlaf.","mcq":[{"q":"Wie wirkt Daridorexant bei Insomnie?","a":"Duale Orexin-1/2-Rezeptor-Antagonisierung, dämpft Wachsignale","w":["Positive Modulation α1-haltiger GABA-A-Rezeptoren","Agonismus an MT1/MT2-Rezeptoren im Hypothalamus","H1-Antagonismus im tuberomammillären Kern"],"why":"DORAs hemmen das Wachsystem statt den Kortex global zu dämpfen; weniger Toleranz und Rebound als Z-Substanzen."},{"q":"Welcher PET-Befund stützt das Hyperarousal-Modell der Insomnie (Nofzinger 2004)?","a":"Geringerer Metabolismusabfall von Wach zu NREM in Weckarealen","w":["Erhöhter Metabolismus des VLPO während des Schlafs","Verstärkter Metabolismusabfall im Thalamus während NREM","Verminderter globaler Glukosemetabolismus im Schlaf"],"why":"Aufsteigendes retikuläres System, Hypothalamus, Thalamus, Insula, ACC und Amygdala ‚schalten‘ beim Einschlafen weniger ab."},{"q":"Welche KVT-I-Komponente gilt als besonders wirksam, erhöht aber anfangs die Tagesmüdigkeit?","a":"Schlafrestriktion (Bettzeitverkürzung)","w":["Schlafhygiene-Edukation","Progressive Muskelrelaxation","Kognitive Umstrukturierung"],"why":"Sie erhöht gezielt den Schlafdruck und festigt den Schlaf; Schlafhygiene allein ist als Monotherapie kaum wirksam."}],"src":"Nofzinger, Am J Psychiatry 2004"},{"id":"narkolepsie","name":"Narkolepsie (Typ 1)","dis":"narkolepsie","level":3,"regions":[{"r":"hypothal","how":"loss","note":"Verlust des Großteils der Orexin-Neurone im lateralen Hypothalamus (Thannickal 2000)"},{"r":"brainstem","how":"hyper","note":"Enthemmte pontine REM-Generatoren → REM-Intrusionen und Atonie im Wachzustand (Kataplexie)"},{"r":"lc","how":"hypo","note":"Der LC stellt bei Kataplexie sein Feuern ein (Hundemodell, Wu 1999)"},{"r":"amygdala","how":"hyper","note":"Emotionale Auslöser (Lachen) der Kataplexie; Amygdala-Aktivierung während Attacken"}],"nt":["Orexin (Hypokretin)","Histamin","Noradrenalin","Acetylcholin (REM)","GABA/Glycin (Atonie)"],"models":["Autoimmunhypothese: HLA-DQB1*06:02 bei nahezu allen Typ-1-Fällen; hypokretinreaktive T-Zellen (Latorre 2018)","Instabiler Flip-Flop: ohne Orexin wechseln Wach-, NREM- und REM-Zustände abrupt","REM-Dissoziation: Kataplexie, Schlaflähmung und hypnagoge Halluzinationen als REM-Elemente im Wachen","Typ 1 (Kataplexie, Orexin im Liquor ↓) vs. Typ 2 (Orexin normal)"],"nut":"Typ 1 mit erhöhtem BMI trotz nicht erhöhter Kalorienzufuhr (Orexin regelt Energieumsatz); Natriumoxybat liefert viel Natrium; Pitolisant senkt die Wirkung hormoneller Kontrazeptiva.","mcq":[{"q":"Welcher Liquorbefund sichert eine Narkolepsie Typ 1?","a":"Hypokretin-1 ≤ 110 pg/ml (bzw. < 1/3 des Normwerts)","w":["Erhöhtes Hypokretin-1 bei erniedrigtem Histamin","Oligoklonale Banden bei HLA-DQB1*06:02","Erniedrigtes Melatonin bei normalem Hypokretin"],"why":"Der Orexin-Mangel ist pathognomonisch für Typ 1; HLA-DQB1*06:02 ist zwar fast immer vorhanden, aber unspezifisch (häufig in der Bevölkerung)."},{"q":"Welcher Impfstoff war 2009/10 in Nordeuropa mit einem Anstieg kindlicher Narkolepsie assoziiert?","a":"AS03-adjuvantierter H1N1-Impfstoff (Pandemrix)","w":["MF59-adjuvantierter H1N1-Impfstoff (Focetria)","Saisonaler Influenza-Lebendimpfstoff","Tetravalenter HPV-Impfstoff"],"why":"Das Signal betraf Pandemrix, nicht Focetria; auch die H1N1-Infektion selbst gilt als Trigger – passend zur Autoimmunhypothese."}],"src":"Thannickal, Neuron 2000; Latorre, Nature 2018; Wu, J Neurosci 1999"},{"id":"delir","name":"Delir","dis":"delir","level":3,"regions":[{"r":"nbm","how":"hypo","note":"Cholinerges Defizit – anticholinerge Medikation ist ein starker Auslöser"},{"r":"microglia","how":"hyper","note":"Systemische Entzündung aktiviert ‚geprimte‘ Mikroglia, v. a. bei vorbestehender Neurodegeneration"},{"r":"thalamus","how":"dysconnect","note":"Gestörte thalamokortikale Filterung und Aufmerksamkeitssteuerung"},{"r":"dlpfc","how":"hypo","note":"Aufmerksamkeitsdefizit als Kernsymptom"},{"r":"pcc","how":"dysconnect","note":"Umgekehrte Kopplung zwischen dlPFC und PCC während des Delirs (Choi 2012)"}],"nt":["Acetylcholin (↓)","Dopamin (↑)","GABA","Glutamat","Zytokine (IL-6, TNF-α)"],"models":["Vulnerabilität × Auslöser (Inouye): je höher die Vorbelastung, desto geringer der nötige Trigger","Cholinerges Defizit: anticholinerge Last als starker, vermeidbarer Risikofaktor","Neuroinflammation: systemische Entzündung aktiviert vorgeschädigte Mikroglia","Netzwerk-Dyskonnektivität: Zusammenbruch der Balance zwischen DMN und Aufgabennetzwerken"],"nut":"Dehydratation, Hypo-/Hypernatriämie, Hypoglykämie und Thiaminmangel sind behandelbare Auslöser; Mangelernährung erhöht das Risiko; bei Alkoholanamnese Thiamin vor bzw. mit Glukose.","mcq":[{"q":"Welche Maßnahme senkt die Delirinzidenz bei älteren Krankenhauspatienten nachweislich?","a":"Multikomponenten-Prävention (Orientierung, Schlaf, Mobilisation, Hydratation)","w":["Prophylaktisches Haloperidol für alle Risikopatienten","Routinemäßige Rivastigmin-Gabe bei Aufnahme","Benzodiazepine zur Nacht zur Schlafsicherung"],"why":"Das Hospital Elder Life Program senkte die Inzidenz (Inouye 1999); Haloperidol-Prophylaxe senkt sie nicht, Rivastigmin schadete auf der ICU."},{"q":"Welcher Delir-Subtyp ist am häufigsten und wird am häufigsten übersehen?","a":"Hypoaktives Delir","w":["Hyperaktives Delir","Gemischtes Delir","Delirium tremens"],"why":"Ruhige, apathische Patienten fallen nicht auf – trotz schlechterer Prognose; Screening (z. B. 4AT, CAM) ist daher nötig."}],"src":"Inouye, NEJM 1999; Choi, Am J Psychiatry 2012"},{"id":"alzheimer","name":"Alzheimer-Krankheit","dis":"alzheimer","level":3,"regions":[{"r":"entorhinal","how":"atrophy","note":"Erster kortikaler Ort der Tau-Pathologie (Braak I–II), früher Neuronenverlust in Schicht II"},{"r":"hippocampus","how":"atrophy","note":"Progrediente Atrophie, korreliert mit Gedächtnisstörung"},{"r":"nbm","how":"loss","note":"Verlust cholinerger Neurone → Rationale der AChE-Hemmer"},{"r":"precuneus","how":"hypo","note":"Früher FDG-Hypometabolismus und frühe Amyloidablagerung im DMN"},{"r":"ppc","how":"hypo","note":"Temporoparietaler Hypometabolismus/Hypoperfusion als typisches Muster"},{"r":"microglia","how":"hyper","note":"Plaque-assoziierte Mikroglia; TREM2-Varianten erhöhen das Risiko"},{"r":"lc","how":"loss","note":"Frühe Tau-Pretangles im Locus coeruleus, teils schon im jungen Erwachsenenalter (Braak 2011)"}],"nt":["Acetylcholin","Glutamat (NMDA)"],"models":["Amyloid-Kaskade (Hardy & Higgins 1992): Aβ-Aggregation löst Tau-Pathologie und Neurodegeneration aus","Tau-Ausbreitung nach Braak: transentorhinal → limbisch → neokortikal; korreliert enger mit Kognition als Amyloid","Neuroinflammation: TREM2 und weitere Mikroglia-Gene als Risikofaktoren","Biologische Definition über Biomarker (A/T/N, Blut-pTau217) statt rein klinischer Diagnose","ApoE4 ist der stärkste genetische Risikofaktor der sporadischen Form; ApoE2 schützt"],"nut":"Lancet-Kommission 2024: 14 modifizierbare Faktoren (u. a. Hypertonie, Diabetes, LDL, Hörverlust); MIND-Diät-RCT ohne signifikanten Kognitionsvorteil (Barnes 2023); B12-Mangel als DD.","mcq":[{"q":"Wo beginnt die neurofibrilläre Tau-Pathologie nach Braak typischerweise im Kortex?","a":"Transentorhinaler/entorhinaler Kortex","w":["Präcuneus und posteriores Cingulum","Hippocampus, Region CA3","Primärer visueller Kortex"],"why":"Tau: transentorhinal → limbisch → neokortikal; Amyloid lagert sich dagegen zuerst neokortikal ab, u. a. im Präcuneus."},{"q":"Warum erhöhen Loss-of-Function-Varianten von TREM2 (z. B. R47H) das Alzheimer-Risiko?","a":"Gestörte Mikroglia-Antwort auf Amyloid-Plaques","w":["Gesteigerte APP-Spaltung durch die β-Sekretase","Verminderte Tau-Phosphorylierung in Neuronen","Erhöhte ApoE4-Synthese in Astrozyten"],"why":"TREM2 vermittelt Aktivierung, Plaque-Umhüllung und Phagozytose; ohne sie bleiben Plaques ‚offen‘ und toxischer für Neuriten."}],"src":"Braak, J Neuropathol Exp Neurol 2011; Livingston, Lancet 2024; Barnes, NEJM 2023"},{"id":"ftd","name":"Frontotemporale Demenz (FTD)","dis":"frontotemporale_demenz","level":3,"regions":[{"r":"ofc","how":"atrophy","note":"Frühe orbitofrontale Atrophie bei der Verhaltensvariante (bvFTD) → Enthemmung"},{"r":"vmpfc","how":"atrophy","note":"Verlust von Empathie, Einsicht und sozialer Bewertung"},{"r":"insula","how":"atrophy","note":"Anteriore Insula früh betroffen – Verlust von Von-Economo-Neuronen (Seeley 2006)"},{"r":"dacc","how":"atrophy","note":"Teil des degenerierenden Salienznetzwerks → Apathie"},{"r":"temppol","how":"atrophy","note":"Semantische Variante: links betonte Temporalpol-Atrophie → Wortbedeutungsverlust"},{"r":"broca","how":"atrophy","note":"Nichtflüssige Variante: linker inferiorer Frontalkortex → Agrammatismus, Sprechapraxie"}],"nt":["Serotonin","Dopamin","Glutamat"],"models":["Proteinopathien: TDP-43 (Großteil), Tau (MAPT) oder FUS","Genetik: C9orf72-Expansion (häufigste, auch ALS), GRN (Progranulin), MAPT","Selektive Vulnerabilität: Verlust von Von-Economo-Neuronen im Salienznetzwerk (Seeley 2006)","ALS-FTD-Spektrum: klinische, genetische und pathologische Überlappung"],"nut":"bvFTD: Hyperoralität und Süßhunger (Diagnosekriterium) mit Gewichtszunahme, assoziiert mit OFC-, Insula- und Hypothalamus-Atrophie; später Dysphagie; AChE-Hemmer ohne Nutzen.","mcq":[{"q":"Welche genetische Ursache verbindet FTD und ALS am häufigsten?","a":"GGGGCC-Hexanukleotid-Expansion in C9orf72","w":["Haploinsuffizienz von GRN (Progranulin)","Mutationen im MAPT-Gen (Tau)","Mutationen im SOD1-Gen"],"why":"C9orf72 verursacht FTD, ALS oder beides; GRN und MAPT verursachen fast nur FTD, SOD1 fast nur ALS."},{"q":"Welche Zellpopulation geht bei bvFTD früh in anteriorer Insula und ACC verloren (Seeley 2006)?","a":"Von-Economo-Neurone (Spindelneurone)","w":["Betz-Riesenpyramidenzellen","Purkinje-Zellen","Chandelier-Interneurone"],"why":"Diese großen Projektionsneurone kommen fast nur bei Menschenaffen, Menschen, Walen und Elefanten vor – Teil des Salienznetzwerks."}],"src":"Seeley, Ann Neurol 2006"},{"id":"lewy","name":"Lewy-Körperchen-Demenz (DLB)","dis":"lewy_koerperchen_demenz","level":3,"regions":[{"r":"nbm","how":"loss","note":"Ausgeprägteres cholinerges Defizit als bei Alzheimer → oft gutes Ansprechen auf AChE-Hemmer"},{"r":"v1","how":"hypo","note":"Okzipitaler Hypometabolismus → visuelle Halluzinationen"},{"r":"putamen","how":"loss","note":"Reduzierte DaT-Bindung im SPECT – stützt DLB gegenüber Alzheimer"},{"r":"sn","how":"loss","note":"Dopaminerger Neuronenverlust → Parkinsonismus"},{"r":"brainstem","how":"loss","note":"α-Synuklein u. a. im Nucleus subcoeruleus → REM-Schlaf-Verhaltensstörung, oft Jahre vorher"}],"nt":["Acetylcholin","Dopamin"],"models":["α-Synuklein-Ausbreitung; Kopathologie mit Amyloid und Tau verschlechtert den Verlauf","Cholinerges Defizit (stärker als bei Alzheimer) → Fluktuationen und Halluzinationen","Ein-Jahres-Regel: Demenz vor oder bis 1 Jahr nach Parkinsonismus = DLB, später = Parkinson-Demenz","Prodromi: REM-Schlaf-Verhaltensstörung, Hyposmie, autonome Störungen"],"nut":"Schwere Neuroleptika-Überempfindlichkeit – D2-Antagonisten meiden; Orthostase und Obstipation (autonom) → Flüssigkeit, Ballaststoffe, Salz nach ärztlicher Rücksprache; Dysphagie im Verlauf.","mcq":[{"q":"Welcher Bildgebungsbefund stützt eine DLB gegenüber einer Alzheimer-Demenz?","a":"Vermindertes striatales Signal im DaT-SPECT","w":["Ausgeprägte Hippocampusatrophie im MRT","Positives Amyloid-PET","Frontotemporale Hypoperfusion im SPECT"],"why":"DaT-SPECT ist ein indikativer Biomarker; Amyloid ist auch bei vielen DLB-Patienten positiv, der Hippocampus eher relativ erhalten."},{"q":"Was bezeichnet das ‚Cingulate Island Sign‘ im FDG-PET?","a":"Erhaltener PCC-Stoffwechsel bei Hypometabolismus von Präcuneus/Cuneus","w":["Isolierter PCC-Hypometabolismus bei frühem Alzheimer","Hypermetabolismus des ACC bei bvFTD","Inselförmige Amyloidablagerung im Cingulum"],"why":"Typisch für DLB: der PCC bleibt relativ ausgespart, während er bei Alzheimer früh hypometabol ist."},{"q":"Welche Prodromalerscheinung sagt Synucleinopathien (Parkinson, DLB, MSA) mit der höchsten Konversionsrate voraus?","a":"Isolierte REM-Schlaf-Verhaltensstörung","w":["Restless-Legs-Syndrom","Obstruktive Schlafapnoe","Isolierte Hyposmie"],"why":"Die Mehrheit der Betroffenen mit isolierter RBD entwickelt binnen etwa 12 Jahren eine Synucleinopathie (Postuma 2019); Hyposmie ist weniger spezifisch."}],"src":"Postuma, Brain 2019"},{"id":"parkinson","name":"Morbus Parkinson","dis":"parkinson","level":3,"regions":[{"r":"sn","how":"loss","note":"Verlust dopaminerger Neurone der ventrolateralen Pars compacta mit Lewy-Körpern"},{"r":"putamen","how":"hypo","note":"Stärkster Dopaminverlust im dorsalen/posterioren (sensomotorischen) Putamen"},{"r":"gp","how":"hyper","note":"GPi überaktiv (Ratenmodell) → verstärkte Thalamushemmung; DBS-Ziel"},{"r":"thalamus","how":"hypo","note":"Verminderte thalamokortikale Erregung → Bradykinese"},{"r":"m1","how":"hypo","note":"Verminderte Aktivierung motorischer und supplementär-motorischer Areale"},{"r":"brainstem","how":"loss","note":"Braak 1–2: dorsaler Vaguskern und Medulla vor der Nigra betroffen (Prodromi)"},{"r":"lc","how":"loss","note":"Noradrenerger Neuronenverlust → Depression, Angst, autonome Symptome"}],"nt":["Dopamin","Acetylcholin (relativ ↑, striatal)","Noradrenalin","Serotonin","Glutamat (STN)"],"models":["Ratenmodell (Albin/DeLong): direkter Pfad ↓, indirekter ↑ → GPi/SNr hemmen den Thalamus stärker","Oszillationsmodell: übersteigerte β-Synchronie (13–30 Hz) in STN/GPi korreliert mit Bradykinese","Braak-Staging: Lewy-Pathologie aufsteigend von Medulla/Bulbus olfactorius zur Nigra und zum Kortex","Body-first vs. brain-first: Beginn im enterischen oder im zentralen Nervensystem (Borghammer)","Biomarker: α-Synuklein-Seed-Amplification-Assay im Liquor (Siderowf 2023)"],"nut":"Obstipation oft Jahre vor der Motorik; Gewichtsverlust im Verlauf; Kaffee und Rauchen invers assoziiert (Kausalität unklar); Nahrungsprotein konkurriert mit L-Dopa um den LAT1-Transport.","mcq":[{"q":"Welcher Teil des Striatums verliert bei idiopathischem Parkinson zuerst und am stärksten Dopamin?","a":"Dorsales (posteriores) Putamen","w":["Kopf des Nucleus caudatus","Ventrales Striatum (Nucleus accumbens)","Anteriores ventrales Putamen"],"why":"Der Gradient (posterior > anterior, dorsal > ventral) erklärt die frühe motorische Betonung und die asymmetrische DaT-Minderung."},{"q":"Was folgt laut Basalganglien-Ratenmodell aus dem Dopaminmangel?","a":"Überaktivität von STN und GPi mit verstärkter Thalamushemmung","w":["Unteraktivität von STN und GPi mit Thalamusenthemmung","Überaktivität des GPe mit Hemmung des STN","Verstärkter direkter Pfad über D1-Rezeptoren"],"why":"D2-Verlust enthemmt den indirekten Pfad (GPe ↓ → STN ↑ → GPi ↑), D1-Verlust schwächt den direkten – beides hemmt den Thalamus."},{"q":"Welcher Test weist α-Synuklein-Pathologie im Liquor mit hoher Sensitivität nach (Siderowf, Lancet Neurol 2023)?","a":"α-Synuklein-Seed-Amplification-Assay (SAA)","w":["DaT-SPECT mit semiquantitativer Auswertung","ELISA für Gesamt-α-Synuklein im Liquor","Neurofilament-Leichtketten (NfL) im Serum"],"why":"SAA weist aggregationsfähige Seeds nach; die Sensitivität war bei LRRK2-Trägern und Personen ohne Hyposmie geringer."}],"src":"Siderowf, Lancet Neurol 2023"},{"id":"huntington","name":"Chorea Huntington","dis":"huntington","level":3,"regions":[{"r":"caudate","how":"atrophy","note":"Früheste und stärkste Atrophie, Jahre vor der klinischen Manifestation messbar"},{"r":"putamen","how":"atrophy","note":"Atrophie folgt dem Caudatum; Verlust mittelgroßer Projektionsneurone (MSN)"},{"r":"gp","how":"hyper","note":"GPe enthemmt durch Verlust indirekter MSN → STN/GPi gedämpft → Thalamusenthemmung, Chorea"},{"r":"ventrikel","how":"atrophy","note":"Erweiterte Vorderhörner (‚Boxcar‘-Ventrikel) durch Caudatum-Atrophie"},{"r":"dlpfc","how":"atrophy","note":"Kortikale Verdünnung → exekutive Defizite und Apathie"},{"r":"hypothal","how":"loss","note":"Verlust von Orexin-Neuronen (Petersén 2005) → Schlaf- und Gewichtsstörungen"}],"nt":["GABA (MSN)","Dopamin (relativ ↑)","Glutamat (Exzitotoxizität)","Enkephalin/Substanz P"],"models":["Autosomal-dominante CAG-Expansion im HTT-Gen: ≥ 40 volle, 36–39 reduzierte Penetranz; Antizipation v. a. paternal","Somatische CAG-Expansion in Neuronen bestimmt das Erkrankungsalter mit (GeM-HD 2019)","Selektive Vulnerabilität: MSN des indirekten Pfads zuerst (Chorea), des direkten später (Rigidität)","Toxischer Funktionsgewinn des mutierten Huntingtins: Aggregate, transkriptionelle und mitochondriale Störung"],"nut":"Ungewollter Gewichtsverlust trotz hoher Zufuhr (Hypermetabolismus, hypothalamische Beteiligung) → energiedichte Kost; Dysphagie, Aspirationsgefahr; höheres Gewicht mit langsamerem Verlauf verknüpft.","mcq":[{"q":"Welche striatale Neuronenpopulation degeneriert bei Huntington zuerst und erklärt die frühe Chorea?","a":"Enkephalin-/D2-tragende MSN des indirekten Pfads","w":["Substanz-P-/D1-tragende MSN des direkten Pfads","Cholinerge striatale Interneurone","Parvalbumin-positive striatale Interneurone"],"why":"Ihr Verlust enthemmt den GPe, dämpft STN/GPi und damit die Thalamushemmung – überschießende Bewegung; cholinerge Interneurone bleiben relativ verschont."},{"q":"Was bestimmt laut GeM-HD (Cell 2019) das Erkrankungsalter besser als die Polyglutaminlänge?","a":"Die Länge der ununterbrochenen CAG-Sequenz","w":["Die Expression des Wildtyp-HTT-Allels","Die Länge der prolinreichen Region","Das maternale Methylierungsmuster von HTT"],"why":"Verlust der CAA-Unterbrechung führt bei gleicher Polyglutaminlänge zu früherem Beginn; DNA-Reparatur-Modifier (FAN1, MSH3) treiben die somatische Expansion."}],"src":"GeM-HD Consortium, Cell 2019; Petersén, Hum Mol Genet 2005"},{"id":"tle","name":"Mesiale Temporallappenepilepsie","dis":"epilepsie","level":3,"regions":[{"r":"hippocampus","how":"loss","note":"Hippocampussklerose: Neuronenverlust v. a. in CA1 und CA4 (Hilus) mit Gliose, CA2 relativ verschont"},{"r":"amygdala","how":"hyper","note":"Häufiger Anfallsursprung bzw. -ausbreitung; Aura mit Angst oder epigastrischem Aufsteigen"},{"r":"entorhinal","how":"hyper","note":"Eintrittspforte der Anfallsausbreitung in den Hippocampus; Zellverlust in Schicht III"},{"r":"interneuron","how":"loss","note":"Verlust hilärer (Somatostatin-)Interneurone → verminderte Hemmung im Gyrus dentatus"},{"r":"temppol","how":"hypo","note":"Interiktaler ipsilateraler temporaler Hypometabolismus im FDG-PET (Lateralisierung)"},{"r":"thalamus","how":"dysconnect","note":"Thalamus in das Anfallsnetzwerk eingebunden; anteriorer Thalamus als DBS-Ziel"}],"nt":["Glutamat","GABA"],"models":["Initiales präzipitierendes Ereignis (z. B. komplizierter Fieberkrampf) → Latenz → Hippocampussklerose","Moosfaser-Sprouting: Körnerzellen bilden rekurrente exzitatorische Verbindungen","Interneuronverlust im Hilus → verminderte Hemmung im Gyrus dentatus","Pharmakoresistenz bei etwa einem Drittel → Epilepsiechirurgie überlegen (Wiebe 2001)"],"nut":"Ketogene bzw. modifizierte Atkins-Diät bei Pharmakoresistenz wirksam (v. a. Kinder); Valproat: Gewichtszunahme, Folsäure bei Kinderwunsch; Enzyminduktoren senken Vitamin D (Knochen).","mcq":[{"q":"Welches histopathologische Muster kennzeichnet die klassische Hippocampussklerose (ILAE Typ 1)?","a":"Neuronenverlust v. a. in CA1 und CA4, CA2 relativ verschont","w":["Selektiver Verlust der Körnerzellen des Gyrus dentatus","Neuronenverlust v. a. in CA2 bei erhaltenem CA1","Neurofibrilläre Bündel im Subiculum ohne Gliose"],"why":"Typ 1: schwerer Verlust in CA1 und CA4 (Hilus), CA2 resistenter; Körnerzellen zeigen eher Dispersion als vollständigen Verlust."},{"q":"Nach Versagen von wie vielen adäquat gewählten und vertragenen Antiepileptika gilt eine Epilepsie laut ILAE als pharmakoresistent?","a":"Zwei","w":["Eins","Drei","Vier"],"why":"Nach zwei gescheiterten Regimen ist die Chance auf Anfallsfreiheit durch weitere Medikamente gering – Zeitpunkt für die prächirurgische Abklärung (Kwan 2010)."}],"src":"Wiebe, NEJM 2001; Kwan, Epilepsia 2010"},{"id":"migraene","name":"Migräne","dis":"migraene","level":3,"regions":[{"r":"v1","how":"hyper","note":"Kortikale Hyperexzitabilität; Cortical Spreading Depolarization → Aura"},{"r":"brainstem","how":"hyper","note":"Dorsale Pons und trigeminaler Kern aktiv in der Attacke; trigeminovaskuläre Bahn (CGRP)"},{"r":"hypothal","how":"hyper","note":"Aktivitätsanstieg ~24 h vor der Attacke (Schulte & May 2016) → Prodromi wie Gähnen, Heißhunger"},{"r":"thalamus","how":"hyper","note":"Zentrale Sensibilisierung → Allodynie, Photophobie"}],"nt":["CGRP","Serotonin (5-HT1B/1D/1F)","PACAP","Glutamat"],"models":["Cortical Spreading Depolarization (Leão 1944) als Korrelat der Aura, aktiviert trigeminale Afferenzen","Trigeminovaskuläres System: CGRP-Freisetzung → Vasodilatation und Sensibilisierung (Ziel von Gepanten/mAbs)","Hypothalamus als Generator der Prodromalphase (Schulte & May 2016)","Neuronale statt vaskuläre Ursache: Vasodilatation ist weder notwendig noch hinreichend"],"nut":"Regelmäßige Mahlzeiten (Fasten/Hypoglykämie triggern); Koffein-Übergebrauch und -Entzug meiden; Alkohol (v. a. Rotwein) als Trigger; Magnesium und Riboflavin prophylaktisch mit begrenzter Evidenz.","mcq":[{"q":"Welcher monoklonale Antikörper zur Migräneprophylaxe richtet sich gegen den CGRP-Rezeptor statt gegen CGRP selbst?","a":"Erenumab","w":["Fremanezumab","Galcanezumab","Eptinezumab"],"why":"Erenumab blockiert den Rezeptor (Calcitonin-Receptor-like Receptor/RAMP1); die anderen drei binden den Liganden CGRP."},{"q":"Warum ist Lasmiditan im Gegensatz zu Triptanen nicht wegen KHK kontraindiziert?","a":"Es wirkt am 5-HT1F-Rezeptor ohne vasokonstriktive 5-HT1B-Wirkung","w":["Es ist ein oraler CGRP-Rezeptorantagonist","Es wirkt nur zentral am 5-HT1D-Rezeptor","Es ist ein selektiver 5-HT2B-Antagonist"],"why":"‚Ditane‘ verengen keine Koronarien; dafür sedieren sie – Fahrverbot für mehrere Stunden nach Einnahme."},{"q":"Welche Region zeigte im täglichen fMRT über 30 Tage (Schulte & May 2016) erhöhte Aktivität schon etwa 24 h vor der Attacke?","a":"Hypothalamus","w":["Dorsale Pons","Primäre Sehrinde","Periaquäduktales Grau"],"why":"Der Hypothalamus erklärt Prodromi (Müdigkeit, Gähnen, Heißhunger); die dorsale Pons war vor allem während der Attacke aktiv."}],"src":"Schulte & May, Brain 2016"},{"id":"wernicke","name":"Wernicke-Korsakow-Syndrom","dis":"wernicke_korsakow","level":3,"regions":[{"r":"mammillar","how":"lesion","note":"Symmetrische Läsionen und Atrophie; im MRT teils Kontrastmittelanreicherung"},{"r":"thalamus","how":"lesion","note":"Mediale/anteriore Kerne; Degeneration der anterioren Kerne trennt Amnesie von Nicht-Amnesie (Harding 2000)"},{"r":"brainstem","how":"lesion","note":"Periaquäduktale Läsionen, okulomotorische und vestibuläre Kerne → Ophthalmoplegie, Nystagmus"},{"r":"cerebellum","how":"atrophy","note":"Vermis-Degeneration → Gangataxie"}],"nt":["Glutamat (Exzitotoxizität bei Energiemangel)"],"models":["Thiaminpyrophosphat ist Kofaktor von PDH, α-KGDH und Transketolase → Energieversagen in aktiven Regionen","Klassische Trias (Ophthalmoplegie, Ataxie, Verwirrtheit) nur bei einer Minderheit → Caine-Kriterien","Korsakow: dienzephale Amnesie (anteriore Thalamuskerne, Mammillarkörper) mit Konfabulation","Ursachen auch ohne Alkohol: Bariatrie, Hyperemesis, Anorexie/Refeeding, Tumorleiden, Dialyse"],"nut":"Thiamin parenteral vor bzw. mit Glukose (Glukose verbraucht Thiamin); Magnesiummangel mitbehandeln (Kofaktor); Risiko auch bei Bariatrie, Hyperemesis und Anorexie/Refeeding.","mcq":[{"q":"Was fordern die Caine-Kriterien (1997) für eine Wernicke-Enzephalopathie bei Alkoholabhängigen?","a":"2 von 4: Mangelernährung, Okulomotorik, Kleinhirnzeichen, Bewusstsein/Gedächtnis","w":["Vollständige Trias plus erniedrigtes Serum-Thiamin","MRT-Läsion der Corpora mammillaria plus Ataxie","Konfabulation plus Nystagmus plus Polyneuropathie"],"why":"Die Trias liegt nur selten vollständig vor; die Caine-Kriterien erhöhen die Sensitivität deutlich – Thiamin vorsorglich geben."},{"q":"Welches Thiamin-abhängige Enzym wird in Erythrozyten zur funktionellen Mangeldiagnostik gemessen?","a":"Transketolase","w":["Pyruvatdehydrogenase","α-Ketoglutarat-Dehydrogenase","Verzweigtkettige α-Ketosäure-Dehydrogenase"],"why":"Erythrozyten-Transketolase-Aktivität mit TPP-Stimulationseffekt; heute oft ergänzt durch Vollblut-TPP (HPLC)."},{"q":"Welche Läsion unterscheidet laut Harding (Brain 2000) amnestische Alkoholkranke von solchen ohne Amnesie?","a":"Degeneration der anterioren Thalamuskerne","w":["Bilaterale Hippocampusatrophie","Degeneration des Kleinhirnwurms","Atrophie des präfrontalen Kortex"],"why":"Mammillarkörper waren in beiden Gruppen betroffen; entscheidend für die Korsakow-Amnesie war der anteriore Thalamus."}],"src":"Caine, J Neurol Neurosurg Psychiatry 1997; Harding, Brain 2000"}],"drugs":[{"id":"ssri","name":"SSRI (z. B. Escitalopram, Sertralin)","cls":"Antidepressivum","level":4,"target":"Hemmung des Serotonintransporters (SERT)","regions":["raphe","sert","terminal5ht","r5ht1a"],"mech":"Blockieren die Wiederaufnahme von Serotonin. Die Stimmung bessert sich erst nach Wochen: Somatodendritische 5-HT1A-Autorezeptoren der Raphe-Kerne desensibilisieren, dazu kommen nachgeschaltete Plastizitätseffekte (BDNF).","use":"Depression, Angst-, Panik- und Zwangsstörung, PTBS","se":"Übelkeit, sexuelle Funktionsstörungen, Unruhe zu Beginn, Hyponatriämie (SIADH, v. a. Ältere), Blutungsneigung, QT-Verlängerung (Citalopram), Serotoninsyndrom in Kombinationen, Absetzsymptome","nut":"Johanniskraut meiden (Serotoninsyndrom, CYP-Induktion). Hyponatriämie bei Älteren mit Diuretika beachten. Langfristig teils Gewichtszunahme.","mcq":[{"q":"Warum setzt die antidepressive Wirkung von SSRI erst nach Wochen ein, obwohl SERT sofort blockiert ist?","a":"Die 5-HT1A-Autorezeptoren der Raphe müssen erst desensibilisieren","w":["Der Steady State im Gehirn wird erst nach Wochen erreicht","Serotonin muss erst aus Tryptophan nachgebildet werden","SERT wird erst nach Wochen vollständig internalisiert"],"why":"Akut bremst mehr Serotonin über 5-HT1A-Autorezeptoren die Raphe-Neurone; erst ihre Desensibilisierung steigert die kortikale Freisetzung dauerhaft."},{"q":"Welche Elektrolytstörung ist unter SSRI bei älteren Menschen typisch?","a":"Hyponatriämie durch SIADH","w":["Hyperkaliämie","Hypokalzämie","Hypermagnesiämie"],"why":"SSRI können die ADH-Ausschüttung steigern; Risiko steigt mit Alter und Diuretika."}]},{"id":"snri","name":"SNRI (Venlafaxin, Duloxetin)","cls":"Antidepressivum","level":4,"target":"Hemmung von SERT und NET","regions":["raphe","lc","sert"],"mech":"Hemmen die Wiederaufnahme von Serotonin und Noradrenalin. Venlafaxin wirkt im unteren Bereich vorwiegend serotonerg, die noradrenerge Komponente kommt erst bei höheren Spiegeln hinzu.","use":"Depression, generalisierte Angststörung; Duloxetin auch bei diabetischer Polyneuropathie","se":"wie SSRI, zusätzlich Blutdruckanstieg, Schwitzen, ausgeprägtes Absetzsyndrom (Venlafaxin)","nut":"","mcq":[{"q":"Welche Zusatzindikation hebt Duloxetin von den SSRI ab?","a":"Schmerzhafte diabetische Polyneuropathie","w":["Alkoholentzugssyndrom","Narkolepsie mit Kataplexie","Bulimia nervosa"],"why":"Die noradrenerge Verstärkung absteigender Schmerzhemmbahnen erklärt die analgetische Wirkung."}]},{"id":"tza","name":"Trizyklische Antidepressiva (z. B. Amitriptylin)","cls":"Antidepressivum","level":4,"target":"SERT/NET-Hemmung plus Blockade von H1-, M1- und α1-Rezeptoren","regions":["raphe","lc","sert"],"mech":"Hemmen die Wiederaufnahme von Serotonin und Noradrenalin; die Blockade weiterer Rezeptoren erklärt Sedierung, anticholinerge Effekte und Blutdruckabfall.","use":"Depression (meist nicht 1. Wahl), chronischer Schmerz, Migräneprophylaxe","se":"anticholinerg (Mundtrockenheit, Obstipation, Harnverhalt, Delir), Sedierung, Orthostase, Gewichtszunahme; in Überdosis kardiotoxisch durch Natriumkanalblock (QRS-Verbreiterung)","nut":"Gewichtszunahme über H1; Obstipation, daher ballaststoff- und flüssigkeitsreich essen; Alkohol verstärkt die Sedierung.","mcq":[{"q":"Was macht Trizyklika in Überdosis besonders gefährlich?","a":"Natriumkanalblockade am Herzen mit QRS-Verbreiterung","w":["Hepatotoxizität durch reaktive Metaboliten","Atemdepression über µ-Opioidrezeptoren","Hyperthermie durch D2-Blockade"],"why":"Der Natriumkanalblock verursacht Arrhythmien; Natriumbikarbonat ist die spezifische Gegenmaßnahme."}]},{"id":"maoi","name":"MAO-Hemmer (Tranylcypromin, Moclobemid)","cls":"Antidepressivum","level":4,"target":"Hemmung der Monoaminoxidase","regions":["raphe","lc","terminal5ht"],"mech":"Hemmen den Abbau von Serotonin, Noradrenalin und Dopamin. Tranylcypromin hemmt MAO-A und -B irreversibel, Moclobemid reversibel und selektiv MAO-A.","use":"therapieresistente Depression (Tranylcypromin), atypische Depression","se":"hypertensive Krise mit Tyramin, Serotoninsyndrom mit anderen serotonergen Mitteln, Schlafstörung, Orthostase","nut":"Unter irreversiblen MAO-Hemmern tyraminarme Kost: kein lang gereifter Käse, Rohwurst, Sauerkraut, Sojasoße, Hefeextrakt, Fassbier. Sonst droht eine hypertensive Krise (Cheese-Effekt).","mcq":[{"q":"Welches Lebensmittel ist unter Tranylcypromin am gefährlichsten?","a":"Lang gereifter Käse","w":["Frische Vollmilch","Grapefruitsaft","Grünes Blattgemüse"],"why":"Tyramin wird sonst von intestinaler und hepatischer MAO-A abgebaut; unter Hemmung setzt es Noradrenalin frei."},{"q":"Warum ist das Tyraminrisiko unter Moclobemid geringer als unter Tranylcypromin?","a":"Die Hemmung ist reversibel und wird von Tyramin verdrängt","w":["Moclobemid hemmt nur MAO-B","Moclobemid wirkt nicht im Darm","Moclobemid wird nicht resorbiert"],"why":"Hohe Tyraminkonzentrationen können Moclobemid kompetitiv vom Enzym verdrängen."}]},{"id":"mirtazapin","name":"Mirtazapin","cls":"Antidepressivum","level":4,"target":"α2-Antagonismus plus 5-HT2-, 5-HT3- und H1-Blockade","regions":["lc","raphe"],"mech":"Blockiert präsynaptische α2-Auto- und Heterorezeptoren und steigert so Noradrenalin- und Serotoninfreisetzung; die H1-Blockade macht müde und hungrig.","use":"Depression mit Schlafstörung oder Appetitverlust","se":"Sedierung, deutliche Gewichtszunahme, selten Agranulozytose","nut":"Appetit und Gewicht steigen (H1, 5-HT2C): bei Kachexie teils erwünscht, sonst Gewicht und Stoffwechsel verfolgen.","mcq":[{"q":"Welches Antidepressivum passt am ehesten zu Depression mit Insomnie und Gewichtsverlust?","a":"Mirtazapin","w":["Bupropion","Fluoxetin","Tranylcypromin"],"why":"Sedierung und Appetitsteigerung sind hier erwünschte Effekte."}]},{"id":"bupropion","name":"Bupropion","cls":"Antidepressivum","level":4,"target":"Hemmung von DAT und NET","regions":["vta","nacc","lc"],"mech":"Hemmt die Wiederaufnahme von Dopamin und Noradrenalin, kaum serotonerg; antriebssteigernd.","use":"Depression mit Antriebsmangel, Raucherentwöhnung; mit Naltrexon zur Gewichtsreduktion","se":"Schlafstörung, Unruhe, gesenkte Krampfschwelle; kaum sexuelle Nebenwirkungen","nut":"Kontraindiziert bei Bulimie und Anorexie wegen erhöhten Krampfrisikos; eher Gewichtsabnahme.","mcq":[{"q":"Warum ist Bupropion bei Bulimia nervosa kontraindiziert?","a":"Erhöhtes Risiko für Krampfanfälle","w":["Es verstärkt Essanfälle über D2","Es verursacht schwere Hypokaliämie","Es verzögert die Magenentleerung"],"why":"In frühen Studien traten bei Patientinnen mit Essstörungen gehäuft Anfälle auf."}]},{"id":"agomelatin","name":"Agomelatin","cls":"Antidepressivum","level":4,"target":"MT1/MT2-Agonismus und 5-HT2C-Antagonismus","regions":["hypothal","dlpfc"],"mech":"Stellt den zirkadianen Rhythmus über den Nucleus suprachiasmaticus neu ein; die 5-HT2C-Blockade enthemmt Dopamin und Noradrenalin im präfrontalen Kortex.","use":"Depression, besonders mit gestörtem Schlaf-Wach-Rhythmus","se":"Leberwerterhöhung bis Hepatotoxizität, Kopfschmerz; kaum sexuelle Nebenwirkungen, kein Absetzsyndrom","nut":"Alkohol meiden (Leberbelastung).","mcq":[{"q":"Welche Laborkontrolle ist unter Agomelatin vorgeschrieben?","a":"Transaminasen","w":["Lithiumspiegel","Differenzialblutbild","TSH"],"why":"Wegen des Risikos von Leberschäden werden die Leberwerte zu Beginn und im Verlauf kontrolliert."}]},{"id":"vortioxetin","name":"Vortioxetin","cls":"Antidepressivum","level":4,"target":"SERT-Hemmung plus Wirkung an mehreren 5-HT-Rezeptoren","regions":["sert","r5ht1a","raphe"],"mech":"Kombiniert SERT-Hemmung mit 5-HT1A-Agonismus, 5-HT1B-Partialagonismus und 5-HT3-, 5-HT7- und 5-HT1D-Antagonismus.","use":"Depression, auch mit kognitiven Symptomen","se":"Übelkeit, Juckreiz; weniger sexuelle Funktionsstörungen als SSRI","nut":"","mcq":[{"q":"Welcher Mechanismus gehört NICHT zu Vortioxetin?","a":"Hemmung der MAO-A","w":["SERT-Hemmung","5-HT3-Antagonismus","5-HT1A-Agonismus"],"why":"Vortioxetin ist ein multimodaler Serotonin-Modulator, kein Enzymhemmer."}]},{"id":"lithium","name":"Lithium","cls":"Stimmungsstabilisierer","level":4,"target":"Hemmung von GSK-3β und Inositol-Monophosphatase","regions":["hippocampus","dlpfc","trkb"],"mech":"Mechanismus nicht vollständig geklärt: Hemmung von IMPase und GSK-3β, neuroprotektive und plastizitätsfördernde Effekte. Senkt als einziges Mittel konsistent das Suizidrisiko.","use":"Phasenprophylaxe der bipolaren Störung, Augmentation bei Depression, Suizidprävention","se":"geringe therapeutische Breite; Tremor, Polyurie (nephrogener Diabetes insipidus), Hypothyreose, Hyperparathyreoidismus, Gewichtszunahme; Intoxikation mit Ataxie, Verwirrtheit, Krampfanfällen","nut":"Der Spiegel steigt bei Natriummangel und Dehydratation (Hitze, Durchfall, Sport) sowie mit Diuretika, ACE-Hemmern und NSAR. Salz- und Flüssigkeitszufuhr konstant halten, keine salzarmen Crash-Diäten.","mcq":[{"q":"Welche Situation erhöht den Lithiumspiegel am ehesten?","a":"Salzarme Diät plus starkes Schwitzen","w":["Viel Kaffee","Proteinreiche Kost","Gleichzeitige Gabe von Theophyllin"],"why":"Lithium wird wie Natrium proximal rückresorbiert; Natrium- und Volumenmangel steigern die Rückresorption. Koffein und Theophyllin senken den Spiegel eher."},{"q":"Welche Drüse muss unter Lithium neben der Niere regelmäßig kontrolliert werden?","a":"Schilddrüse","w":["Pankreas","Nebennierenrinde","Hypophysenhinterlappen"],"why":"Lithium hemmt die Hormonfreisetzung der Schilddrüse; Hypothyreose und Struma sind häufig."}]},{"id":"valproat","name":"Valproat und Lamotrigin","cls":"Stimmungsstabilisierer / Antiepileptikum","level":4,"target":"Natriumkanalblock; Valproat zusätzlich GABA-Anstieg und HDAC-Hemmung","regions":["interneuron","pyramidal"],"mech":"Stabilisieren neuronale Erregbarkeit. Valproat wirkt vor allem antimanisch, Lamotrigin vor allem gegen depressive Phasen der bipolaren Störung.","use":"bipolare Störung, Epilepsie","se":"Valproat: stark teratogen (Neuralrohrdefekte, Entwicklungsstörungen), Hepatotoxizität, Gewichtszunahme, Hyperammonämie. Lamotrigin: Hautausschlag bis Stevens-Johnson-Syndrom, daher langsame Eindosierung","nut":"Valproat stört den Folatstoffwechsel und macht Gewichtszunahme; bei Frauen im gebärfähigen Alter nur unter strengem Schwangerschaftsverhütungsprogramm.","mcq":[{"q":"Welche Nebenwirkung erzwingt die langsame Eindosierung von Lamotrigin?","a":"Schwere Hautreaktionen wie Stevens-Johnson-Syndrom","w":["Hyperammonämie","Agranulozytose","QT-Verlängerung"],"why":"Das Risiko steigt bei schneller Aufdosierung und in Kombination mit Valproat."}]},{"id":"typ_ap","name":"Typische Antipsychotika (z. B. Haloperidol)","cls":"Antipsychotikum","level":4,"target":"D2-Antagonismus","regions":["vta","nacc","sn","putamen","caudate","hypophyse_p"],"mech":"D2-Blockade mesolimbisch wirkt antipsychotisch; dieselbe Blockade nigrostriatal macht extrapyramidale Störungen, tuberoinfundibulär Hyperprolaktinämie, mesokortikal eher mehr Negativsymptome.","use":"Schizophrenie (Positivsymptome), akute Erregung, Delir","se":"Frühdyskinesien, Parkinsonoid, Akathisie, Spätdyskinesien; Hyperprolaktinämie; QT-Verlängerung; malignes neuroleptisches Syndrom","nut":"Hyperprolaktinämie kann Amenorrhö und Knochendichteverlust verursachen (Calcium, Vitamin D, Knochendichte im Blick).","mcq":[{"q":"Über welche Bahn erklärt sich die Hyperprolaktinämie unter D2-Antagonisten?","a":"Tuberoinfundibuläre Bahn","w":["Mesokortikale Bahn","Nigrostriatale Bahn","Mesolimbische Bahn"],"why":"Dopamin aus dem Nucleus arcuatus hemmt die laktotropen Zellen; D2-Blockade enthemmt die Prolaktinfreisetzung."}]},{"id":"atyp_ap","name":"Atypische Antipsychotika (Olanzapin, Clozapin)","cls":"Antipsychotikum","level":4,"target":"D2- plus 5-HT2A-Antagonismus","regions":["nacc","vta","r5ht2a","hypothal"],"mech":"Die 5-HT2A-Blockade enthemmt Dopamin nigrostriatal und kortikal, daher weniger extrapyramidale Störungen. Clozapin bindet nur schwach an D2 und wirkt bei therapieresistenter Schizophrenie.","use":"Schizophrenie, Manie; Clozapin bei Therapieresistenz und Suizidalität","se":"metabolisches Syndrom (Gewicht, Diabetes, Lipide), Sedierung; Clozapin zusätzlich Agranulozytose, Myokarditis, Krampfanfälle, Hypersalivation, Obstipation bis Ileus","nut":"Starke Gewichtszunahme und Insulinresistenz: Gewicht, Taillenumfang, HbA1c und Lipide überwachen, früh Ernährungsberatung. Clozapin wird über CYP1A2 abgebaut: Rauchstopp lässt den Spiegel stark steigen, Koffein erhöht ihn ebenfalls.","mcq":[{"q":"Ein Patient unter Clozapin hört stationär abrupt auf zu rauchen. Was droht?","a":"Anstieg des Clozapinspiegels bis zur Intoxikation","w":["Spiegelabfall mit psychotischem Rückfall","Hyperkaliämie","Serotoninsyndrom"],"why":"Inhaltsstoffe des Rauchs induzieren CYP1A2; fällt die Induktion weg, steigt der Spiegel binnen Tagen."},{"q":"Welche Kontrolle ist unter Clozapin engmaschig vorgeschrieben?","a":"Leukozyten und neutrophile Granulozyten","w":["Lithiumspiegel","Prolaktin","Ammoniak"],"why":"Clozapin kann eine lebensbedrohliche Agranulozytose auslösen, besonders in den ersten Monaten."}]},{"id":"aripiprazol","name":"Partialagonisten (Aripiprazol, Cariprazin)","cls":"Antipsychotikum","level":4,"target":"D2/D3-Partialagonismus","regions":["vta","nacc","caudate"],"mech":"Wirken bei hohem Dopaminspiegel antagonistisch und bei niedrigem agonistisch und stabilisieren so die Dopaminübertragung.","use":"Schizophrenie, Manie, Augmentation bei Depression","se":"Akathisie, Unruhe, selten Impulskontrollstörungen (Spielen, Essattacken); wenig Prolaktinanstieg und Gewichtszunahme","nut":"Metabolisch günstiger als Olanzapin; selten Binge-Eating als Impulskontrollstörung.","mcq":[{"q":"Welche seltene Nebenwirkung von Aripiprazol hängt mit seiner partiell agonistischen Dopaminwirkung zusammen?","a":"Impulskontrollstörungen wie Spielsucht","w":["Hyperprolaktinämie","Agranulozytose","Starke Sedierung"],"why":"Ähnlich wie bei Dopaminagonisten bei Parkinson kann die agonistische Komponente Belohnungsverhalten enthemmen."}]},{"id":"benzo","name":"Benzodiazepine (z. B. Lorazepam, Diazepam)","cls":"Anxiolytikum / Hypnotikum","level":4,"target":"Positive allosterische Modulation des GABA-A-Rezeptors","regions":["amygdala","interneuron","thalamus"],"mech":"Binden zwischen α- und γ-Untereinheit und erhöhen in Gegenwart von GABA die Öffnungsfrequenz des Chloridkanals.","use":"akute Angst und Erregung, Status epilepticus, Alkoholentzug, Prämedikation","se":"Sedierung, Sturzgefahr, Toleranz und Abhängigkeit, Atemdepression mit Alkohol oder Opioiden, Gedächtnisstörungen; Antidot Flumazenil","nut":"Alkohol verstärkt die Atemdepression; im Alter erhöhtes Sturz- und Delirrisiko.","mcq":[{"q":"Wie unterscheiden sich Benzodiazepine am GABA-A-Rezeptor von Barbituraten?","a":"Sie erhöhen die Öffnungsfrequenz, nicht die Öffnungsdauer","w":["Sie öffnen den Kanal auch ohne GABA","Sie hemmen die GABA-Wiederaufnahme","Sie hemmen die GABA-Transaminase"],"why":"Weil Benzodiazepine GABA brauchen, ist ihre Wirkung nach oben begrenzt; Barbiturate öffnen in hohen Konzentrationen direkt."}]},{"id":"ketamin","name":"Ketamin und Esketamin","cls":"Schnell wirksames Antidepressivum","level":4,"target":"NMDA-Rezeptor-Antagonismus","regions":["nmda","interneuron","pyramidal","trkb","dlpfc"],"mech":"Blockiert NMDA-Rezeptoren bevorzugt an GABAergen Interneuronen. Die Enthemmung löst einen Glutamatschub an AMPA-Rezeptoren aus, BDNF wird freigesetzt, mTOR aktiviert, und es bilden sich rasch neue Synapsen. Wirkung binnen Stunden.","use":"therapieresistente Depression (Esketamin-Nasenspray mit oralem Antidepressivum), depressive Krise mit Suizidalität","se":"Dissoziation, Blutdruckanstieg, Übelkeit, Sedierung, Missbrauchspotenzial; Anwendung nur unter Überwachung","nut":"","mcq":[{"q":"Welche Kette erklärt den schnellen antidepressiven Effekt von Ketamin am besten?","a":"NMDA-Block an Interneuronen → Glutamatschub → BDNF/mTOR","w":["SERT-Hemmung → 5-HT1A-Desensibilisierung","D2-Blockade im Striatum → Dopamin ↓","GABA-A-Modulation → Angstlösung"],"why":"Das Disinhibitionsmodell verbindet den Rezeptorblock mit rascher Synaptogenese im präfrontalen Kortex."}]},{"id":"neurosteroid","name":"Neurosteroide (Brexanolon, Zuranolon)","cls":"Antidepressivum (postpartale Depression)","level":4,"target":"Positive allosterische Modulation synaptischer und extrasynaptischer GABA-A-Rezeptoren","regions":["interneuron","amygdala"],"mech":"Analoga des Progesteronmetaboliten Allopregnanolon. Der Abfall der Neurosteroide nach der Geburt wird mit der postpartalen Depression in Verbindung gebracht.","use":"postpartale Depression (in den USA zugelassen: Brexanolon i. v. 2019, Zuranolon oral 2023)","se":"Sedierung, Schwindel, eingeschränkte Fahrtüchtigkeit","nut":"","mcq":[{"q":"Von welchem körpereigenen Stoff leitet sich Brexanolon ab?","a":"Allopregnanolon","w":["Melatonin","DHEA-Sulfat","Oxytocin"],"why":"Allopregnanolon entsteht aus Progesteron und steigt in der Schwangerschaft stark an."}]},{"id":"psilocybin","name":"Psilocybin","cls":"Psychedelikum (nur in Studien bzw. Härtefallprogrammen)","level":4,"target":"5-HT2A-Rezeptor-Agonismus (über Psilocin)","regions":["r5ht2a","pyramidal","claustrum","pcc","vmpfc","v1"],"mech":"Prodrug: wird zu Psilocin dephosphoryliert, das als Agonist an 5-HT2A-Rezeptoren der Schicht-V-Pyramidenzellen wirkt. Akut steigt die Glutamatfreisetzung, das Default-Mode-Netzwerk desintegriert, die globale Konnektivität nimmt zu; danach Hinweise auf gesteigerte Plastizität.","use":"untersucht bei therapieresistenter Depression, Depression, Angst bei Krebs, Sucht und Anorexie; nicht regulär zugelassen","se":"akute Angst, Puls- und Blutdruckanstieg, Kopfschmerz, Übelkeit; Psychoserisiko bei Disposition (in Studien Ausschluss von Psychosen und Bipolar-I); Suizidalitätssignale in Studien; nur mit psychologischer Begleitung","nut":"","mcq":[{"q":"Welcher Befund zeigt, dass 5-HT2A für die akute psychedelische Wirkung entscheidend ist?","a":"Vorbehandlung mit Ketanserin verhindert die subjektiven Effekte","w":["Naloxon hebt die Effekte auf","Die Wirkung korreliert mit der D2-Besetzung","SSRI-Vorbehandlung verstärkt die Effekte deutlich"],"why":"Der 5-HT2A-Antagonist Ketanserin blockiert in Humanstudien die psychedelische Erfahrung (Vollenweider et al., 1998)."},{"q":"Was ist Psilocybin pharmakologisch?","a":"Ein Prodrug, das zu Psilocin dephosphoryliert wird","w":["Ein direkter NMDA-Antagonist","Ein MAO-Hemmer","Ein 5-HT2A-Antagonist"],"why":"Die Phosphatgruppe wird im Körper abgespalten; Psilocin ist die aktive Substanz."}]},{"id":"mdma","name":"MDMA","cls":"Entaktogen (nur in Studien)","level":4,"target":"Umkehr des Serotonintransporters mit Monoaminfreisetzung","regions":["sert","terminal5ht","amygdala","vmpfc"],"mech":"Wird über SERT aufgenommen und kehrt den Transport um; massive Serotoninfreisetzung, dazu Noradrenalin, Dopamin und Oxytocin. Die Amygdala-Reaktivität sinkt.","use":"MDMA-gestützte Psychotherapie bei PTBS untersucht; die FDA lehnte die Zulassung 2024 vorerst ab; in Australien seit 2023 für Psychiater verschreibbar","se":"Hyperthermie, Tachykardie, Blutdruckanstieg, Hyponatriämie, Serotoninsyndrom mit anderen serotonergen Mitteln","nut":"Hyponatriämie durch ADH-Freisetzung.","mcq":[{"q":"Warum lehnte die FDA 2024 die MDMA-gestützte PTBS-Therapie vorerst ab?","a":"Zweifel an Verblindung und Datenqualität der Studien","w":["Kein Effekt im primären Endpunkt","Hohe Sterblichkeit in Phase 3","Fehlender Patentschutz"],"why":"Die Phase-3-Studien erreichten ihre Endpunkte, doch funktionelle Entblindung, Erwartungseffekte und Berichte über Fehlverhalten wogen schwer."}]},{"id":"stimulanz","name":"Stimulanzien (Methylphenidat, Lisdexamfetamin)","cls":"ADHS-Medikament","level":4,"target":"DAT/NET-Hemmung (Methylphenidat) bzw. Monoaminfreisetzung (Amphetamine)","regions":["caudate","nacc","dlpfc","lc"],"mech":"Erhöhen Dopamin und Noradrenalin im präfrontal-striatalen Netzwerk und verbessern Aufmerksamkeit und Impulskontrolle.","use":"ADHS; Lisdexamfetamin in den USA auch bei Binge-Eating-Störung","se":"Appetitminderung, Gewichtsverlust, Schlafstörung, Puls- und Blutdruckanstieg, Wachstumsverzögerung bei Kindern, Missbrauchspotenzial","nut":"Appetitminderung: Mahlzeiten vor der Einnahme oder abends einplanen, bei Kindern Gewicht und Wachstum verfolgen.","mcq":[{"q":"Für welche Essstörung ist Lisdexamfetamin in den USA zugelassen?","a":"Binge-Eating-Störung","w":["Anorexia nervosa","ARFID","Bulimia nervosa"],"why":"In RCTs sank die Zahl der Essanfalltage; in Deutschland ist es dafür nicht zugelassen."}]},{"id":"atomoxetin","name":"Atomoxetin","cls":"ADHS-Medikament","level":4,"target":"Selektive NET-Hemmung","regions":["lc","dlpfc"],"mech":"Erhöht Noradrenalin und, weil der präfrontale Kortex Dopamin vor allem über NET aufnimmt, dort auch Dopamin, nicht aber im Striatum.","use":"ADHS, wenn Stimulanzien ungeeignet sind","se":"Appetitminderung, Übelkeit, Puls- und Blutdruckanstieg, selten Leberschäden, Suizidgedanken bei Jugendlichen","nut":"","mcq":[{"q":"Warum steigt unter Atomoxetin präfrontales Dopamin, obwohl es nur NET hemmt?","a":"Im PFC wird Dopamin vorwiegend über NET aufgenommen","w":["Es hemmt zusätzlich MAO-B","Es ist ein D1-Agonist","Es blockiert D2-Autorezeptoren"],"why":"Im präfrontalen Kortex gibt es wenig DAT; NET übernimmt dort die Dopaminaufnahme."}]},{"id":"naltrexon","name":"Naltrexon und Nalmefen","cls":"Suchtmedikament","level":4,"target":"µ-Opioidrezeptor-Antagonismus","regions":["vta","nacc"],"mech":"Dämpft die opioidvermittelte Belohnung beim Trinken: Endogene Opioide enthemmen normalerweise die Dopaminneurone des VTA.","use":"Alkoholabhängigkeit (Rückfallprophylaxe; Nalmefen zur Trinkmengenreduktion), Opioidabhängigkeit nach Entzug","se":"Übelkeit, Kopfschmerz; löst bei Opioidkonsum einen Entzug aus und blockiert Opioid-Analgesie","nut":"Mit Bupropion kombiniert zur Gewichtsreduktion zugelassen.","mcq":[{"q":"Warum darf Naltrexon nicht bei aktuellem Opioidkonsum gegeben werden?","a":"Es löst ein akutes Entzugssyndrom aus","w":["Es verstärkt die Atemdepression","Es verursacht ein Serotoninsyndrom","Es führt zu Hyperkaliämie"],"why":"Der Antagonist verdrängt die Opioide vom Rezeptor."}]},{"id":"acamprosat","name":"Acamprosat","cls":"Suchtmedikament","level":4,"target":"Modulation der glutamatergen NMDA-Übertragung","regions":["nmda","nacc"],"mech":"Dämpft die glutamaterge Übererregbarkeit nach chronischem Alkoholkonsum und unterstützt die Abstinenz.","use":"Rückfallprophylaxe bei Alkoholabhängigkeit","se":"Durchfall; renal eliminiert, bei schwerer Niereninsuffizienz kontraindiziert","nut":"","mcq":[{"q":"Welche Organfunktion begrenzt den Einsatz von Acamprosat?","a":"Die Nierenfunktion","w":["Die Leberfunktion","Die Schilddrüsenfunktion","Die Knochenmarkfunktion"],"why":"Acamprosat wird unverändert über die Niere ausgeschieden und kaum in der Leber verstoffwechselt, ein Vorteil bei Lebererkrankung."}]},{"id":"opioidsubst","name":"Opioid-Substitution (Methadon, Buprenorphin)","cls":"Suchtmedikament","level":4,"target":"µ-Opioidrezeptor: Vollagonist (Methadon) bzw. Partialagonist (Buprenorphin)","regions":["vta","nacc","brainstem"],"mech":"Lang wirksame Rezeptorbesetzung verhindert Entzug und Craving und senkt Beikonsum, Infektionen und Sterblichkeit.","use":"Opioidabhängigkeit","se":"Methadon: QT-Verlängerung, Atemdepression mit Benzodiazepinen oder Alkohol; Buprenorphin kann Entzug auslösen, wenn es zu früh nach Vollagonisten gegeben wird","nut":"Obstipation und Mundtrockenheit, Zahngesundheit beachten.","mcq":[{"q":"Welche Eigenschaft macht Buprenorphin sicherer als Methadon?","a":"Ceiling-Effekt der Atemdepression","w":["Kein Abhängigkeitspotenzial","Rein peripherer Wirkort","Sehr kurze Halbwertszeit"],"why":"Als Partialagonist mit hoher Rezeptoraffinität erreicht es keine volle Atemdepression."}]},{"id":"glp1","name":"GLP-1-Rezeptoragonisten (Semaglutid u. a.)","cls":"Inkretinmimetikum (bei Sucht in Erprobung)","level":4,"target":"GLP-1-Rezeptor","regions":["hypothal","brainstem","vta","nacc"],"mech":"Wirken neben Pankreas und Magen im Hirnstamm (Area postrema, NTS), Hypothalamus und mesolimbischen System; präklinisch dämpfen sie die Dopaminantwort auf Alkohol und andere Belohnungen.","use":"zugelassen bei Typ-2-Diabetes und Adipositas; bei Alkoholkonsumstörung erste kleine RCTs mit weniger Trinken, keine Zulassung","se":"Übelkeit, Erbrechen, Obstipation, Verlust von Muskel- und Magermasse, selten Pankreatitis","nut":"Starke Appetitminderung: ausreichend Protein und Krafttraining gegen Muskelverlust, Mangelernährung und Dehydratation vermeiden.","mcq":[{"q":"Welche Aussage zu GLP-1-RA bei Alkoholkonsumstörung trifft (Stand 2025) am ehesten zu?","a":"Kleine RCTs zeigen weniger Trinken, eine Zulassung gibt es nicht","w":["In der EU für Alkoholabhängigkeit zugelassen","Große Phase-3-Studien zeigten keinen Effekt","Die Wirkung beruht auf MAO-Hemmung"],"why":"Die Evidenz stammt aus Tiermodellen, Kohortendaten und ersten kleinen RCTs; größere Studien laufen."}]},{"id":"ache","name":"Acetylcholinesterasehemmer (Donepezil, Rivastigmin, Galantamin)","cls":"Antidementivum","level":4,"target":"Hemmung der Acetylcholinesterase","regions":["nbm","hippocampus"],"mech":"Erhöhen Acetylcholin in Kortex und Hippocampus und gleichen teilweise den Verlust cholinerger Neurone des Nucleus basalis Meynert aus.","use":"leichte bis mittelschwere Alzheimer-Demenz, Demenz bei Parkinson (Rivastigmin)","se":"Übelkeit, Durchfall, Gewichtsverlust, Bradykardie und Synkopen, Albträume","nut":"Appetit- und Gewichtsverlust bei Demenz: Gewicht regelmäßig kontrollieren.","mcq":[{"q":"Welche kardiale Nebenwirkung ist typisch für AChE-Hemmer?","a":"Bradykardie mit Synkopen","w":["Tachykardie durch Sympathikusaktivierung","Hypertensive Krise","Vorhofflimmern durch Hyperthyreose"],"why":"Mehr Acetylcholin verstärkt den Vagotonus am Sinus- und AV-Knoten."}]},{"id":"antiamyloid","name":"Anti-Amyloid-Antikörper (Lecanemab, Donanemab)","cls":"Antidementivum","level":4,"target":"Amyloid-β (Protofibrillen und Plaques)","regions":["hippocampus","entorhinal","pcc"],"mech":"Entfernen Amyloid-Plaques und verlangsamten in Phase-3-Studien den kognitiven Abbau im Frühstadium moderat.","use":"frühe Alzheimer-Krankheit mit Amyloidnachweis; in der EU nur für Menschen ohne zwei ApoE4-Allele","se":"ARIA (Hirnödem, Mikroblutungen), besonders bei ApoE4-Homozygoten; Infusionsreaktionen; regelmäßige MRT-Kontrollen","nut":"","mcq":[{"q":"Warum sind ApoE4-Homozygote in der EU von Lecanemab ausgeschlossen?","a":"Deutlich höheres Risiko für ARIA (Ödeme, Blutungen)","w":["Sie haben keine Amyloid-Plaques","Der Antikörper wird bei ihnen schneller abgebaut","Höheres Risiko für Agranulozytose"],"why":"In den Zulassungsstudien traten ARIA bei zwei ApoE4-Allelen am häufigsten und schwersten auf."}]},{"id":"levodopa","name":"Levodopa (mit Decarboxylasehemmer)","cls":"Parkinsonmedikament","level":4,"target":"Dopaminvorstufe","regions":["sn","putamen","caudate"],"mech":"Überwindet die Blut-Hirn-Schranke und wird in den verbliebenen nigrostriatalen Neuronen zu Dopamin. Carbidopa oder Benserazid verhindern die Umwandlung außerhalb des Gehirns.","use":"Parkinson","se":"Wirkfluktuationen, Dyskinesien, Übelkeit, Orthostase, Halluzinationen","nut":"Große neutrale Aminosäuren aus Eiweiß konkurrieren mit Levodopa um den Transporter LAT1 in Darm und Blut-Hirn-Schranke: Einnahme mit Abstand zu eiweißreichen Mahlzeiten, bei Fluktuationen Eiweiß auf den Abend verlagern.","mcq":[{"q":"Warum nimmt man Levodopa mit Abstand zu eiweißreichen Mahlzeiten?","a":"Aminosäuren konkurrieren um den Transporter LAT1","w":["Eiweiß bindet Levodopa irreversibel im Magen","Eiweiß induziert die Dopadecarboxylase","Eiweiß steigert die renale Ausscheidung"],"why":"Levodopa ist selbst eine große neutrale Aminosäure und nutzt denselben Transporter."}]},{"id":"ekt","name":"Elektrokonvulsionstherapie (EKT)","cls":"Hirnstimulation","level":4,"target":"Generalisierter Krampfanfall in Kurznarkose","regions":["hippocampus","sgacc","dlpfc"],"mech":"Mechanismus nicht vollständig geklärt: Neuroplastizität (Hippocampusvolumen nimmt zu), Normalisierung der HPA-Achse, veränderte Netzwerkkonnektivität.","use":"schwere, therapieresistente oder psychotische Depression, Katatonie, akute Suizidalität","se":"vorübergehende Gedächtnisstörungen, Kopfschmerz, Narkoserisiko","nut":"","mcq":[{"q":"Bei welchem Zustandsbild gilt die EKT als besonders wirksam?","a":"Katatonie","w":["Leichte depressive Episode","Zwangsstörung","Generalisierte Angststörung"],"why":"Bei Katatonie und psychotischer Depression sind die Ansprechraten hoch."}]},{"id":"rtms","name":"Repetitive transkranielle Magnetstimulation (rTMS)","cls":"Hirnstimulation","level":4,"target":"Stimulation des linken dlPFC","regions":["dlpfc","sgacc"],"mech":"Hochfrequente Stimulation des linken dlPFC. Die Wirksamkeit hängt mit der funktionellen Antikorrelation zwischen dem Stimulationsort und dem sgACC zusammen; beschleunigte Protokolle wählen das Ziel per fMRT.","use":"therapieresistente Depression","se":"Kopfschmerz, Missempfindungen der Kopfhaut, selten Krampfanfall","nut":"","mcq":[{"q":"Welche funktionelle Beziehung nutzt man, um das rTMS-Ziel im dlPFC zu optimieren?","a":"Antikorrelation des Zielpunkts mit dem sgACC","w":["Maximale Korrelation mit der Amygdala","Nähe zum motorischen Handareal","Höchste 5-HT2A-Rezeptordichte"],"why":"Punkte mit stärkerer Antikorrelation zum sgACC sagten in Studien besseres Ansprechen voraus (Fox et al., 2012)."}]},{"id":"dbs","name":"Tiefe Hirnstimulation (DBS)","cls":"Hirnstimulation","level":4,"target":"Implantierte Elektroden, z. B. in Nucleus subthalamicus, sgACC oder ventraler Kapsel","regions":["sgacc","nacc","capsula"],"mech":"Moduliert pathologische Netzwerkaktivität. Bei Parkinson etabliert (Nucleus subthalamicus, Globus pallidus internus), bei Zwangsstörung im Einsatz, bei Depression (sgACC, Mayberg 2005) experimentell.","use":"Parkinson, Tremor, Dystonie, Zwangsstörung; Depression in Studien","se":"Operationsrisiken (Blutung, Infektion), stimulationsbedingte Stimmungs- oder Verhaltensänderungen","nut":"Nach Stimulation des Nucleus subthalamicus bei Parkinson häufig Gewichtszunahme.","mcq":[{"q":"Welche Zielregion wählte Mayberg 2005 für die DBS bei therapieresistenter Depression?","a":"Subgenualer cingulärer Kortex (BA 25)","w":["Nucleus subthalamicus","Hippocampus","Locus coeruleus"],"why":"Die Region war in der Bildgebung bei Depression überaktiv und normalisierte sich unter erfolgreicher Therapie."}]},{"id":"vns","name":"Vagusnervstimulation","cls":"Hirnstimulation","level":4,"target":"Stimulation des linken N. vagus","regions":["brainstem","lc","raphe"],"mech":"Afferente Vagussignale erreichen über den Nucleus tractus solitarii den Locus coeruleus und die Raphe-Kerne.","use":"pharmakoresistente Epilepsie; in den USA auch therapieresistente Depression (begrenzte Evidenz)","se":"Heiserkeit, Husten, Atemnot während der Stimulation","nut":"","mcq":[{"q":"Über welchen Kern erreichen vagale Afferenzen das Gehirn zuerst?","a":"Nucleus tractus solitarii","w":["Nucleus ambiguus","Nucleus dorsalis nervi vagi","Nucleus arcuatus"],"why":"Der NTS ist die viszerosensible Umschaltstation; Nucleus ambiguus und dorsaler Vaguskern sind efferent."}]}],"cards":[{"id":"m_mono","track":"model","level":3,"title":"Monoamin-Hypothese","text":"Depression als Mangel an Serotonin und Noradrenalin: gestützt durch die Wirkung von MAO-Hemmern und Trizyklika. Dagegen spricht, dass der Transporterblock sofort wirkt, die Stimmung sich aber erst nach Wochen bessert, und eine Umbrella-Review fand keine konsistente Evidenz für erniedrigtes Serotonin.","facts":["Tryptophan-Depletion senkt bei Gesunden kaum die Stimmung, löst aber bei remittierten Patienten Rückfallsymptome aus","Heute eher: Monoamine als Modulatoren von Plastizität und Netzwerken"],"regions":["raphe","lc"],"src":"Moncrieff et al., Mol Psychiatry 2022; Ruhé et al., Mol Psychiatry 2007","mcq":[{"q":"Welcher Befund spricht am stärksten gegen eine reine Serotoninmangel-Erklärung der Depression?","a":"Der SERT-Block wirkt sofort, die Stimmung bessert sich erst nach Wochen","w":["SSRI wirken besser als Placebo","MAO-Hemmer wirken antidepressiv","Tryptophan-Depletion löst bei Remittierten Rückfallsymptome aus"],"why":"Die zeitliche Lücke deutet auf nachgeschaltete Anpassung und Plastizität statt auf einfachen Transmittermangel."}]},{"id":"m_bdnf","track":"model","level":3,"title":"Neuroplastizitäts- und BDNF-Hypothese","text":"Chronischer Stress und Depression gehen mit weniger Dendritendornen in PFC und Hippocampus, reduzierter Neurogenese und niedrigerem BDNF einher. Wirksame Therapien wie Antidepressiva, Ketamin, EKT und Bewegung fördern Plastizität.","facts":["Serum-BDNF ist bei Depression im Mittel erniedrigt, als Einzelmarker aber unspezifisch","Antidepressiva binden laut Casarotto 2021 direkt an den BDNF-Rezeptor TrkB"],"regions":["hippocampus","dlpfc","trkb","apical"],"src":"Duman & Monteggia, Biol Psychiatry 2006; Casarotto et al., Cell 2021","mcq":[{"q":"Welche Aussage zu BDNF bei Depression trifft zu?","a":"Im Serum im Mittel erniedrigt, als Einzelmarker aber unspezifisch","w":["Diagnostisch spezifisch für Depression","Unter wirksamer Therapie typischerweise weiter fallend","Nur im Liquor messbar, nicht im Serum"],"why":"Erniedrigtes BDNF findet man auch bei anderen Erkrankungen; es steigt unter Therapie eher an."}]},{"id":"m_hpa","track":"model","level":3,"title":"Stressachse und Cortisol","text":"Bei einem Teil der Depressiven, besonders bei melancholischer oder psychotischer Depression, ist die HPA-Achse überaktiv: mehr CRH und Cortisol, gestörte Rückkopplung. Dauerhaft hohes Cortisol schädigt Hippocampus-Neurone, frühe Traumatisierung prägt die Achse langfristig.","facts":["Im Dexamethason-Hemmtest wird Cortisol bei vielen schwer Depressiven nicht ausreichend supprimiert","Glukokortikoidrezeptoren sind eher weniger empfindlich (Glukokortikoidresistenz)"],"regions":["hypothal","hypophyse_p","hippocampus","amygdala"],"src":"Pariante & Lightman, Trends Neurosci 2008","mcq":[{"q":"Welcher Befund passt zur HPA-Überaktivität bei Depression?","a":"Fehlende Cortisolsuppression nach Dexamethason","w":["Erniedrigtes CRH im Liquor","Gesteigerte Empfindlichkeit der Glukokortikoidrezeptoren","Regelhaft niedriges Morgencortisol"],"why":"Die negative Rückkopplung über Glukokortikoidrezeptoren ist abgeschwächt."}]},{"id":"m_inflam","track":"model","level":3,"title":"Entzündungshypothese","text":"Etwa ein Viertel der Depressiven hat ein niedriggradig erhöhtes CRP, IL-6 und TNF-α sind im Mittel erhöht. Zytokine lenken Tryptophan über IDO in den Kynurenin-Weg und dämpfen Dopamin im Belohnungssystem. Erhöhte Entzündungswerte gehen mit schlechterem Ansprechen auf klassische Antidepressiva einher.","facts":["In einer RCT half der TNF-Blocker Infliximab nur Patienten mit hohem Ausgangs-CRP","Interferon-α-Therapie löst bei einem erheblichen Teil der Behandelten Depressionen aus"],"regions":["nacc","dacc","insula","microglia"],"src":"Osimo et al., Psychol Med 2019; Raison et al., JAMA Psychiatry 2013","mcq":[{"q":"Welche Patienten profitierten in der Infliximab-Studie (Raison 2013)?","a":"Nur jene mit hohem Ausgangs-CRP","w":["Alle Patienten gleichermaßen","Nur jene mit niedrigem CRP","Nur jene mit gleichzeitiger Angststörung"],"why":"Bei niedrigem CRP schnitt Infliximab tendenziell sogar schlechter ab als Placebo."}]},{"id":"m_glu","track":"model","level":3,"title":"Glutamat und Ketamin","text":"Die rasche Wirkung von Ketamin lenkte den Blick auf Glutamat: NMDA-Block an Interneuronen, Glutamatschub, AMPA-Aktivierung, BDNF-Freisetzung und mTOR. Im Tiermodell entstehen binnen 24 Stunden neue Dornen im präfrontalen Kortex.","facts":["Wirkung nach Stunden, meist für Tage","Esketamin ist in der EU bei therapieresistenter Depression zugelassen"],"regions":["nmda","interneuron","dlpfc","trkb"],"src":"Berman et al., Biol Psychiatry 2000; Li et al., Science 2010","mcq":[{"q":"Was hebt im Tiermodell die antidepressive Wirkung von Ketamin auf?","a":"Ein AMPA-Rezeptor-Antagonist","w":["Ein 5-HT2A-Antagonist","Ein MAO-Hemmer","Ein Benzodiazepin"],"why":"Die Wirkung braucht die AMPA-vermittelte Aktivierung nach dem Glutamatschub (Maeng et al., 2008)."}]},{"id":"m_net","track":"model","level":3,"title":"Netzwerke und Grübeln","text":"Bei Depression ist das Default-Mode-Netzwerk stärker mit dem subgenualen ACC gekoppelt, was mit Grübeln in Verbindung gebracht wird. Das exekutive Netzwerk um den dlPFC reguliert Emotionen schwächer.","facts":["sgACC-Überaktivität normalisiert sich unter erfolgreicher Therapie","Die Antikorrelation dlPFC–sgACC sagt das Ansprechen auf rTMS vorher"],"regions":["vmpfc","pcc","sgacc","dlpfc"],"src":"Hamilton et al., Biol Psychiatry 2015; Fox et al., Biol Psychiatry 2012","mcq":[{"q":"Welche Kopplung wird bei Depression mit Grübeln verbunden?","a":"Default-Mode-Netzwerk mit dem subgenualen ACC","w":["Exekutives Netzwerk mit dem visuellen Kortex","Salienznetzwerk mit dem Kleinhirn","Motorkortex mit dem Putamen"],"why":"Die verstärkte Einbindung des sgACC in das DMN korreliert mit der Grübelneigung."}]},{"id":"m_reward","track":"model","level":3,"title":"Belohnungssystem und Anhedonie","text":"Anhedonie geht mit verminderter Aktivität im ventralen Striatum bei Belohnungserwartung einher; Stress und Entzündung dämpfen mesolimbisches Dopamin. Klassische SSRI bessern Anhedonie oft unzureichend.","facts":["Ausgeprägte Anhedonie sagt schlechteres Ansprechen auf SSRI vorher","Wollen (Dopamin) und Mögen (Opioide) sind getrennte Komponenten"],"regions":["vta","nacc","vmpfc"],"src":"Pizzagalli, Annu Rev Clin Psychol 2014","mcq":[{"q":"Welche Komponente der Belohnung wird vor allem dopaminerg vermittelt?","a":"Das Wollen (Anreizmotivation)","w":["Das Mögen (hedonischer Genuss)","Das Sättigungsgefühl","Die Gedächtniskonsolidierung"],"why":"Nach Berridge vermittelt Dopamin den Anreiz, opioide Hotspots den Genuss."}]},{"id":"m_gut","track":"model","level":3,"title":"Ernährung, Darm und Depression","text":"Mediterrane Kostmuster gehen in Kohorten mit weniger Depression einher. In der SMILES-Studie (n=67) erreichten unter Ernährungsberatung 32 % eine Remission gegenüber 8 % unter sozialer Unterstützung; die Studie war klein und nicht verblindet. Omega-3 mit hohem EPA-Anteil zeigt in Meta-Analysen kleine Effekte.","facts":["Mikrobiom-Befunde bei Depression sind überwiegend korrelativ","Darm-Hirn-Wege: Vagus, Zytokine, Tryptophan-Metabolite, kurzkettige Fettsäuren"],"regions":["hypothal","brainstem","microglia"],"src":"Jacka et al., BMC Med 2017; Liao et al., Transl Psychiatry 2019","mcq":[{"q":"Welche Schwäche hat die SMILES-Studie am deutlichsten?","a":"Kleine Stichprobe ohne Verblindung","w":["Keine Randomisierung","Nur gesunde Teilnehmende","Kein klinischer Endpunkt"],"why":"Teilnehmende wussten, welche Intervention sie erhielten; Erwartungseffekte sind möglich."}]},{"id":"p_2a","track":"mech","level":3,"title":"5-HT2A an Schicht-V-Pyramidenzellen","text":"Psilocin aktiviert 5-HT2A-Rezeptoren, die vor allem auf apikalen Dendriten von Schicht-V-Pyramidenzellen sitzen, besonders dicht in Assoziations- und visuellem Kortex. Das steigert die Erregbarkeit und die Glutamatfreisetzung.","facts":["Der 5-HT2A-Antagonist Ketanserin hebt die subjektiven Effekte auf","In der PET korreliert die 5-HT2A-Besetzung mit der Intensität der Erfahrung"],"regions":["r5ht2a","pyramidal","apical","v1","ppc"],"src":"Vollenweider et al., NeuroReport 1998; Madsen et al., Neuropsychopharmacology 2019","mcq":[{"q":"Was zeigten Madsen et al. 2019 mit PET?","a":"Die 5-HT2A-Besetzung korreliert mit der Intensität der Erfahrung","w":["Psilocin bindet vorwiegend an D2-Rezeptoren","Die Besetzung bleibt nach einem Tag unverändert hoch","Spiegel und Erleben hängen nicht zusammen"],"why":"Plasmaspiegel von Psilocin, Rezeptorbesetzung und subjektive Intensität verliefen parallel."}]},{"id":"p_dmn","track":"mech","level":3,"title":"Default-Mode-Netzwerk und Konnektivität","text":"Unter Psilocybin sinkt die Integrität des Default-Mode-Netzwerks, vor allem im PCC und mPFC; Netzwerke werden weniger voneinander getrennt, die globale Konnektivität steigt. Das korreliert mit dem Erleben von Ich-Auflösung.","facts":["Erstbeschrieben mit fMRT (Carhart-Harris 2012)","Nach Therapie bei Depression korrelierte geringere Netzwerk-Modularität mit der Besserung (Daws 2022)"],"regions":["pcc","vmpfc","precuneus"],"src":"Carhart-Harris et al., PNAS 2012; Daws et al., Nat Med 2022","mcq":[{"q":"Welche Region zeigte in der ersten fMRT-Studie unter Psilocybin die deutlichste Abnahme?","a":"Posteriorer cingulärer Kortex","w":["Primäre Sehrinde","Kleinhirn","Nucleus accumbens"],"why":"PCC und mPFC als DMN-Knoten zeigten weniger Blutfluss und Kopplung."}]},{"id":"p_rebus","track":"mech","level":4,"title":"REBUS und thalamischer Filter","text":"REBUS (relaxed beliefs under psychedelics): Psychedelika lockern stark gewichtete Vorannahmen, sodass Information von unten mehr Einfluss bekommt. Das CSTC-Modell sieht ergänzend eine geschwächte thalamische Filterung, sodass mehr Reize den Kortex erreichen. Beides sind Rahmenmodelle, keine bewiesenen Mechanismen.","facts":["REBUS verbindet Predictive Processing mit Netzwerkbefunden","CSTC = kortiko-striato-thalamo-kortikale Schleife"],"regions":["thalamus","pcc","claustrum"],"src":"Carhart-Harris & Friston, Pharmacol Rev 2019; Vollenweider & Geyer, Brain Res Bull 2001","mcq":[{"q":"Was beschreibt das REBUS-Modell?","a":"Gelockerte Vorannahmen, mehr Einfluss von Bottom-up-Information","w":["Verstärkte thalamische Filterung","Selektive Blockade von 5-HT1A","Zunehmende Modularität der Netzwerke"],"why":"REBUS: Die Präzision hoher Priors sinkt, Vorhersagefehler von unten wiegen stärker."}]},{"id":"p_plast","track":"mech","level":4,"title":"Plastizität nach der Sitzung","text":"Psychedelika fördern im Tiermodell rasch Dendritenwachstum und Synapsenbildung; eine einzelne Gabe erhöhte bei Mäusen die Spine-Dichte im mPFC über Wochen. Ob dafür 5-HT2A nötig ist, ist umstritten: Moliner et al. beschreiben eine direkte Bindung an TrkB.","facts":["Kritische-Periode-Hypothese: Psychedelika öffnen ein Lernfenster für soziale Belohnung (Nardou 2023)","Wie viel davon beim Menschen klinisch zählt, ist offen"],"regions":["apical","trkb","pyramidal"],"src":"Ly et al., Cell Rep 2018; Shao et al., Neuron 2021; Moliner et al., Nat Neurosci 2023; Nardou et al., Nature 2023","mcq":[{"q":"Was beschrieben Moliner et al. 2023?","a":"Psychedelika binden direkt an TrkB und fördern so Plastizität","w":["Psilocybin wirkt ausschließlich über 5-HT1A","Psychedelika senken BDNF dauerhaft","Ohne TrkB ist die Wirkung verstärkt"],"why":"Die Autoren sehen TrkB als möglichen gemeinsamen Angriffspunkt von Antidepressiva und Psychedelika."}]},{"id":"p_exp","track":"mech","level":4,"title":"Erfahrung oder Pharmakologie?","text":"Offen ist, ob die subjektive Erfahrung für die Wirkung nötig ist. Die Intensität mystischer Erfahrung korreliert in Studien mit dem Ansprechen; nicht-halluzinogene Analoga wirken im Tiermodell antidepressiv. Beim Menschen ist die Frage ungeklärt.","facts":["Korrelation ist kein Beweis: Erwartung, Erleben und Begleitung sind verwoben"],"regions":["pcc","claustrum"],"src":"Olson, ACS Pharmacol Transl Sci 2021","mcq":[{"q":"Welcher Befund spricht dafür, dass die Erfahrung nicht zwingend nötig sein könnte?","a":"Nicht-halluzinogene Analoga wirken im Tiermodell antidepressiv","w":["Mystische Erfahrung korreliert mit dem Ansprechen","Ketanserin hebt die Erfahrung auf","Höhere Dosen wirken stärker als niedrige"],"why":"Wenn Plastizität ohne Erleben entsteht, wäre die Erfahrung eher Begleiterscheinung; beim Menschen fehlt der Nachweis."}]},{"id":"s_davis","track":"study","level":4,"title":"Davis et al. 2021: Warteliste","text":"RCT mit sofortiger vs. um acht Wochen verzögerter Behandlung bei Depression (n=24 ausgewertet), zwei Sitzungen mit psychologischer Begleitung. Nach vier Wochen 71 % Response und 54 % Remission (GRID-HAMD); Effektstärke gegenüber Warteliste Cohen’s d über 2.","facts":["Wartelisten-Kontrolle ohne Verblindung bläht Effektstärken auf","Kleine Stichprobe, keine Placebo-Kontrolle"],"regions":[],"src":"Davis et al., JAMA Psychiatry 2021","mcq":[{"q":"Warum ist Cohen’s d über 2 in Davis 2021 nicht mit SSRI-Effekten vergleichbar?","a":"Kontrolle war eine Warteliste ohne Placebo und Verblindung","w":["Der Endpunkt war eine Selbstbeurteilung","Es wurden nur Gesunde eingeschlossen","Der Endpunkt lag erst nach einem Jahr"],"why":"Gegen Warteliste fehlen Erwartungs- und Zuwendungseffekte in der Kontrolle."}]},{"id":"s_ch21","track":"study","level":4,"title":"Carhart-Harris et al. 2021: vs. Escitalopram","text":"Doppelblinde Phase-2-Studie (n=59) bei mittelschwerer bis schwerer Depression. Primärer Endpunkt (QIDS-SR-16 nach 6 Wochen): −8,0 vs. −6,0 Punkte, nicht signifikant. Sekundär Remission 57 % vs. 28 % und Response etwa 70 % vs. 48 %, jedoch ohne Korrektur für multiples Testen.","facts":["Positive Sekundärendpunkte heben einen negativen Primärendpunkt nicht auf","Der Escitalopram-Arm erhielt eine sehr niedrige Psilocybin-Kontrolldosis"],"regions":[],"src":"Carhart-Harris et al., NEJM 2021","mcq":[{"q":"Wie fasst man Carhart-Harris 2021 korrekt zusammen?","a":"Primärendpunkt verfehlt, Sekundärendpunkte zugunsten Psilocybin","w":["Psilocybin im Primärendpunkt überlegen","Escitalopram im Primärendpunkt überlegen","In keinem Endpunkt ein Unterschied"],"why":"Die Sekundärendpunkte waren nicht für multiples Testen korrigiert und gelten als hypothesengenerierend."}]},{"id":"s_good22","track":"study","level":4,"title":"COMP360 Phase 2b (Goodwin 2022)","text":"Drei Dosisgruppen (hoch, mittel, sehr niedrig als Kontrolle) bei therapieresistenter Depression (n=233), Einzelgabe mit Begleitung. MADRS nach 3 Wochen −12,0 vs. −7,9 vs. −5,4; Differenz hoch vs. Kontrolle −6,6 Punkte (95 %-KI −10,2 bis −2,9). Remission nach 3 Wochen 29 % vs. 9 % vs. 8 %.","facts":["Anhaltende Response nach 12 Wochen nur bei einer Minderheit","In den aktiven Gruppen mehr Suizidgedanken und Selbstverletzung als unter Kontrolle"],"regions":[],"src":"Goodwin et al., NEJM 2022","mcq":[{"q":"Welche Kontrollbedingung nutzte die COMP360-Phase-2b-Studie?","a":"Eine sehr niedrige Psilocybin-Dosis","w":["Niacin als aktives Placebo","Escitalopram","Warteliste"],"why":"Die Kontrolldosis soll die Erwartung angleichen, ohne relevant zu wirken."},{"q":"Wie hoch war die Remissionsrate nach 3 Wochen in der höchsten Dosisgruppe?","a":"29 %","w":["54 %","9 %","71 %"],"why":"29 % vs. 9 % (mittlere) vs. 8 % (Kontrolldosis)."}]},{"id":"s_raison","track":"study","level":4,"title":"Raison et al. 2023: Depression ohne Therapieresistenz","text":"Phase-2-RCT (n=104), Einzelgabe vs. Niacin als aktives Placebo, beide mit Begleitung. MADRS-Differenz −12,3 Punkte an Tag 43 (95 %-KI −17,5 bis −7,2), schon an Tag 8 −12,0; keine schweren unerwünschten Ereignisse.","facts":["Niacin erzeugt Flush und soll Entblindung erschweren, gelingt aber nur begrenzt","Größere Differenz als in TRD-Studien: andere Population"],"regions":[],"src":"Raison et al., JAMA 2023","mcq":[{"q":"Warum wurde in Raison 2023 Niacin als Vergleich gewählt?","a":"Als aktives Placebo mit spürbaren Körpereffekten","w":["Weil Niacin selbst antidepressiv wirkt","Um Flush-Reaktionen zu verhindern","Als Lipidsenker für einen Sekundärendpunkt"],"why":"Spürbare Effekte sollen die Zuteilung schwerer erkennbar machen."}]},{"id":"s_comp005","track":"study","level":4,"title":"COMP005 (Phase 3)","text":"Einzelgabe vs. Placebo bei therapieresistenter Depression (n=258). MADRS-Differenz nach 6 Wochen −3,6 Punkte (95 %-KI −5,7 bis −1,5; p<0,001). Bisher nur als Firmenmitteilung veröffentlicht.","facts":["Deutlich kleinere Differenz als in Phase 2b","Das Unternehmen definiert Response als ≥ 25 % MADRS-Reduktion statt der üblichen ≥ 50 %"],"regions":[],"src":"Compass Pathways, Mitteilungen Juni 2025 und Februar 2026","mcq":[{"q":"Was ist an den Response-Angaben der COMP360-Phase-3-Mitteilungen auffällig?","a":"Response als ≥ 25 % statt der üblichen ≥ 50 % MADRS-Reduktion","w":["Response nur per Selbstbeurteilung gemessen","Response ohne Kontrollgruppe berichtet","Response erst nach zwei Jahren gemessen"],"why":"Eine weichere Schwelle lässt Response-Raten höher erscheinen; für Vergleiche immer die Definition prüfen."}]},{"id":"s_comp006","track":"study","level":4,"title":"COMP006 (Phase 3)","text":"Zwei Gaben im Abstand von drei Wochen, hohe vs. mittlere vs. sehr niedrige Dosis (n=581). MADRS-Differenz hoch vs. Kontrolle nach 6 Wochen −3,8 Punkte (95 %-KI −5,8 bis −1,8; p<0,001); laut Unternehmen hielt das Ansprechen bis Woche 26 an, ohne Ungleichgewicht bei Suizidalität.","facts":["Bisher nur Firmenmitteilungen, nicht peer-reviewed","Phase 3 insgesamt: statistisch klar, klinisch moderat (knapp 4 MADRS-Punkte)"],"regions":[],"src":"Compass Pathways, Mitteilungen Februar und Juli 2026","mcq":[{"q":"Welche Größenordnung hatte die MADRS-Differenz in beiden COMP360-Phase-3-Studien nach 6 Wochen?","a":"Knapp 4 Punkte","w":["Etwa 12 Punkte","Etwa 7 Punkte","Unter 1 Punkt"],"why":"COMP005 −3,6 und COMP006 −3,8 Punkte gegenüber Placebo bzw. Kontrolldosis."}]},{"id":"s_meta","track":"study","level":4,"title":"Metaxa & Clarke 2024: Meta-Analyse","text":"Neun RCTs (436 Teilnehmende): Hedges’ g = 0,66 (95 %-KI 0,46 bis 0,86) zugunsten Psilocybin; Response RR 2,17, Remission RR 2,96. Größere Effekte bei sekundärer Depression (z. B. bei Krebserkrankung) als bei primärer.","facts":["Alle Studien mit moderatem Verzerrungsrisiko","Teilnehmende erkannten ihre Zuteilung in 70–85 % der Fälle"],"regions":[],"src":"Metaxa & Clarke, BMJ 2024","mcq":[{"q":"Welches gepoolte Hedges’ g fand die BMJ-Meta-Analyse 2024?","a":"0,66","w":["0,18","1,64","2,6"],"why":"Ein mittlerer Effekt, bei moderatem Verzerrungsrisiko und eingeschränkter Verblindung."}]},{"id":"s_safety","track":"safety","level":4,"title":"Sicherheit in den Studien","text":"Häufig am Sitzungstag: Kopfschmerz, Übelkeit, Angst, emotionale Labilität, Blutdruckanstieg; meist binnen Tagen abgeklungen. Selten schwere Reaktionen. In Phase 2b mehr Suizidgedanken in den aktiven Gruppen, in Phase 3 laut Sicherheitskomitee kein Ungleichgewicht. Psychose und Bipolar-I sind in Studien ausgeschlossen.","facts":["EPIsoDE: zwei schwere Reaktionen (starker Blutdruckanstieg, anhaltende Wahrnehmungsstörung)","Begleitung vor, während und nach der Sitzung ist Teil der Behandlung"],"regions":[],"src":"Goodwin et al., NEJM 2022; Mertens et al., JAMA Psychiatry 2026; Compass Pathways 2026","mcq":[{"q":"Welche Gruppe wird in Psilocybin-Studien typischerweise ausgeschlossen?","a":"Menschen mit Psychose oder Bipolar-I in der Vorgeschichte","w":["Menschen über 40 Jahre","Menschen mit früherer SSRI-Therapie","Menschen mit Angststörung als Komorbidität"],"why":"Psychedelika können bei Disposition psychotische oder manische Episoden auslösen."}]},{"id":"me_blind","track":"method","level":4,"title":"Funktionelle Entblindung","text":"Bei Psychedelika erkennen die meisten Teilnehmenden und Begleitenden, wer die Substanz erhielt. Das untergräbt die Verblindung und kann Effekte über Erwartung aufblähen, besonders bei Selbstbeurteilungsskalen.","facts":["Gegenmittel: aktive Placebos, Kontrolldosen, unabhängige verblindete Rater, Erwartung messen","In der BMJ-Meta-Analyse erkannten Teilnehmende ihre Zuteilung in 70–85 %"],"regions":[],"src":"Muthukumaraswamy et al., Expert Rev Clin Pharmacol 2021; Metaxa & Clarke, BMJ 2024","mcq":[{"q":"Welche Maßnahme schützt am besten gegen Erwartungseffekte beim Rating?","a":"Verblindete externe Rater ohne Kontakt zur Sitzung","w":["Selbstbeurteilung statt Fremdrating","Längere Sitzungen","Höhere Dosis im Verum-Arm"],"why":"Externe Rater wissen weniger über die Zuteilung als Begleitende oder Teilnehmende."}]},{"id":"me_ctrl","track":"method","level":4,"title":"Kontrollbedingungen im Vergleich","text":"Warteliste, inaktives Placebo, aktives Placebo (z. B. Niacin), niedrige Kontrolldosis, aktiver Vergleich (z. B. Escitalopram): Je strenger die Kontrolle, desto kleiner meist die Effektgröße.","facts":["Davis 2021 (Warteliste): d über 2","COMP360 Phase 3 (Placebo bzw. Kontrolldosis): knapp 4 MADRS-Punkte"],"regions":[],"src":"Metaxa & Clarke, BMJ 2024","mcq":[{"q":"Welche Kontrolle erzeugt typischerweise die größten Effektstärken?","a":"Warteliste","w":["Aktives Placebo","Niedrige Kontrolldosis","Aktiver Vergleich mit Escitalopram"],"why":"Ohne Placebo fehlen Erwartung und Zuwendung in der Kontrollgruppe."}]},{"id":"me_resp","track":"method","level":4,"title":"Response, Remission, Effektgröße","text":"Response heißt meist ≥ 50 % Skalenreduktion, Remission ein Wert unter einer Schwelle (z. B. MADRS ≤ 10). Effektgrößen hängen von Kontrolle und Streuung ab; klassische Antidepressiva liegen gegenüber Placebo meta-analytisch bei etwa g = 0,3.","facts":["Cipriani 2018: alle 21 untersuchten Antidepressiva wirksamer als Placebo, mit kleinen Effektgrößen","Firmen definieren eine klinisch bedeutsame Response teils abweichend (≥ 25 %)"],"regions":[],"src":"Cipriani et al., Lancet 2018","mcq":[{"q":"Wie groß ist der mittlere Effekt klassischer Antidepressiva gegenüber Placebo etwa?","a":"g ≈ 0,3","w":["g ≈ 1,0","g ≈ 0,05","g ≈ 2,0"],"why":"Klein, aber konsistent; Vergleiche mit Psilocybin hinken wegen unterschiedlicher Kontrollen und Verblindung."}]},{"id":"me_press","track":"method","level":4,"title":"Pressemitteilung vs. Publikation","text":"Topline-Daten aus Firmenmitteilungen nennen oft nur ausgewählte Endpunkte, ohne Effektgrößen und vollständige Sicherheitsdaten. Erst die peer-reviewte Publikation zeigt Protokoll, Analysepopulation und alle Endpunkte.","facts":["Stand der Recherche (November 2026): COMP005 und COMP006 nur als Mitteilungen gefunden","Für Reviews: Quelle immer als Pressemitteilung kennzeichnen"],"regions":[],"src":"Compass Pathways 2025–2026","mcq":[{"q":"Was fehlt in Topline-Mitteilungen typischerweise?","a":"Vollständige Endpunkte, Effektgrößen und Analysedetails","w":["Der primäre Endpunkt","Die Fallzahl","Der Name der Prüfsubstanz"],"why":"Der primäre Endpunkt wird meist genannt, Details folgen erst in der Publikation."}]},{"id":"r_status","track":"reg","level":4,"title":"Zulassungsstand (November 2026)","text":"USA: Für COMP360 läuft laut Unternehmen ein rollierender Zulassungsantrag, Abschluss für Q4 2026 geplant; Markteinführung frühestens 2027 nach Zulassung und DEA-Neueinstufung. Australien: seit 2023 Verschreibung durch autorisierte Psychiater bei therapieresistenter Depression. Deutschland und EU: keine Zulassung, nur Studien und das Härtefallprogramm.","facts":["COMP360 hat in den USA Breakthrough-Status","Das erste EU-Härtefallprogramm läuft seit 2025 am ZI Mannheim"],"regions":[],"src":"Compass Pathways, Juli 2026; TGA Australien 2023; ZI Mannheim 2025","mcq":[{"q":"Wo ist Psilocybin bei therapieresistenter Depression seit 2023 durch autorisierte Psychiater verschreibbar?","a":"Australien","w":["Deutschland","Kanada als reguläre Zulassung","Vereinigtes Königreich"],"why":"Die australische TGA erlaubt dies seit Juli 2023."}]},{"id":"pr_episode","track":"prak","level":1,"title":"EPIsoDE (JAMA Psychiatry 2026)","text":"Phase-2b-Studie am ZI Mannheim und an der Charité (n=144, therapieresistente Depression): hohe Dosis vs. niedrige Kontrolldosis vs. Placebo, mit Vorbereitung, zwei Therapeuten in der Sitzung und Integration. Primärer Endpunkt (Response nach 6 Wochen) verfehlt; nach einer Woche signifikant mehr Response; nach 6 Wochen HAMD-17 sekundär 4,6 Punkte stärker gesenkt als unter Placebo.","facts":["Cross-over-Sequenzen: alle erhielten mindestens einmal die hohe Dosis; nach 12 Wochen keine Gruppenunterschiede mehr","Zwei schwere Reaktionen: starker Blutdruckanstieg, anhaltende Wahrnehmungsstörung"],"regions":[],"src":"Mertens, Koslowski, Betzler et al., JAMA Psychiatry 2026","mcq":[{"q":"Was zeigte EPIsoDE?","a":"Primärer Endpunkt nach 6 Wochen verfehlt, frühe Response signifikant","w":["Primärer Endpunkt klar erreicht, kein früher Effekt","Placebo war der hohen Dosis überlegen","Vorzeitiger Abbruch wegen Sicherheitssignalen"],"why":"Der Unterschied war nach einer Woche deutlich, nach sechs Wochen im Primärendpunkt nicht mehr signifikant."}]},{"id":"pr_episode12","track":"prak","level":1,"title":"EPIsoDE: 12 Monate danach","text":"Naturalistische Nachbeobachtung von 126 Teilnehmenden ohne Kontrollgruppe: Nach 12 Monaten lag der HAMD-17 im Mittel etwa 8 Punkte unter dem Ausgangswert.","facts":["Ohne Kontrollgruppe nicht von Regression zur Mitte, Spontanverlauf und Begleittherapie zu trennen"],"regions":[],"src":"Mertens et al., Psychother Psychosom 2026","mcq":[{"q":"Welche Einschränkung hat die 12-Monats-Nachbeobachtung von EPIsoDE?","a":"Es gibt keine Kontrollgruppe","w":["Nur sechs Teilnehmende","Keine standardisierte Skala","Nur App-basierte Selbstauskünfte"],"why":"Langzeitverläufe ohne Vergleich zeigen Stabilität, aber keinen kausalen Effekt."}]},{"id":"pr_cu","track":"prak","level":1,"title":"Härtefallprogramm am ZI (seit 2025)","text":"Erstes Compassionate-Use-Programm für Psilocybin in der EU: Antrag von Prof. Gründer beim BfArM, gemeldet im Juli 2025; ZI Mannheim und Tagesklinik der OVID Clinic Berlin. Für einzelne Erwachsene mit therapieresistenter Depression; stationär, mit Psychotherapie; Präparat PEX010 (Filament Health).","facts":["Voraussetzungen: schwere Erkrankung, keine zufriedenstellende zugelassene Therapie, keine Studienteilnahme möglich, Nutzen-Risiko-Abwägung im Einzelfall","Eine strukturierte Verlaufsdokumentation könnte Daten für spätere Auswertungen liefern"],"regions":[],"src":"ZI Mannheim, Mitteilung vom 31.07.2025","mcq":[{"q":"Welche Bedingung gehört NICHT zu den Voraussetzungen des Härtefallprogramms?","a":"Vorherige Teilnahme an EPIsoDE","w":["Keine Möglichkeit zur Studienteilnahme","Keine zufriedenstellende zugelassene Therapie","Schwere Erkrankung"],"why":"Die Kriterien betreffen Krankheitsschwere und fehlende Alternativen, nicht frühere Studienteilnahme."}]},{"id":"pr_an_peck","track":"prak","level":1,"title":"Anorexie: Peck et al. 2023","text":"Offene Phase-1-Studie mit 10 Frauen, eine Gabe plus Begleitung: machbar und weitgehend sicher (zwei Hypoglykämien). Nach 3 Monaten bei 4 von 10 klinisch bedeutsame Besserung der Essstörungs-Psychopathologie; Gewicht im Mittel unverändert.","facts":["Ziel war Machbarkeit und Sicherheit, nicht Wirksamkeit"],"regions":["insula","vmpfc","nacc"],"src":"Peck et al., Nat Med 2023","mcq":[{"q":"Welche unerwünschten Ereignisse fielen bei Peck 2023 auf?","a":"Hypoglykämien","w":["Hypertensive Krisen","Psychotische Episoden","Anhaltende Wahrnehmungsstörungen"],"why":"Bei Untergewicht ist der Glukosestoffwechsel störanfällig, ein ernährungsmedizinisch relevanter Punkt."}]},{"id":"pr_an_douglass","track":"prak","level":1,"title":"Anorexie: Douglass, Spriggs et al. 2026","text":"Pilotstudie ohne Kontrollgruppe mit 21 Frauen (mittlerer BMI 16,4), drei Sitzungen: Essstörungswerte sanken; nach 3 Monaten 48 % im Bereich ohne Essstörung; die Motivation zur Genesung stieg bis zu einem Jahr; der BMI änderte sich in den ersten sechs Wochen nicht.","facts":["Ohne Kontrollgruppe lassen sich Erwartung und Spontanverlauf nicht abgrenzen","Eine Teilnehmerin mit Suizidversuchen Monate später, nicht als substanzbedingt bewertet; hohe Grundrate bei Anorexie"],"regions":["insula","vmpfc"],"src":"Douglass, Spriggs et al., Br J Psychiatry 2026","mcq":[{"q":"Welche Aussage zu Douglass, Spriggs et al. 2026 trifft zu?","a":"Keine Kontrollgruppe, BMI in den ersten Wochen unverändert","w":["Placebokontrolliert mit deutlichem BMI-Anstieg","Nur Männer eingeschlossen","Primärer Endpunkt war Gewichtszunahme nach einem Jahr"],"why":"Die Pilotstudie zielte auf Machbarkeit; Wirksamkeit braucht kontrollierte Studien."}]},{"id":"pr_sex","track":"prak","level":1,"title":"Geschlechtsunterschiede: worauf achten","text":"Für dein Scoping Review: Viele Psilocybin-Studien berichten Ergebnisse nicht getrennt nach Geschlecht. Wichtige Variablen: feste vs. körpergewichtsbezogene Dosierung, Hormonstatus (Zyklus, Kontrazeption, Menopause), Vorerfahrung und Erwartung, Geschlecht der Begleitenden. Peer-reviewte Daten sind dünn; Reanalysen von 2026 liegen bisher nur als Preprints vor.","facts":["Die SAGER-Leitlinien fordern geschlechtsdifferenzierte Berichte","Sex (biologisch) und Gender (sozial) getrennt extrahieren"],"regions":[],"src":"Heidari et al., Res Integr Peer Rev 2016 (SAGER)","mcq":[{"q":"Welche Angabe gehört in einen Extraktionsbogen zu Geschlechtsunterschieden unbedingt?","a":"Ob nach Geschlecht getrennt berichtet oder analysiert wurde","w":["Die Musikplaylist der Sitzung","Die Dauer der Vorbereitungssitzung","Der Hersteller des Präparats"],"why":"Ohne getrennte Berichte lässt sich kein Unterschied kartieren; das ist oft schon ein Befund."}]},{"id":"pr_prisma","track":"prak","level":1,"title":"Scoping Review nach PRISMA-ScR und JBI","text":"Scoping Reviews kartieren Evidenz, statt Effekte zu poolen: PCC-Schema (Population, Concept, Context), vorab veröffentlichtes Protokoll, zwei unabhängige Screener, Charting mit pilotiertem Extraktionsbogen; eine Qualitätsbewertung ist nicht verpflichtend.","facts":["PRISMA-ScR hat 20 Pflicht- und 2 optionale Items","KI-gestützte Extraktion: als Zweitextraktor mit menschlicher Prüfung, Abweichungen dokumentieren"],"regions":[],"src":"Tricco et al., Ann Intern Med 2018; Peters et al., JBI Evid Synth 2020","mcq":[{"q":"Was unterscheidet ein Scoping Review grundsätzlich von einer Meta-Analyse?","a":"Es kartiert die Evidenz, statt Effekte zu poolen","w":["Es schließt nur RCTs ein","Es verzichtet auf eine systematische Suche","Es nutzt nur eine Datenbank"],"why":"Ziel ist ein Überblick über Umfang, Art und Lücken der Literatur."}]},{"id":"pr_glp","track":"prak","level":1,"title":"GLP-1 und Belohnung","text":"GLP-1-Rezeptoren in Hirnstamm, Hypothalamus und mesolimbischem System dämpfen im Tiermodell die Dopaminantwort auf Alkohol, Nikotin und andere Belohnungen. Klinisch: Exenatid ohne Gesamteffekt auf schwere Trinktage (Klausen 2022), Semaglutid mit weniger Trinken in einer kleinen RCT (Hendershot 2025).","facts":["Offene Fragen: Craving vs. Gewohnheit, Dauer, Auswahl der Patienten","Ernährungsmedizinisch: Appetit, Proteinzufuhr, Muskelerhalt"],"regions":["vta","nacc","hypothal","brainstem"],"src":"Klausen et al., JCI Insight 2022; Hendershot et al., JAMA Psychiatry 2025","mcq":[{"q":"Welche Aussage zur klinischen Evidenz von GLP-1-RA bei Alkoholkonsumstörung trifft zu?","a":"Gemischt: Exenatid ohne Gesamteffekt, Semaglutid positiv in kleiner RCT","w":["Große Phase-3-Studien belegen die Wirksamkeit","Alle Studien waren negativ","Es gibt nur Tierdaten"],"why":"Die Datenlage ist vielversprechend, aber klein; größere RCTs laufen."}]}],"story":[{"title":"Gesunde Regulation","text":"Präfrontale Areale (vmPFC, dlPFC) bewerten und dämpfen die Amygdala, der Hippocampus ordnet Erlebtes in den Kontext ein, und Cortisol bremst über Rückkopplung die Stressachse. So bleibt eine schlechte Nachricht eine schlechte Nachricht und wird nicht zum Dauerzustand.","regions":["vmpfc","dlpfc","amygdala","hippocampus"],"how":"focus"},{"title":"Was sich bei Depression verändert","text":"Der subgenuale ACC ist überaktiv, die Amygdala reagiert stärker auf negative Reize, das Hippocampusvolumen ist im Mittel kleiner, das ventrale Striatum antwortet schwächer auf Belohnung. Das Default-Mode-Netzwerk koppelt enger an den sgACC: Grübeln.","regions":[{"r":"sgacc","how":"hyper"},{"r":"amygdala","how":"hyper"},{"r":"hippocampus","how":"atrophy"},{"r":"nacc","how":"hypo"},{"r":"pcc","how":"dysconnect"}],"how":"hyper"},{"title":"Stressachse und Entzündung","text":"Bei einem Teil der Betroffenen ist die HPA-Achse dauerhaft aktiviert, und niedriggradige Entzündung (CRP, IL-6) lenkt Tryptophan in den Kynurenin-Weg und dämpft Dopamin. Hier setzen Ernährung, Bewegung und Schlaf an, mit realistisch kleinen Effekten.","regions":[{"r":"hypothal","how":"hyper"},{"r":"hypophyse_p","how":"hyper"},{"r":"microglia","how":"hyper"}],"how":"hyper"},{"title":"SSRI: langsamer Umbau","text":"SSRI blockieren SERT sofort. Erst wenn die 5-HT1A-Autorezeptoren der Raphe-Kerne nach Wochen desensibilisieren, steigt die Serotoninfreisetzung im Kortex dauerhaft, und Plastizität kommt in Gang. Effekt gegenüber Placebo: klein bis mittel (g ≈ 0,3).","regions":["raphe","sert","r5ht1a"],"how":"focus"},{"title":"Ketamin: schneller Glutamatschub","text":"Ketamin blockiert NMDA-Rezeptoren an GABAergen Interneuronen. Die Pyramidenzellen werden enthemmt, Glutamat aktiviert AMPA-Rezeptoren, BDNF und mTOR folgen, binnen Stunden bilden sich neue Synapsen. Die Wirkung kommt schnell, hält aber oft nur Tage.","regions":["nmda","interneuron","pyramidal","trkb"],"how":"focus"},{"title":"Psilocybin akut: 5-HT2A","text":"Psilocin aktiviert 5-HT2A-Rezeptoren auf Schicht-V-Pyramidenzellen. Das Default-Mode-Netzwerk lockert sich (PCC, mPFC), Netzwerke kommunizieren breiter miteinander. Das Erleben ist intensiv und wird deshalb in Studien eng begleitet.","regions":["r5ht2a","pyramidal","apical"],"how":"focus"},{"title":"Nach der Sitzung","text":"Im Tiermodell wachsen nach einer Gabe Dendritendornen über Wochen; diskutiert werden 5-HT2A, TrkB und ein geöffnetes Lernfenster. In der Therapie dient die Integration dazu, neue Perspektiven in den Alltag zu übertragen. Wie viel davon beim Menschen trägt, ist offen.","regions":["apical","trkb"],"how":"focus"},{"title":"Was die Studien zeigen","text":"Gegen Warteliste sehr große Effekte (Davis 2021), gegen Escitalopram Primärendpunkt verfehlt (2021), Phase 2b −6,6 MADRS-Punkte, die beiden Phase-3-Studien knapp −4 Punkte. Meta-analytisch g = 0,66 bei moderatem Verzerrungsrisiko. EPIsoDE: früher Effekt, Primärendpunkt nach 6 Wochen verfehlt.","regions":[],"how":"focus"},{"title":"Offene Fragen","text":"Wie stark blähen Entblindung und Erwartung die Effekte auf? Wie lange hält die Wirkung, und wer profitiert? Braucht es die Erfahrung? Wie sicher ist es außerhalb streng ausgewählter Studienpopulationen? Und unterscheiden sich Frauen und Männer?","regions":[],"how":"focus"},{"title":"Bezug zu deinem Praktikum","text":"EPIsoDE stammt aus der AG Gründer; seit 2025 läuft am ZI das erste Härtefallprogramm der EU. Dein Scoping Review zu Geschlechtsunterschieden setzt genau bei einer der offenen Fragen an, und GLP-1-Agonisten verbinden Belohnung mit deinem Fach Ernährungsmedizin.","regions":["vta","nacc"],"how":"focus"}]};
